(window.theoremosProcesses??={})["annals_improved_bounds_sunflower_lemma"]={"runs":[],"sourceRoute":{"files":[{"name":"Submission/Helpers.lean","path":"submitted/annals_improved_bounds_sunflower_lemma/Submission/Helpers.lean","sha256":"9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42","recordSource":true,"declarations":[{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:388","name":"Submission.Helpers.isSunflower_preimage_equiv","kind":"theorem","type":"isSunflower_preimage_equiv {X Y : Type*} (e : X ≃ Y) {r : ℕ} {S : Set (Set Y)} (hS : Set.IsSunflower r S) : Set.IsSunflower r (Set.preimage e '' S)","line":13,"endLine":21,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:554","line":15,"endLine":16,"code":" by\n  refine ⟨?_, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:576","line":17,"endLine":18,"code":"  · rw [Set.ncard_image_of_injective S (Set.preimage_injective.mpr e.surjective)]\n    exact hS.1\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:673","line":19,"endLine":21,"code":"  · rintro _ ⟨A, hA, rfl⟩ _ ⟨B, hB, rfl⟩ hAB\n    have hne : A ≠ B := fun h ↦ hAB (congrArg (Set.preimage e) h)\n    rw [← Set.preimage_inter, hS.2 hA hB hne, Set.preimage_sInter, Set.sInter_image]\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:869","name":"Submission.Helpers.transfer_from_numbered_ground_sets","kind":"theorem","type":"transfer_from_numbered_ground_sets (c : ℝ) (hc : ∀ (r : ℕ), 3 ≤ r → ∀ (n : ℕ) (ℱ : Set (Set (Fin n))) (w : ℕ), 2 ≤ w → Set.IsSystem w ℱ → _root_.ImprovedBoundsSunflowerLemma.lowerBound r c w ≤ (ℱ.ncard : ℝ) → ∃ S ⊆ ℱ, Set.IsSunflower r S) (r : ℕ) (hr : 3 ≤ r) (X : Type*) [Finite X] (ℱ : Set (Set X)) (w : ℕ) (hw : 2 ≤ w) (hℱ₁ : Set.IsSystem w ℱ) (hℱ₂ : _root_.ImprovedBoundsSunflowerLemma.lowerBound r c w ≤ (ℱ.ncard : ℝ)) : ∃ S ⊆ ℱ, Set.IsSunflower r S","line":22,"endLine":49,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:388"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:1376","line":31,"endLine":32,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:1392","line":33,"endLine":33,"code":"  letI := Fintype.ofFinite X\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:1421","line":34,"endLine":34,"code":"  let e : X ≃ Fin (Fintype.card X) := Fintype.equivFin X\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:1478","line":35,"endLine":35,"code":"  let ℱ' : Set (Set (Fin (Fintype.card X))) := Set.image (Set.image e) ℱ\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:1551","line":36,"endLine":39,"code":"  have hℱ₁' : Set.IsSystem w ℱ' := by\n    rintro _ ⟨A, hA, rfl⟩\n    rw [Set.ncard_image_of_injective A e.injective]\n    exact hℱ₁ A hA\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:1686","line":40,"endLine":44,"code":"  have hℱ₂' :\n      _root_.ImprovedBoundsSunflowerLemma.lowerBound r c w ≤ (ℱ'.ncard : ℝ) := by\n    change _ ≤ ((Set.image (Set.image e) ℱ).ncard : ℝ)\n    rw [Set.ncard_image_of_injective ℱ e.injective.image_injective]\n    exact hℱ₂\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:1919","line":45,"endLine":45,"code":"  obtain ⟨S, hSℱ, hS⟩ := hc r hr (Fintype.card X) ℱ' w hw hℱ₁' hℱ₂'\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:1987","line":46,"endLine":46,"code":"  refine ⟨Set.preimage e '' S, ?_, isSunflower_preimage_equiv e hS⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2055","line":47,"endLine":47,"code":"  rintro _ ⟨A, hA, rfl⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2079","line":48,"endLine":48,"code":"  obtain ⟨B, hB, hBA⟩ := hSℱ hA\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2111","line":49,"endLine":49,"code":"  simpa only [← hBA, Set.preimage_image_eq B e.injective] using hB\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2178","name":"Submission.Helpers.one_lt_logb_of_two_le","kind":"theorem","type":"one_lt_logb_of_two_le (w : ℕ) (hw : 2 ≤ w) : 1 < Real.logb (1.9 : ℝ) (w : ℝ)","line":50,"endLine":55,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2269","line":51,"endLine":52,"code":" by\n  have hwR : (2 : ℝ) ≤ (w : ℝ) := by exact_mod_cast hw\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2328","line":53,"endLine":54,"code":"  apply (Real.lt_logb_iff_rpow_lt (by norm_num : (1 : ℝ) < 1.9)\n    (by linarith : 0 < (w : ℝ))).2\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2427","line":55,"endLine":55,"code":"  simpa using (lt_of_lt_of_le (by norm_num : (1.9 : ℝ) < 2) hwR)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2492","name":"Submission.Helpers.positive_log_factors","kind":"theorem","type":"positive_log_factors (w : ℕ) (hw : 2 ≤ w) : 0 < Real.logb (1.9 : ℝ) (w : ℝ) ∧ 0 < Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ))","line":56,"endLine":60,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2178"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2644","line":58,"endLine":59,"code":" by\n  have hlog := one_lt_logb_of_two_le w hw\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2690","line":60,"endLine":60,"code":"  exact ⟨lt_trans zero_lt_one hlog, Real.logb_pos (by norm_num) hlog⟩\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2760","name":"Submission.Helpers.rational_log_factors_lower_bounds","kind":"theorem","type":"rational_log_factors_lower_bounds (w : ℕ) (hw : 2 ≤ w) : (15 / 14 : ℝ) ≤ Real.logb (1.9 : ℝ) (w : ℝ) ∧ (1 / 10 : ℝ) ≤ Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ))","line":61,"endLine":81,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2948","line":63,"endLine":64,"code":" by\n  have hb : (1 : ℝ) < 1.9 := by norm_num\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2993","line":65,"endLine":65,"code":"  have hpow₁ : (1.9 : ℝ) ^ 15 ≤ (2 : ℝ) ^ 14 := by norm_num\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3053","line":66,"endLine":67,"code":"  have h₁ := Real.logb_le_logb_of_le hb\n    (pow_pos (by norm_num : (0 : ℝ) < 1.9) 15) hpow₁\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3146","line":68,"endLine":68,"code":"  rw [Real.logb_pow, Real.logb_pow, Real.logb_self_eq_one hb] at h₁\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3214","line":69,"endLine":69,"code":"  have hwR : (2 : ℝ) ≤ (w : ℝ) := by exact_mod_cast hw\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3269","line":70,"endLine":70,"code":"  have hmono₁ := Real.logb_le_logb_of_le hb (by norm_num : (0 : ℝ) < 2) hwR\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3345","line":71,"endLine":73,"code":"  have hfirst : (15 / 14 : ℝ) ≤ Real.logb (1.9 : ℝ) (w : ℝ) := by\n    norm_num at h₁\n    linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3443","line":74,"endLine":74,"code":"  refine ⟨hfirst, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3465","line":75,"endLine":75,"code":"  have hpow₂ : (1.9 : ℝ) ≤ (15 / 14 : ℝ) ^ 10 := by norm_num\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3526","line":76,"endLine":76,"code":"  have h₂ := Real.logb_le_logb_of_le hb (by norm_num : (0 : ℝ) < 1.9) hpow₂\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3602","line":77,"endLine":77,"code":"  rw [Real.logb_self_eq_one hb, Real.logb_pow] at h₂\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3655","line":78,"endLine":79,"code":"  have hmono₂ := Real.logb_le_logb_of_le hb\n    (by norm_num : (0 : ℝ) < 15 / 14) hfirst\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3744","line":80,"endLine":80,"code":"  norm_num at h₂\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3761","line":81,"endLine":81,"code":"  linarith\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3772","name":"Submission.Helpers.log_product_lower_bound","kind":"theorem","type":"log_product_lower_bound (w : ℕ) (hw : 2 ≤ w) : (3 / 28 : ℝ) ≤ Real.logb (1.9 : ℝ) (w : ℝ) * Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ))","line":82,"endLine":90,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2760"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:3934","line":84,"endLine":85,"code":" by\n  obtain ⟨hfirst, hsecond⟩ := rational_log_factors_lower_bounds w hw\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4007","line":86,"endLine":90,"code":"  calc\n    (3 / 28 : ℝ) = (15 / 14 : ℝ) * (1 / 10 : ℝ) := by norm_num\n    _ ≤ Real.logb (1.9 : ℝ) (w : ℝ) *\n        Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ)) :=\n      mul_le_mul hfirst hsecond (by norm_num) (le_trans (by norm_num) hfirst)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4254","name":"Submission.Helpers.minimal_fragment_decode","kind":"theorem","type":"minimal_fragment_decode {X ι : Type*} [Finite X] (f : ι → Set X) (i j j₀ : ι) (W : Set X) (t : ℕ) (hj : f j ⊆ f i ∪ W) (ht : (f j \\ W).ncard = t) (hmin : ∀ a, f a ⊆ f i ∪ W → t ≤ (f a \\ W).ncard) (h₀ : f j₀ ⊆ W ∪ (f j \\ W)) : f j₀ \\ W = f j \\ W","line":91,"endLine":107,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4525","line":95,"endLine":100,"code":" by\n  have hsub : f j₀ \\ W ⊆ f j \\ W := by\n    intro x hx\n    rcases h₀ hx.1 with hxW | hxT\n    · exact False.elim (hx.2 hxW)\n    · exact hxT\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4667","line":101,"endLine":101,"code":"  apply Set.eq_of_subset_of_ncard_le hsub\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4709","line":102,"endLine":102,"code":"  rw [ht]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4719","line":103,"endLine":103,"code":"  apply hmin j₀\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4735","line":104,"endLine":104,"code":"  intro x hx\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4748","line":105,"endLine":105,"code":"  rcases h₀ hx with hxW | hxT\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4778","line":106,"endLine":106,"code":"  · exact Or.inr hxW\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4799","line":107,"endLine":107,"code":"  · exact hj hxT.1\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4818","name":"Submission.Helpers.ncard_mul_le_of_fiber_bounds","kind":"theorem","type":"ncard_mul_le_of_fiber_bounds {α β : Type*} [Fintype α] [Fintype β] (s : Set α) (t : Set β) (f : α → β) (a b : ℝ) (hf : ∀ x ∈ s, f x ∈ t) (hb : ∀ y ∈ t, ({x | x ∈ s ∧ f x = y}.ncard : ℝ) * a ≤ b) : (s.ncard : ℝ) * a ≤ (t.ncard : ℝ) * b","line":108,"endLine":132,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:5079","line":112,"endLine":113,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:5095","line":114,"endLine":118,"code":"  have hc := Finset.card_eq_sum_card_fiberwise\n    (s := s.toFinset) (t := t.toFinset) (f := f)\n    (by\n      intro x hx\n      simpa using hf x (by simpa using hx))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:5260","line":119,"endLine":122,"code":"  have he (y : β) :\n      {x | x ∈ s ∧ f x = y}.toFinset = {x ∈ s.toFinset | f x = y} := by\n    ext x\n    simp\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:5371","line":123,"endLine":126,"code":"  have hc' : (s.ncard : ℝ) =\n      ∑ y ∈ t.toFinset, ({x | x ∈ s ∧ f x = y}.ncard : ℝ) := by\n    simp_rw [Set.ncard_eq_toFinset_card', he]\n    exact_mod_cast hc\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:5532","line":127,"endLine":132,"code":"  calc\n    (s.ncard : ℝ) * a =\n        ∑ y ∈ t.toFinset, ({x | x ∈ s ∧ f x = y}.ncard : ℝ) * a := by\n      rw [← Finset.sum_mul, ← hc']\n    _ ≤ ∑ _y ∈ t.toFinset, b := Finset.sum_le_sum fun y hy ↦ hb y (by simpa using hy)\n    _ = (t.ncard : ℝ) * b := by simp [Set.ncard_eq_toFinset_card']\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:5821","name":"Submission.Helpers.maximal_weighted_link","kind":"theorem","type":"maximal_weighted_link (n w : ℕ) (ℱ : Set (Set (Fin n))) (κ : ℝ) (hκ : 2 ≤ κ) (hsys : Set.IsSystem w ℱ) (hsize : κ ^ w < (ℱ.ncard : ℝ)) : ∃ T : Set (Fin n), 2 ≤ {A : Set (Fin n) | A ∈ ℱ ∧ T ⊆ A}.ncard ∧ ∀ U : Set (Fin n), ({A : Set (Fin n) | A ∈ ℱ ∧ U ⊆ A}.ncard : ℝ) * κ ^ U.ncard ≤ ({A : Set (Fin n) | A ∈ ℱ ∧ T ⊆ A}.ncard : ℝ) * κ ^ T.ncard","line":133,"endLine":163,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:6212","line":139,"endLine":140,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:6228","line":141,"endLine":141,"code":"  letI := Fintype.ofFinite (Set (Fin n))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:6269","line":142,"endLine":142,"code":"  let L (T : Set (Fin n)) : Set (Set (Fin n)) := {A | A ∈ ℱ ∧ T ⊆ A}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:6338","line":143,"endLine":143,"code":"  let score (T : Set (Fin n)) : ℝ := (L T).ncard * κ ^ T.ncard\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:6401","line":144,"endLine":144,"code":"  obtain ⟨T, _, hmax⟩ := Finset.exists_max_image Finset.univ score Finset.univ_nonempty\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:6489","line":145,"endLine":145,"code":"  have hmax' (U : Set (Fin n)) : score U ≤ score T := hmax U (Finset.mem_univ U)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:6570","line":146,"endLine":146,"code":"  have hbot : score ∅ = (ℱ.ncard : ℝ) := by simp [score, L]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:6630","line":147,"endLine":147,"code":"  have hlarge : κ ^ w < score T := lt_of_lt_of_le hsize (hbot ▸ hmax' ∅)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:6703","line":148,"endLine":148,"code":"  have hκpos : 0 < κ := by linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:6739","line":149,"endLine":149,"code":"  have hscorepos : 0 < score T := lt_trans (pow_pos hκpos w) hlarge\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:6807","line":150,"endLine":153,"code":"  have hLpos : 0 < (L T).ncard := by\n    by_contra h\n    have hzero : (L T).ncard = 0 := Nat.eq_zero_of_not_pos h\n    simp [score, hzero] at hscorepos\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:6958","line":154,"endLine":154,"code":"  obtain ⟨A, hA⟩ := (Set.ncard_pos (Set.toFinite (L T))).mp hLpos\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:7024","line":155,"endLine":155,"code":"  have hTcard : T.ncard ≤ w := le_trans (Set.ncard_le_ncard hA.2) (hsys A hA.1)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:7104","line":156,"endLine":162,"code":"  have htwo : 2 ≤ (L T).ncard := by\n    by_contra h\n    have hle : ((L T).ncard : ℝ) ≤ 1 := by exact_mod_cast (by omega : (L T).ncard ≤ 1)\n    have hscorele : score T ≤ κ ^ T.ncard := by\n      simpa [score] using mul_le_mul_of_nonneg_right hle (le_of_lt (pow_pos hκpos T.ncard))\n    have hpowle : κ ^ T.ncard ≤ κ ^ w := pow_le_pow_right₀ (by linarith) hTcard\n    exact (not_lt_of_ge (hscorele.trans hpowle)) hlarge\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:7519","line":163,"endLine":163,"code":"  exact ⟨T, htwo, hmax'⟩\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:7544","name":"Submission.Helpers.extract_spread_petals","kind":"theorem","type":"extract_spread_petals (n w : ℕ) (ℱ : Set (Set (Fin n))) (κ : ℝ) (hκ : 2 ≤ κ) (hsys : Set.IsSystem w ℱ) (hsize : κ ^ w < (ℱ.ncard : ℝ)) : ∃ (T : Set (Fin n)) (ℋ : Set (Set (Fin n))), ℋ.Nonempty ∧ (∅ : Set (Fin n)) ∉ ℋ ∧ Set.IsSystem w ℋ ∧ (∀ A ∈ ℋ, Disjoint T A ∧ T ∪ A ∈ ℱ) ∧ (∀ U : Set (Fin n), ({A : Set (Fin n) | A ∈ ℋ ∧ U ⊆ A}.ncard : ℝ) * (κ / 2) ^ U.ncard ≤ (ℋ.ncard : ℝ))","line":164,"endLine":268,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:5821"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:7977","line":171,"endLine":172,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:7993","line":173,"endLine":173,"code":"  obtain ⟨T, htwo, hmax⟩ := maximal_weighted_link n w ℱ κ hκ hsys hsize\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:8065","line":174,"endLine":174,"code":"  let L (U : Set (Fin n)) : Set (Set (Fin n)) := {A | A ∈ ℱ ∧ U ⊆ A}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:8134","line":175,"endLine":175,"code":"  let G : Set (Set (Fin n)) := (fun A : Set (Fin n) ↦ A \\ T) '' L T\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:8202","line":176,"endLine":176,"code":"  let ℋ : Set (Set (Fin n)) := G \\ {∅}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:8241","line":177,"endLine":177,"code":"  have hκpos : 0 < κ := by linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:8277","line":178,"endLine":180,"code":"  have hrec (A : Set (Fin n)) (hA : A ∈ L T) : T ∪ (A \\ T) = A := by\n    rw [Set.union_comm]\n    exact Set.sdiff_union_of_subset hA.2\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:8411","line":181,"endLine":186,"code":"  have hinj : Set.InjOn (fun A : Set (Fin n) ↦ A \\ T) (L T) := by\n    intro A hA B hB hAB\n    calc\n      A = T ∪ (A \\ T) := (hrec A hA).symm\n      _ = T ∪ (B \\ T) := congrArg (fun U ↦ T ∪ U) hAB\n      _ = B := hrec B hB\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:8631","line":187,"endLine":187,"code":"  have hGcard : G.ncard = (L T).ncard := hinj.ncard_image\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:8689","line":188,"endLine":195,"code":"  have hHcard : (L T).ncard ≤ ℋ.ncard + 1 := by\n    rw [← hGcard]\n    have hsub : G ⊆ insert (∅ : Set (Fin n)) ℋ := by\n      intro A hA\n      by_cases he : A = ∅\n      · exact Or.inl he\n      · exact Or.inr ⟨hA, by simpa using he⟩\n    exact (Set.ncard_le_ncard hsub).trans (Set.ncard_insert_le _ _)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:8988","line":196,"endLine":196,"code":"  have hHpos : 0 < ℋ.ncard := by change 2 ≤ (L T).ncard at htwo; omega\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:9059","line":197,"endLine":199,"code":"  have hhalf : ((L T).ncard : ℝ) ≤ 2 * (ℋ.ncard : ℝ) := by\n    have hnat : (L T).ncard ≤ 2 * ℋ.ncard := by omega\n    exact_mod_cast hnat\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:9196","line":200,"endLine":203,"code":"  have hproperties (A : Set (Fin n)) (hA : A ∈ ℋ) :\n      Disjoint T A ∧ T ∪ A ∈ ℱ := by\n    obtain ⟨B, hB, rfl⟩ := hA.1\n    exact ⟨Set.disjoint_sdiff_right, (hrec B hB).symm ▸ hB.1⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:9379","line":204,"endLine":207,"code":"  have hsysH : Set.IsSystem w ℋ := by\n    intro A hA\n    obtain ⟨B, hB, rfl⟩ := hA.1\n    exact (Set.ncard_le_ncard Set.sdiff_subset).trans (hsys B hB.1)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:9532","line":208,"endLine":209,"code":"  refine ⟨T, ℋ, (Set.ncard_pos (Set.toFinite ℋ)).mp hHpos, ?_, hsysH,\n    hproperties, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:9623","line":210,"endLine":210,"code":"  · simp [ℋ]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:9636","line":211,"endLine":268,"code":"  · intro U\n    by_cases hU : U = ∅\n    · simp [hU]\n    by_cases hdis : Disjoint T U\n    · let K : Set (Set (Fin n)) := {A | A ∈ ℋ ∧ U ⊆ A}\n      have hrecovery (A : Set (Fin n)) (hA : A ∈ ℋ) : (T ∪ A) \\ T = A := by\n        ext x\n        constructor\n        · intro hx\n          exact hx.1.resolve_left hx.2\n        · intro hx\n          exact ⟨Or.inr hx, fun hxT ↦ Set.disjoint_left.mp (hproperties A hA).1 hxT hx⟩\n      have hrootinj : Set.InjOn (fun A : Set (Fin n) ↦ T ∪ A) K := by\n        intro A hA B hB hAB\n        calc\n          A = (T ∪ A) \\ T := (hrecovery A hA.1).symm\n          _ = (T ∪ B) \\ T := congrArg (fun D ↦ D \\ T) hAB\n          _ = B := hrecovery B hB.1\n      have hrootmap : (fun A : Set (Fin n) ↦ T ∪ A) '' K ⊆ L (T ∪ U) := by\n        rintro _ ⟨A, hA, rfl⟩\n        refine ⟨(hproperties A hA.1).2, ?_⟩\n        intro x hx\n        exact hx.elim Or.inl (fun hxU ↦ Or.inr (hA.2 hxU))\n      have hKcard : K.ncard ≤ (L (T ∪ U)).ncard := by\n        rw [← hrootinj.ncard_image]\n        exact Set.ncard_le_ncard hrootmap\n      have hfull : ((L (T ∪ U)).ncard : ℝ) * κ ^ U.ncard ≤ ((L T).ncard : ℝ) := by\n        apply (mul_le_mul_iff_left₀ (pow_pos hκpos T.ncard)).mp\n        calc\n          ((L (T ∪ U)).ncard : ℝ) * κ ^ U.ncard * κ ^ T.ncard =\n              ((L (T ∪ U)).ncard : ℝ) * κ ^ (T ∪ U).ncard := by\n            rw [Set.ncard_union_eq hdis, pow_add]\n            ring\n          _ ≤ ((L T).ncard : ℝ) * κ ^ T.ncard := hmax (T ∪ U)\n      have hcount : (K.ncard : ℝ) * κ ^ U.ncard ≤ ((L T).ncard : ℝ) := by\n        exact (mul_le_mul_of_nonneg_right (by exact_mod_cast hKcard)\n          (le_of_lt (pow_pos hκpos U.ncard))).trans hfull\n      have hUpos : 1 ≤ U.ncard := by\n        exact (Set.ncard_pos (Set.toFinite U)).mpr (Set.nonempty_iff_ne_empty.mpr hU)\n      have hpowtwo : (2 : ℝ) ≤ (2 : ℝ) ^ U.ncard := by\n        simpa using (pow_le_pow_right₀ (by norm_num : (1 : ℝ) ≤ 2) hUpos)\n      have hpow : 2 * (κ / 2) ^ U.ncard ≤ κ ^ U.ncard := by\n        calc\n          2 * (κ / 2) ^ U.ncard ≤ (2 : ℝ) ^ U.ncard * (κ / 2) ^ U.ncard :=\n            mul_le_mul_of_nonneg_right hpowtwo (pow_nonneg (by linarith) _)\n          _ = (2 * (κ / 2)) ^ U.ncard := (mul_pow _ _ _).symm\n          _ = κ ^ U.ncard := by congr 1; ring\n      have hscaled := mul_le_mul_of_nonneg_left hpow (Nat.cast_nonneg K.ncard : (0 : ℝ) ≤ K.ncard)\n      change (K.ncard : ℝ) * (κ / 2) ^ U.ncard ≤ (ℋ.ncard : ℝ)\n      nlinarith\n    · have hzero : {A : Set (Fin n) | A ∈ ℋ ∧ U ⊆ A} = ∅ := by\n        apply Set.eq_empty_iff_forall_notMem.mpr\n        intro A hA\n        apply hdis\n        exact Set.disjoint_left.mpr fun x hxT hxU ↦\n          Set.disjoint_left.mp (hproperties A hA.1).1 hxT (hA.2 hxU)\n      rw [hzero]\n      simp\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:12347","name":"Submission.Helpers.codegree_bound_of_injective_shrinking","kind":"theorem","type":"codegree_bound_of_injective_shrinking {X ι ι' : Type*} [Finite X] [Finite ι] [Finite ι'] (f : ι → Set X) (g : ι' → Set X) (e : ι' → ι) (he : Function.Injective e) (hgf : ∀ i, g i ⊆ f (e i)) (κ N : ℝ) (hκ : 0 ≤ κ) (hbound : ∀ U : Set X, ({i : ι | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) : ∀ U : Set X, ({i : ι' | U ⊆ g i}.ncard : ℝ) * κ ^ U.ncard ≤ N","line":269,"endLine":283,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:12736","line":276,"endLine":277,"code":" by\n  intro U\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:12750","line":278,"endLine":281,"code":"  have hc : {i : ι' | U ⊆ g i}.ncard ≤ {i : ι | U ⊆ f i}.ncard :=\n    Set.ncard_le_ncard_of_injOn e\n      (fun i hi ↦ Set.Subset.trans hi (hgf i))\n      (fun i _ j _ hij ↦ he hij)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:12930","line":282,"endLine":283,"code":"  exact (mul_le_mul_of_nonneg_right (by exact_mod_cast hc)\n    (pow_nonneg hκ _)).trans (hbound U)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13029","name":"Submission.Helpers.fragment_shrinks_current_edge","kind":"theorem","type":"fragment_shrinks_current_edge {X ι : Type*} (f : ι → Set X) (i j : ι) (W : Set X) (hj : f j ⊆ f i ∪ W) : f j \\ W ⊆ f i","line":284,"endLine":290,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13166","line":286,"endLine":287,"code":" by\n  intro x hx\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13183","line":288,"endLine":288,"code":"  rcases hj hx.1 with hxi | hxW\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13215","line":289,"endLine":289,"code":"  · exact hxi\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13229","line":290,"endLine":290,"code":"  · exact False.elim (hx.2 hxW)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13261","name":"Submission.Helpers.fragment_preserves_existential_provenance","kind":"theorem","type":"fragment_preserves_existential_provenance {X ι : Type*} (ℱ : Set (Set X)) (f : ι → Set X) (Wold W : Set X) (j : ι) (hprov : ∀ i, ∃ A ∈ ℱ, A ⊆ f i ∪ Wold) : ∃ A ∈ ℱ, A ⊆ (f j \\ W) ∪ (Wold ∪ W)","line":291,"endLine":302,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13475","line":294,"endLine":295,"code":" by\n  obtain ⟨A, hA, hsub⟩ := hprov j\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13513","line":296,"endLine":296,"code":"  refine ⟨A, hA, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13534","line":297,"endLine":297,"code":"  intro x hx\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13547","line":298,"endLine":298,"code":"  rcases hsub hx with hxj | hxold\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13581","line":299,"endLine":301,"code":"  · by_cases hxW : x ∈ W\n    · exact Or.inr (Or.inr hxW)\n    · exact Or.inl ⟨hxj, hxW⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13668","line":302,"endLine":302,"code":"  · exact Or.inr (Or.inl hxold)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13700","name":"Submission.Helpers.fragment_code_fiber_bound","kind":"theorem","type":"fragment_code_fiber_bound {X ι : Type*} [Finite X] [Fintype ι] (f : ι → Set X) (s : Set (ι × Set X)) (T : ι × Set X → Set X) (Z E : Set X) (k t : ℕ) (κ N : ℝ) (hκ : 0 ≤ κ) (hN : 0 ≤ N) (hE : E.ncard ≤ k) (hcode : ∀ U : Set X, ({i : ι | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) (hZ : ∀ p ∈ s, p.2 ∪ T p = Z) (hdis : ∀ p ∈ s, Disjoint p.2 (T p)) (hTE : ∀ p ∈ s, T p ⊆ E) (ht : ∀ p ∈ s, (T p).ncard = t) (hf : ∀ p ∈ s, T p ⊆ f p.1) : (s.ncard : ℝ) * κ ^ t ≤ (k.choose t : ℝ) * N","line":303,"endLine":348,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4818"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:14224","line":313,"endLine":314,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:14240","line":315,"endLine":315,"code":"  letI := Fintype.ofFinite (Set X)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:14275","line":316,"endLine":330,"code":"  have hrecover (A : Set X) (p : ι × Set X) (hp : p ∈ s) (hA : T p = A) :\n      p.2 = Z \\ A := by\n    ext x\n    constructor\n    · intro hx\n      refine ⟨?_, ?_⟩\n      · rw [← hZ p hp]\n        exact Or.inl hx\n      · intro hxA\n        exact Set.disjoint_left.mp (hdis p hp) hx (by simpa only [hA] using hxA)\n    · rintro ⟨hxZ, hxA⟩\n      rw [← hZ p hp] at hxZ\n      rcases hxZ with hxW | hxT\n      · exact hxW\n      · exact False.elim (hxA (by simpa only [hA] using hxT))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:14746","line":331,"endLine":343,"code":"  have hbound (A : Set X) (hA : A ⊆ E ∧ A.ncard = t) :\n      ({p | p ∈ s ∧ T p = A}.ncard : ℝ) * κ ^ t ≤ N := by\n    have hc : {p | p ∈ s ∧ T p = A}.ncard ≤ {i : ι | A ⊆ f i}.ncard := by\n      apply Set.ncard_le_ncard_of_injOn Prod.fst\n      · intro p hp\n        change A ⊆ f p.1\n        simpa only [← hp.2] using hf p hp.1\n      · intro p hp q hq hpq\n        apply Prod.ext hpq\n        exact (hrecover A p hp.1 hp.2).trans (hrecover A q hq.1 hq.2).symm\n    rw [← hA.2]\n    exact (mul_le_mul_of_nonneg_right (by exact_mod_cast hc)\n      (pow_nonneg hκ _)).trans (hcode A)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:15318","line":344,"endLine":345,"code":"  have hsum := ncard_mul_le_of_fiber_bounds s {A : Set X | A ⊆ E ∧ A.ncard = t}\n    T (κ ^ t) N (fun p hp ↦ ⟨hTE p hp, ht p hp⟩) hbound\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:15454","line":346,"endLine":346,"code":"  rw [Set.ncard_powerset_ncard (Set.toFinite E) t] at hsum\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:15513","line":347,"endLine":348,"code":"  exact hsum.trans (mul_le_mul_of_nonneg_right\n    (by exact_mod_cast Nat.choose_le_choose t hE) hN)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:15614","name":"Submission.Helpers.minimal_fragment_count","kind":"theorem","type":"minimal_fragment_count (n d k m t : ℕ) (V : Set (Fin n)) (f : Fin d → Set (Fin n)) (κ N : ℝ) (hκ : 0 < κ) (hN : 0 ≤ N) (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ k) (hcode : ∀ U : Set (Fin n), ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) : ({p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧ (∀ j : Fin d, f j ⊆ f p.1 ∪ p.2 → t ≤ (f j \\ p.2).ncard) ∧ (∃ j : Fin d, f j ⊆ f p.1 ∪ p.2 ∧ (f j \\ p.2).ncard = t)}.ncard : ℝ) * κ ^ t ≤ (V.ncard.choose (m + t) : ℝ) * (k.choose t : ℝ) * N","line":349,"endLine":427,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13029","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13700","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4254","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4818"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:16164","line":358,"endLine":359,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:16180","line":360,"endLine":360,"code":"  letI := Fintype.ofFinite (Set (Fin n))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:16221","line":361,"endLine":364,"code":"  let S : Set (Fin d × Set (Fin n)) := {p |\n    p.2 ⊆ V ∧ p.2.ncard = m ∧\n    (∀ a : Fin d, f a ⊆ f p.1 ∪ p.2 → t ≤ (f a \\ p.2).ncard) ∧\n    (∃ a : Fin d, f a ⊆ f p.1 ∪ p.2 ∧ (f a \\ p.2).ncard = t)}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:16420","line":365,"endLine":367,"code":"  let j (p : Fin d × Set (Fin n)) : Fin d :=\n    if h : ∃ a : Fin d, f a ⊆ f p.1 ∪ p.2 ∧ (f a \\ p.2).ncard = t\n    then Classical.choose h else p.1\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:16568","line":368,"endLine":373,"code":"  have hj (p : Fin d × Set (Fin n)) (hp : p ∈ S) :\n      f (j p) ⊆ f p.1 ∪ p.2 ∧ (f (j p) \\ p.2).ncard = t := by\n    dsimp [j]\n    split_ifs with h\n    · exact Classical.choose_spec h\n    · exact False.elim (h hp.2.2.2)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:16788","line":374,"endLine":374,"code":"  let T (p : Fin d × Set (Fin n)) : Set (Fin n) := f (j p) \\ p.2\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:16853","line":375,"endLine":375,"code":"  let Z (p : Fin d × Set (Fin n)) : Set (Fin n) := p.2 ∪ T p\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:16914","line":376,"endLine":377,"code":"  have hTcard (p : Fin d × Set (Fin n)) (hp : p ∈ S) : (T p).ncard = t :=\n    (hj p hp).2\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:17004","line":378,"endLine":379,"code":"  have hTsub (p : Fin d × Set (Fin n)) (hp : p ∈ S) : T p ⊆ f p.1 :=\n    fragment_shrinks_current_edge f p.1 (j p) p.2 (hj p hp).1\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:17135","line":380,"endLine":381,"code":"  have hTdis (p : Fin d × Set (Fin n)) : Disjoint p.2 (T p) :=\n    Set.disjoint_sdiff_right\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:17227","line":382,"endLine":386,"code":"  have hmaps (p : Fin d × Set (Fin n)) (hp : p ∈ S) :\n      Z p ⊆ V ∧ (Z p).ncard = m + t := by\n    refine ⟨Set.union_subset hp.1 (Set.sdiff_subset.trans (hsys (j p)).1), ?_⟩\n    change (p.2 ∪ T p).ncard = m + t\n    rw [Set.ncard_union_eq (hTdis p), hp.2.1, hTcard p hp]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:17498","line":387,"endLine":391,"code":"  have hedge (p : Fin d × Set (Fin n)) : f (j p) ⊆ Z p := by\n    intro x hx\n    by_cases hxW : x ∈ p.2\n    · exact Or.inl hxW\n    · exact Or.inr ⟨hx, hxW⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:17653","line":392,"endLine":422,"code":"  have hbound (Z₀ : Set (Fin n)) (_hZ₀ : Z₀ ⊆ V ∧ Z₀.ncard = m + t) :\n      ({p | p ∈ S ∧ Z p = Z₀}.ncard : ℝ) * κ ^ t ≤ (k.choose t : ℝ) * N := by\n    let sZ : Set (Fin d × Set (Fin n)) := {p | p ∈ S ∧ Z p = Z₀}\n    change (sZ.ncard : ℝ) * κ ^ t ≤ (k.choose t : ℝ) * N\n    by_cases hne : sZ.Nonempty\n    · obtain ⟨p₀, hp₀⟩ := hne\n      have hcanonical : f (j p₀) ⊆ Z₀ := by\n        rw [← hp₀.2]\n        exact hedge p₀\n      apply fragment_code_fiber_bound f sZ T Z₀ (f (j p₀)) k t κ N\n        (le_of_lt hκ) hN (hsys (j p₀)).2 hcode\n      · intro p hp\n        exact hp.2\n      · intro p _hp\n        exact hTdis p\n      · intro p hp\n        have hdecode : f (j p₀) \\ p.2 = T p := by\n          apply minimal_fragment_decode f p.1 (j p) (j p₀) p.2 t\n            (hj p hp.1).1 (hj p hp.1).2 hp.1.2.2.1\n          change f (j p₀) ⊆ Z p\n          rw [hp.2]\n          exact hcanonical\n        rw [← hdecode]\n        exact Set.sdiff_subset\n      · intro p hp\n        exact hTcard p hp.1\n      · intro p hp\n        exact hTsub p hp.1\n    · have hzero : sZ = ∅ := Set.not_nonempty_iff_eq_empty.mp hne\n      simpa only [hzero, Set.ncard_empty, Nat.cast_zero, zero_mul] using\n        mul_nonneg (Nat.cast_nonneg (k.choose t) : (0 : ℝ) ≤ k.choose t) hN\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:18892","line":423,"endLine":425,"code":"  have hsum := ncard_mul_le_of_fiber_bounds S\n    {Z₀ : Set (Fin n) | Z₀ ⊆ V ∧ Z₀.ncard = m + t} Z\n    (κ ^ t) ((k.choose t : ℝ) * N) hmaps hbound\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:19039","line":426,"endLine":426,"code":"  rw [Set.ncard_powerset_ncard (Set.toFinite V) (m + t)] at hsum\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:19104","line":427,"endLine":427,"code":"  simpa only [mul_assoc] using hsum\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:19140","name":"Submission.Helpers.sunflower_of_disjoint_petals","kind":"theorem","type":"sunflower_of_disjoint_petals (n r : ℕ) (ℱ : Set (Set (Fin n))) (T : Set (Fin n)) (P : Set (Set (Fin n))) (_hr : 2 ≤ r) (hcard : P.ncard = r) (hdis : P.Pairwise Disjoint) (hprop : ∀ A ∈ P, Disjoint T A ∧ T ∪ A ∈ ℱ) : ∃ S ⊆ ℱ, Set.IsSunflower r S","line":428,"endLine":466,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:19411","line":432,"endLine":439,"code":" by\n  have hrecovery (A : Set (Fin n)) (hA : A ∈ P) : (T ∪ A) \\ T = A := by\n    ext x\n    constructor\n    · intro hx\n      exact hx.1.resolve_left hx.2\n    · intro hx\n      exact ⟨Or.inr hx, fun hxT ↦ Set.disjoint_left.mp (hprop A hA).1 hxT hx⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:19656","line":440,"endLine":445,"code":"  have hinj : Set.InjOn (fun A : Set (Fin n) ↦ T ∪ A) P := by\n    intro A hA B hB hAB\n    calc\n      A = (T ∪ A) \\ T := (hrecovery A hA).symm\n      _ = (T ∪ B) \\ T := congrArg (fun D ↦ D \\ T) hAB\n      _ = B := hrecovery B hB\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:19882","line":446,"endLine":446,"code":"  refine ⟨(fun A : Set (Fin n) ↦ T ∪ A) '' P, ?_, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:19936","line":447,"endLine":448,"code":"  · rintro _ ⟨A, hA, rfl⟩\n    exact (hprop A hA).2\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:19987","line":449,"endLine":466,"code":"  · refine ⟨?_, ?_⟩\n    · rw [hinj.ncard_image]\n      exact hcard\n    · rintro _ ⟨A, hA, rfl⟩ _ ⟨B, hB, rfl⟩ hAB\n      have hne : A ≠ B := fun h ↦ hAB (congrArg (fun D ↦ T ∪ D) h)\n      have hd : Disjoint A B := hdis hA hB hne\n      ext x\n      constructor\n      · intro hx\n        have hxT : x ∈ T := by\n          by_contra hxT\n          exact Set.disjoint_left.mp hd (hx.1.resolve_left hxT) (hx.2.resolve_left hxT)\n        apply Set.mem_sInter.mpr\n        rintro _ ⟨D, _hD, rfl⟩\n        exact Or.inl hxT\n      · intro hx\n        exact ⟨Set.mem_sInter.mp hx _ ⟨A, hA, rfl⟩,\n          Set.mem_sInter.mp hx _ ⟨B, hB, rfl⟩⟩\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:20609","name":"Submission.Helpers.scalar_threshold_comparison","kind":"theorem","type":"scalar_threshold_comparison (r w : ℕ) (hr : 3 ≤ r) (hw : 2 ≤ w) : 2 ≤ 520 * (r : ℝ) ^ 3 * ((Nat.log 2 w + 1 : ℕ) : ℝ) ∧ 520 * (r : ℝ) ^ 3 * ((Nat.log 2 w + 1 : ℕ) : ℝ) < 40000 * (r : ℝ) ^ 3 * Real.logb (1.9 : ℝ) (w : ℝ) * Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ)) ∧ w < 2 ^ (Nat.log 2 w + 1)","line":467,"endLine":514,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2178","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:2760"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:20953","line":472,"endLine":473,"code":" by\n  have hb : (1 : ℝ) < 1.9 := by norm_num\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:20998","line":474,"endLine":474,"code":"  have hrR : (3 : ℝ) ≤ (r : ℝ) := by exact_mod_cast hr\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:21053","line":475,"endLine":475,"code":"  have hwR : (2 : ℝ) ≤ (w : ℝ) := by exact_mod_cast hw\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:21108","line":476,"endLine":476,"code":"  have hL := one_lt_logb_of_two_le w hw\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:21148","line":477,"endLine":477,"code":"  have hLL := (rational_log_factors_lower_bounds w hw).2\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:21205","line":478,"endLine":481,"code":"  have hcompare : Real.logb (2 : ℝ) (w : ℝ) ≤ Real.logb (1.9 : ℝ) (w : ℝ) := by\n    change Real.log (w : ℝ) / Real.log 2 ≤ Real.log (w : ℝ) / Real.log 1.9\n    exact div_le_div_of_nonneg_left (Real.log_nonneg (by linarith)) (Real.log_pos hb)\n      (Real.log_le_log (by norm_num) (by norm_num))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:21498","line":482,"endLine":483,"code":"  have hnatlog : (Nat.log 2 w : ℝ) ≤ Real.logb (1.9 : ℝ) (w : ℝ) :=\n    (Real.natLog_le_logb w 2).trans hcompare\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:21611","line":484,"endLine":486,"code":"  have hell : ((Nat.log 2 w + 1 : ℕ) : ℝ) ≤ 2 * Real.logb (1.9 : ℝ) (w : ℝ) := by\n    push_cast\n    linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:21720","line":487,"endLine":488,"code":"  have hellone : (1 : ℝ) ≤ ((Nat.log 2 w + 1 : ℕ) : ℝ) := by\n    exact_mod_cast (Nat.succ_le_succ (Nat.zero_le (Nat.log 2 w)))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:21847","line":489,"endLine":491,"code":"  have hr3 : (1 : ℝ) ≤ (r : ℝ) ^ 3 := by\n    simpa using pow_le_pow_left₀ (by norm_num : (0 : ℝ) ≤ 1)\n      (by linarith : (1 : ℝ) ≤ (r : ℝ)) 3\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:21991","line":492,"endLine":492,"code":"  have hr3pos : (0 : ℝ) < (r : ℝ) ^ 3 := lt_of_lt_of_le zero_lt_one hr3\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:22063","line":493,"endLine":493,"code":"  have hLpos : 0 < Real.logb (1.9 : ℝ) (w : ℝ) := lt_trans zero_lt_one hL\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:22137","line":494,"endLine":494,"code":"  refine ⟨?_, ?_, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:22159","line":495,"endLine":501,"code":"  · have hmul : (1 : ℝ) ≤ (r : ℝ) ^ 3 * ((Nat.log 2 w + 1 : ℕ) : ℝ) := by\n      simpa using mul_le_mul hr3 hellone (by norm_num : (0 : ℝ) ≤ 1) hr3pos.le\n    calc\n      (2 : ℝ) ≤ 520 * 1 := by norm_num\n      _ ≤ 520 * ((r : ℝ) ^ 3 * ((Nat.log 2 w + 1 : ℕ) : ℝ)) :=\n        mul_le_mul_of_nonneg_left hmul (by norm_num)\n      _ = 520 * (r : ℝ) ^ 3 * ((Nat.log 2 w + 1 : ℕ) : ℝ) := by ring\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:22545","line":502,"endLine":513,"code":"  · calc\n      520 * (r : ℝ) ^ 3 * ((Nat.log 2 w + 1 : ℕ) : ℝ) ≤\n          520 * (r : ℝ) ^ 3 * (2 * Real.logb (1.9 : ℝ) (w : ℝ)) :=\n        mul_le_mul_of_nonneg_left hell (mul_nonneg (by norm_num) hr3pos.le)\n      _ = 1040 * ((r : ℝ) ^ 3 * Real.logb (1.9 : ℝ) (w : ℝ)) := by ring\n      _ < 4000 * ((r : ℝ) ^ 3 * Real.logb (1.9 : ℝ) (w : ℝ)) :=\n        mul_lt_mul_of_pos_right (by norm_num) (mul_pos hr3pos hLpos)\n      _ = (40000 * (r : ℝ) ^ 3 * Real.logb (1.9 : ℝ) (w : ℝ)) * (1 / 10) := by ring\n      _ ≤ 40000 * (r : ℝ) ^ 3 * Real.logb (1.9 : ℝ) (w : ℝ) *\n          Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ)) :=\n        mul_le_mul_of_nonneg_left hLL\n          (mul_nonneg (mul_nonneg (by norm_num) hr3pos.le) hLpos.le)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23274","line":514,"endLine":514,"code":"  · simpa only [Nat.succ_eq_add_one] using Nat.lt_pow_succ_log_self (by norm_num : 1 < 2) w\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23366","name":"Submission.Helpers.exists_perm_image_eq_of_ncard_eq","kind":"theorem","type":"exists_perm_image_eq_of_ncard_eq {α : Type*} [Finite α] (A B : Set α) (h : A.ncard = B.ncard) : ∃ σ : Equiv.Perm α, σ '' A = B","line":515,"endLine":524,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23511","line":517,"endLine":518,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23527","line":519,"endLine":519,"code":"  letI := Fintype.ofFinite α\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23556","line":520,"endLine":521,"code":"  obtain ⟨σ, hσ⟩ := Equiv.Perm.exists_map_finset_eq A.toFinset B.toFinset\n    (by simpa only [← Set.ncard_eq_toFinset_card'] using h)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23690","line":522,"endLine":522,"code":"  refine ⟨σ, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23707","line":523,"endLine":523,"code":"  have he := congrArg (fun D : Finset α ↦ (D : Set α)) hσ\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23765","line":524,"endLine":524,"code":"  simpa using he\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23782","name":"Submission.Helpers.permutation_image_fiber_ncard_eq","kind":"theorem","type":"permutation_image_fiber_ncard_eq {α : Type*} [Fintype α] (A U : Set α) (h : A.ncard = U.ncard) : {σ : Equiv.Perm α | σ '' A = A}.ncard = {σ : Equiv.Perm α | σ '' A = U}.ncard","line":525,"endLine":549,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23366"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23981","line":528,"endLine":529,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23997","line":530,"endLine":530,"code":"  obtain ⟨τ, hτ⟩ := exists_perm_image_eq_of_ncard_eq A U h\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:24056","line":531,"endLine":531,"code":"  apply Set.ncard_congr (fun σ _ ↦ σ.trans τ)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:24102","line":532,"endLine":536,"code":"  · intro σ hσ\n    change (τ ∘ σ) '' A = U\n    calc\n      (τ ∘ σ) '' A = τ '' (σ '' A) := (Set.image_image τ σ A).symm\n      _ = U := by rw [hσ, hτ]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:24251","line":537,"endLine":540,"code":"  · intro σ π _ _ he\n    apply Equiv.ext\n    intro x\n    exact τ.injective (congrArg (fun e : Equiv.Perm α ↦ e x) he)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:24369","line":541,"endLine":549,"code":"  · intro π hπ\n    refine ⟨π.trans τ.symm, ?_, ?_⟩\n    · change (τ.symm ∘ π) '' A = A\n      calc\n        (τ.symm ∘ π) '' A = τ.symm '' (π '' A) := (Set.image_image τ.symm π A).symm\n        _ = A := by rw [hπ, ← hτ]; simp [Set.image_image]\n    · apply Equiv.ext\n      intro x\n      exact τ.apply_symm_apply (π x)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:24681","name":"Submission.Helpers.ncard_eq_sum_fiber_ncard","kind":"theorem","type":"ncard_eq_sum_fiber_ncard {α β : Type*} [Fintype α] [Fintype β] (S : Set α) (T : Finset β) (f : α → β) (hf : ∀ x ∈ S, f x ∈ T) : S.ncard = ∑ y ∈ T, {x | x ∈ S ∧ f x = y}.ncard","line":550,"endLine":561,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:24874","line":552,"endLine":553,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:24890","line":554,"endLine":556,"code":"  have hc := Finset.card_eq_sum_card_fiberwise\n    (s := S.toFinset) (t := T) (f := f)\n    (by intro x hx; simpa using hf x (by simpa using hx))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:25035","line":557,"endLine":560,"code":"  have he (y : β) :\n      {x | x ∈ S ∧ f x = y}.toFinset = {x ∈ S.toFinset | f x = y} := by\n    ext x\n    simp\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:25146","line":561,"endLine":561,"code":"  simpa only [Set.ncard_eq_toFinset_card', he] using hc\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:25202","name":"Submission.Helpers.permutation_image_family_ncard_mul","kind":"theorem","type":"permutation_image_family_ncard_mul {α : Type*} [Fintype α] (A : Set α) (H : Set (Set α)) (hH : ∀ U ∈ H, U.ncard = A.ncard) : {σ : Equiv.Perm α | σ '' A ∈ H}.ncard * {U : Set α | U.ncard = A.ncard}.ncard = H.ncard * (Set.univ : Set (Equiv.Perm α)).ncard","line":562,"endLine":596,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:24681","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:23782"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:25479","line":565,"endLine":566,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:25495","line":567,"endLine":567,"code":"  let K := {σ : Equiv.Perm α | σ '' A = A}.ncard\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:25544","line":568,"endLine":586,"code":"  have hc (G : Set (Set α)) (hG : ∀ U ∈ G, U.ncard = A.ncard) :\n      {σ : Equiv.Perm α | σ '' A ∈ G}.ncard = G.ncard * K := by\n    rw [ncard_eq_sum_fiber_ncard _ G.toFinset (fun σ : Equiv.Perm α ↦ σ '' A)\n      (by intro σ hσ; simpa using hσ)]\n    calc\n      (∑ U ∈ G.toFinset,\n          {σ : Equiv.Perm α | σ '' A ∈ G ∧ σ '' A = U}.ncard) =\n          ∑ _U ∈ G.toFinset, K := by\n        apply Finset.sum_congr rfl\n        intro U hU\n        have hUG : U ∈ G := by simpa using hU\n        have he : {σ : Equiv.Perm α | σ '' A ∈ G ∧ σ '' A = U} =\n            {σ : Equiv.Perm α | σ '' A = U} := by\n          ext σ\n          exact ⟨And.right, fun h ↦ ⟨h ▸ hUG, h⟩⟩\n        rw [he]\n        exact (permutation_image_fiber_ncard_eq A U (hG U hUG).symm).symm\n      _ = G.ncard * K := by\n        simp only [Finset.sum_const, nsmul_eq_mul, Set.ncard_eq_toFinset_card', Nat.cast_id]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:26416","line":587,"endLine":587,"code":"  let T : Set (Set α) := {U | U.ncard = A.ncard}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:26465","line":588,"endLine":590,"code":"  have htotal : {σ : Equiv.Perm α | σ '' A ∈ T} = Set.univ := by\n    ext σ\n    simp [T, Set.ncard_image_of_injective A σ.injective]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:26597","line":591,"endLine":591,"code":"  have hall := hc T (fun _ h ↦ h)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:26631","line":592,"endLine":592,"code":"  rw [htotal] at hall\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:26653","line":593,"endLine":596,"code":"  calc\n    _ = (H.ncard * K) * T.ncard := by rw [hc H hH]\n    _ = H.ncard * (T.ncard * K) := by ac_rfl\n    _ = _ := by rw [← hall]\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:26784","name":"Submission.Helpers.numbered_disjoint_blocks","kind":"theorem","type":"numbered_disjoint_blocks (n r s : ℕ) (hrs : r * s ≤ n) : ∃ A : Fin r → Set (Fin n), (∀ i, (A i).ncard = s) ∧ (∀ i j, i ≠ j → Disjoint (A i) (A j))","line":597,"endLine":613,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:26951","line":599,"endLine":600,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:26967","line":601,"endLine":602,"code":"  obtain ⟨e⟩ := Function.Embedding.nonempty_of_card_le\n    (α := Fin r × Fin s) (β := Fin n) (by simpa using hrs)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:27081","line":603,"endLine":603,"code":"  let A : Fin r → Set (Fin n) := fun i ↦ Set.range (fun j : Fin s ↦ e (i, j))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:27159","line":604,"endLine":604,"code":"  refine ⟨A, ?_, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:27180","line":605,"endLine":609,"code":"  · intro i\n    have hi : Function.Injective (fun j : Fin s ↦ e (i, j)) := by\n      intro j k hjk\n      exact congrArg Prod.snd (e.injective hjk)\n    simpa [A] using Set.ncard_range_of_injective hi\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:27378","line":610,"endLine":613,"code":"  · intro i j hij\n    apply Set.disjoint_left.mpr\n    rintro x ⟨a, ha⟩ ⟨b, hb⟩\n    exact hij (congrArg Prod.fst (e.injective (ha.trans hb.symm)))\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:27524","name":"Submission.Helpers.disjoint_blocks_from_dense_family","kind":"theorem","type":"disjoint_blocks_from_dense_family (n r s : ℕ) (𝒢 : Set (Set (Fin n))) (hrs : r * s ≤ n) (h𝒢 : ∀ U ∈ 𝒢, U.ncard = s) (hdense : (r : ℝ) * ((n.choose s : ℝ) - (𝒢.ncard : ℝ)) < (n.choose s : ℝ)) : ∃ B : Fin r → Set (Fin n), (∀ i, B i ∈ 𝒢) ∧ (∀ i j, i ≠ j → Disjoint (B i) (B j))","line":614,"endLine":694,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:26784","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:25202","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4818"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:27836","line":619,"endLine":620,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:27852","line":621,"endLine":621,"code":"  obtain ⟨A, hA, hAdis⟩ := numbered_disjoint_blocks n r s hrs\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:27914","line":622,"endLine":622,"code":"  let T : Set (Set (Fin n)) := {U | U.ncard = s}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:27963","line":623,"endLine":623,"code":"  let H : Set (Set (Fin n)) := T \\ 𝒢\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:28001","line":624,"endLine":624,"code":"  have hGT : 𝒢 ⊆ T := fun U hU ↦ h𝒢 U hU\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:28044","line":625,"endLine":627,"code":"  have hTcard : T.ncard = n.choose s := by\n    simpa [T] using Set.ncard_powerset_ncard\n      (Set.toFinite (Set.univ : Set (Fin n))) s\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:28180","line":628,"endLine":632,"code":"  have hHcard : (H.ncard : ℝ) = (n.choose s : ℝ) - (𝒢.ncard : ℝ) := by\n    have hc := Set.ncard_sdiff_add_ncard_of_subset hGT\n    have hcR : (H.ncard : ℝ) + (𝒢.ncard : ℝ) = (n.choose s : ℝ) := by\n      exact_mod_cast hc.trans hTcard\n    linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:28428","line":633,"endLine":687,"code":"  have hgood : ∃ σ : Equiv.Perm (Fin n), ∀ i, σ '' A i ∈ 𝒢 := by\n    by_contra hnone\n    have hbad : ∀ σ : Equiv.Perm (Fin n), ∃ i, σ '' A i ∈ H := by\n      intro σ\n      have hnot : ¬ ∀ i, σ '' A i ∈ 𝒢 := fun h ↦ hnone ⟨σ, h⟩\n      obtain ⟨i, hi⟩ := not_forall.mp hnot\n      refine ⟨i, ?_, hi⟩\n      change (σ '' A i).ncard = s\n      rw [Set.ncard_image_of_injective _ σ.injective, hA i]\n    let S : Set (Equiv.Perm (Fin n) × Fin r) := {p | p.1 '' A p.2 ∈ H}\n    have hP_le : (Set.univ : Set (Equiv.Perm (Fin n))).ncard ≤ S.ncard := by\n      apply Set.ncard_le_ncard_of_injOn (fun σ ↦ (σ, (hbad σ).choose))\n      · intro σ _\n        exact (hbad σ).choose_spec\n      · intro σ π _ _ he\n        exact congrArg Prod.fst he\n    have hfiber (i : Fin r) :\n        {p : Equiv.Perm (Fin n) × Fin r | p ∈ S ∧ p.2 = i}.ncard =\n          {σ : Equiv.Perm (Fin n) | σ '' A i ∈ H}.ncard := by\n      apply Set.ncard_congr (fun p _ ↦ p.1)\n      · intro p hp\n        change p.1 '' A i ∈ H\n        simpa only [S, Set.mem_ofPred_eq, hp.2] using hp.1\n      · intro p q hp hq he\n        exact Prod.ext he (hp.2.trans hq.2.symm)\n      · intro σ hσ\n        exact ⟨(σ, i), ⟨hσ, rfl⟩, rfl⟩\n    have hbound (i : Fin r) :\n        ({p : Equiv.Perm (Fin n) × Fin r | p ∈ S ∧ p.2 = i}.ncard : ℝ) *\n            (n.choose s : ℝ) ≤\n          (H.ncard : ℝ) * ((Set.univ : Set (Equiv.Perm (Fin n))).ncard : ℝ) := by\n      rw [hfiber i]\n      have hc := permutation_image_family_ncard_mul (A i) H\n        (fun U hU ↦ hU.1.trans (hA i).symm)\n      rw [hA i] at hc\n      change _ * T.ncard = _ at hc\n      rw [hTcard] at hc\n      exact le_of_eq (by exact_mod_cast hc)\n    have hsum := ncard_mul_le_of_fiber_bounds S (Set.univ : Set (Fin r))\n      Prod.snd (n.choose s : ℝ)\n      ((H.ncard : ℝ) * ((Set.univ : Set (Equiv.Perm (Fin n))).ncard : ℝ))\n      (fun _ _ ↦ Set.mem_univ _) (fun i _ ↦ hbound i)\n    have hPpos : 0 < ((Set.univ : Set (Equiv.Perm (Fin n))).ncard : ℝ) := by\n      exact_mod_cast ((Set.ncard_pos (Set.toFinite _)).mpr\n        (⟨Equiv.refl (Fin n), Set.mem_univ _⟩ :\n          (Set.univ : Set (Equiv.Perm (Fin n))).Nonempty))\n    have hleft : ((Set.univ : Set (Equiv.Perm (Fin n))).ncard : ℝ) *\n        (n.choose s : ℝ) ≤ (S.ncard : ℝ) * (n.choose s : ℝ) := by\n      exact mul_le_mul_of_nonneg_right (by exact_mod_cast hP_le) (by positivity)\n    have hsum' : ((Set.univ : Set (Equiv.Perm (Fin n))).ncard : ℝ) *\n        (n.choose s : ℝ) ≤ (r : ℝ) * ((n.choose s : ℝ) - (𝒢.ncard : ℝ)) *\n          ((Set.univ : Set (Equiv.Perm (Fin n))).ncard : ℝ) := by\n      simpa only [Set.ncard_univ, Nat.card_fin, hHcard, mul_assoc] using hleft.trans hsum\n    have hd := mul_lt_mul_of_pos_right hdense hPpos\n    nlinarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:31119","line":688,"endLine":688,"code":"  obtain ⟨σ, hσ⟩ := hgood\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:31145","line":689,"endLine":689,"code":"  refine ⟨fun i ↦ σ '' A i, hσ, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:31181","line":690,"endLine":690,"code":"  intro i j hij\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:31197","line":691,"endLine":691,"code":"  apply Set.disjoint_left.mpr\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:31227","line":692,"endLine":692,"code":"  rintro x ⟨a, ha, hax⟩ ⟨b, hb, hbx⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:31264","line":693,"endLine":693,"code":"  have hab : a = b := σ.injective (hax.trans hbx.symm)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:31319","line":694,"endLine":694,"code":"  exact Set.disjoint_left.mp (hAdis i j hij) ha (hab ▸ hb)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:31378","name":"Submission.Helpers.choose_add_mul_pow_le","kind":"theorem","type":"choose_add_mul_pow_le (v m t : ℕ) : v.choose (m + t) * m ^ t ≤ v.choose m * v ^ t","line":695,"endLine":712,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:31474","line":696,"endLine":712,"code":" by\n  induction t with\n  | zero => simp\n  | succ t ih =>\n    have hstep : v.choose (m + t + 1) * m ≤ v.choose (m + t) * v := by\n      calc\n        v.choose (m + t + 1) * m ≤ v.choose (m + t + 1) * (m + t + 1) :=\n          Nat.mul_le_mul_left _ (by omega)\n        _ = v.choose (m + t) * (v - (m + t)) := Nat.choose_succ_right_eq v (m + t)\n        _ ≤ v.choose (m + t) * v := Nat.mul_le_mul_left _ (Nat.sub_le _ _)\n    calc\n      v.choose (m + (t + 1)) * m ^ (t + 1) =\n          (v.choose (m + t + 1) * m) * m ^ t := by ring\n      _ ≤ (v.choose (m + t) * v) * m ^ t := Nat.mul_le_mul_right _ hstep\n      _ = (v.choose (m + t) * m ^ t) * v := by ring\n      _ ≤ (v.choose m * v ^ t) * v := Nat.mul_le_mul_right _ ih\n      _ = v.choose m * v ^ (t + 1) := by rw [pow_succ]; ring\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:32247","name":"Submission.Helpers.binomial_upper_half_tail","kind":"theorem","type":"binomial_upper_half_tail (w : ℕ) (q : ℝ) (hq : 2 ≤ q) : (∑ t ∈ Finset.Icc (w / 2 + 1) w, (w.choose t : ℝ) * (q⁻¹) ^ (2 * t)) ≤ (2 / q) ^ w","line":713,"endLine":743,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:32406","line":715,"endLine":716,"code":" by\n  have hqpos : 0 < q := by linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:32446","line":717,"endLine":717,"code":"  have hinv : 0 ≤ q⁻¹ := inv_nonneg.mpr hqpos.le\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:32495","line":718,"endLine":718,"code":"  have hinvone : q⁻¹ ≤ 1 := (inv_le_one₀ hqpos).mpr (by linarith)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:32561","line":719,"endLine":729,"code":"  have hsum : (∑ t ∈ Finset.Icc (w / 2 + 1) w, (w.choose t : ℝ)) ≤ (2 : ℝ) ^ w := by\n    calc\n      (∑ t ∈ Finset.Icc (w / 2 + 1) w, (w.choose t : ℝ)) ≤\n          ∑ t ∈ Finset.range (w + 1), (w.choose t : ℝ) := by\n        apply Finset.sum_le_sum_of_subset_of_nonneg\n        · intro t ht\n          simp only [Finset.mem_Icc] at ht\n          exact Finset.mem_range.mpr (by omega)\n        · intro t _ _\n          exact Nat.cast_nonneg _\n      _ = (2 : ℝ) ^ w := by exact_mod_cast Nat.sum_range_choose w\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:33061","line":730,"endLine":743,"code":"  calc\n    (∑ t ∈ Finset.Icc (w / 2 + 1) w, (w.choose t : ℝ) * (q⁻¹) ^ (2 * t)) ≤\n        ∑ t ∈ Finset.Icc (w / 2 + 1) w, (w.choose t : ℝ) * (q⁻¹) ^ w := by\n      apply Finset.sum_le_sum\n      intro t ht\n      have hwt : w ≤ 2 * t := by\n        simp only [Finset.mem_Icc] at ht\n        omega\n      exact mul_le_mul_of_nonneg_left (pow_le_pow_of_le_one hinv hinvone hwt)\n        (Nat.cast_nonneg _)\n    _ = (∑ t ∈ Finset.Icc (w / 2 + 1) w, (w.choose t : ℝ)) * (q⁻¹) ^ w :=\n      (Finset.sum_mul _ _ _).symm\n    _ ≤ (2 : ℝ) ^ w * (q⁻¹) ^ w := mul_le_mul_of_nonneg_right hsum (pow_nonneg hinv _)\n    _ = (2 / q) ^ w := by rw [← mul_pow, div_eq_mul_inv]\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:33711","name":"Submission.Helpers.exists_minimal_fragment_label","kind":"theorem","type":"exists_minimal_fragment_label (n d : ℕ) (f : Fin d → Set (Fin n)) (i : Fin d) (W : Set (Fin n)) : ∃ j : Fin d, f j ⊆ f i ∪ W ∧ ∀ a : Fin d, f a ⊆ f i ∪ W → (f j \\ W).ncard ≤ (f a \\ W).ncard","line":744,"endLine":754,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:33925","line":747,"endLine":748,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:33941","line":749,"endLine":749,"code":"  let s : Finset (Fin d) := Finset.univ.filter fun j ↦ f j ⊆ f i ∪ W\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34010","line":750,"endLine":750,"code":"  have hi : i ∈ s := by simp [s, Set.subset_union_left]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34066","line":751,"endLine":751,"code":"  obtain ⟨j, hj, hmin⟩ := Finset.exists_min_image s (fun j ↦ (f j \\ W).ncard) ⟨i, hi⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34152","line":752,"endLine":752,"code":"  refine ⟨j, (Finset.mem_filter.mp hj).2, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34198","line":753,"endLine":753,"code":"  intro a ha\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34211","line":754,"endLine":754,"code":"  exact hmin a (Finset.mem_filter.mpr ⟨Finset.mem_univ a, ha⟩)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34288","name":"Submission.Helpers.minimalFragmentLabel","kind":"definition","type":"minimalFragmentLabel {n d : ℕ} (f : Fin d → Set (Fin n)) (i : Fin d) (W : Set (Fin n)) : Fin d","line":755,"endLine":757,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:33711"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34393","line":756,"endLine":757,"code":"\n  Classical.choose (exists_minimal_fragment_label n d f i W)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34469","name":"Submission.Helpers.minimalFragment","kind":"definition","type":"minimalFragment {n d : ℕ} (f : Fin d → Set (Fin n)) (i : Fin d) (W : Set (Fin n)) : Set (Fin n)","line":758,"endLine":760,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34288"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34575","line":759,"endLine":760,"code":"\n  f (minimalFragmentLabel f i W) \\ W\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34613","name":"Submission.Helpers.minimalFragment_spec","kind":"theorem","type":"minimalFragment_spec {n d : ℕ} (f : Fin d → Set (Fin n)) (i : Fin d) (W : Set (Fin n)) : f (minimalFragmentLabel f i W) ⊆ f i ∪ W ∧ ∀ a : Fin d, f a ⊆ f i ∪ W → (minimalFragment f i W).ncard ≤ (f a \\ W).ncard","line":761,"endLine":765,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34288","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34469","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:33711"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34846","line":764,"endLine":765,"code":"\n  Classical.choose_spec (exists_minimal_fragment_label n d f i W)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34913","name":"Submission.Helpers.minimalFragment_subset","kind":"theorem","type":"minimalFragment_subset {n d : ℕ} (f : Fin d → Set (Fin n)) (i : Fin d) (W : Set (Fin n)) : minimalFragment f i W ⊆ f i","line":766,"endLine":769,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34469","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:13029","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34288","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34613"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:35046","line":767,"endLine":769,"code":"\n  fragment_shrinks_current_edge f i (minimalFragmentLabel f i W) W\n    (minimalFragment_spec f i W).1\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:35149","name":"Submission.Helpers.ncard_eq_sum_ncard_fibers","kind":"theorem","type":"ncard_eq_sum_ncard_fibers {α β : Type*} [Fintype α] [DecidableEq β] (s : Set α) (t : Finset β) (f : α → β) (hf : ∀ x ∈ s, f x ∈ t) : (s.ncard : ℝ) = ∑ y ∈ t, ({x | x ∈ s ∧ f x = y}.ncard : ℝ)","line":770,"endLine":782,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:35359","line":772,"endLine":773,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:35375","line":774,"endLine":776,"code":"  have hc := Finset.card_eq_sum_card_fiberwise\n    (s := s.toFinset) (t := t) (f := f)\n    (by intro x hx; exact hf x (by simpa using hx))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:35514","line":777,"endLine":780,"code":"  have he (y : β) :\n      {x | x ∈ s ∧ f x = y}.toFinset = {x ∈ s.toFinset | f x = y} := by\n    ext x\n    simp\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:35625","line":781,"endLine":781,"code":"  simp_rw [Set.ncard_eq_toFinset_card', he]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:35669","line":782,"endLine":782,"code":"  exact_mod_cast hc\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:35689","name":"Submission.Helpers.normalize_fragment_rank_bound","kind":"theorem","type":"normalize_fragment_rank_bound (v k m t : ℕ) (c κ N q : ℝ) (hc : 0 ≤ c) (hκ : 0 ≤ κ) (hN : 0 ≤ N) (hq : 2 ≤ q) (hv : 0 < v) (hscale : q ^ 2 * (v : ℝ) ≤ (m : ℝ) * κ) (hcount : c * κ ^ t ≤ (v.choose (m + t) : ℝ) * (k.choose t : ℝ) * N) : c ≤ (v.choose m : ℝ) * (k.choose t : ℝ) * N * (q⁻¹) ^ (2 * t)","line":783,"endLine":811,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:31378"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:36012","line":787,"endLine":788,"code":" by\n  have hqpos : 0 < q := by linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:36052","line":789,"endLine":789,"code":"  have hvpos : (0 : ℝ) < v := by exact_mod_cast hv\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:36103","line":790,"endLine":791,"code":"  have hbinom : (v.choose (m + t) : ℝ) * (m : ℝ) ^ t ≤\n      (v.choose m : ℝ) * (v : ℝ) ^ t := by exact_mod_cast choose_add_mul_pow_le v m t\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:36244","line":792,"endLine":793,"code":"  have hscale_pow := pow_le_pow_left₀\n    (mul_nonneg (sq_nonneg q) (Nat.cast_nonneg v)) hscale t\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:36342","line":794,"endLine":806,"code":"  have hmain : (c * q ^ (2 * t)) * (v : ℝ) ^ t ≤\n      ((v.choose m : ℝ) * (k.choose t : ℝ) * N) * (v : ℝ) ^ t := by\n    calc\n      (c * q ^ (2 * t)) * (v : ℝ) ^ t = c * (q ^ 2 * (v : ℝ)) ^ t := by\n        rw [mul_pow, ← pow_mul]\n        ring\n      _ ≤ c * ((m : ℝ) * κ) ^ t := mul_le_mul_of_nonneg_left hscale_pow hc\n      _ = (c * κ ^ t) * (m : ℝ) ^ t := by rw [mul_pow]; ring\n      _ ≤ ((v.choose (m + t) : ℝ) * (k.choose t : ℝ) * N) * (m : ℝ) ^ t :=\n        mul_le_mul_of_nonneg_right hcount (pow_nonneg (Nat.cast_nonneg m) t)\n      _ ≤ ((v.choose m : ℝ) * (k.choose t : ℝ) * N) * (v : ℝ) ^ t := by\n        convert mul_le_mul_of_nonneg_right hbinom\n          (mul_nonneg (Nat.cast_nonneg (k.choose t)) hN) using 1 <;> ring\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:37069","line":807,"endLine":807,"code":"  have hcancel := (mul_le_mul_iff_left₀ (pow_pos hvpos t)).mp hmain\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:37137","line":808,"endLine":809,"code":"  have hnorm := mul_le_mul_of_nonneg_right hcancel\n    (pow_nonneg (inv_nonneg.mpr hqpos.le) (2 * t))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:37239","line":810,"endLine":811,"code":"  simpa only [inv_pow, mul_assoc, mul_inv_cancel₀ (ne_of_gt (pow_pos hqpos (2 * t))),\n    mul_one] using hnorm\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:37350","name":"Submission.Helpers.minimal_fragment_rank_bound","kind":"theorem","type":"minimal_fragment_rank_bound (n d k m t : ℕ) (V : Set (Fin n)) (f : Fin d → Set (Fin n)) (κ N q : ℝ) (hκ : 0 < κ) (hN : 0 ≤ N) (hq : 2 ≤ q) (hV : 0 < V.ncard) (hscale : q ^ 2 * (V.ncard : ℝ) ≤ (m : ℝ) * κ) (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ k) (hcode : ∀ U : Set (Fin n), ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) : ({p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧ (minimalFragment f p.1 p.2).ncard = t}.ncard : ℝ) ≤ (V.ncard.choose m : ℝ) * (k.choose t : ℝ) * N * (q⁻¹) ^ (2 * t)","line":812,"endLine":836,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34469","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34613","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34288","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:35689","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:15614"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:37900","line":821,"endLine":832,"code":" by\n  have hsub : {p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧\n      (minimalFragment f p.1 p.2).ncard = t} ⊆\n      {p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧\n        (∀ j : Fin d, f j ⊆ f p.1 ∪ p.2 → t ≤ (f j \\ p.2).ncard) ∧\n        (∃ j : Fin d, f j ⊆ f p.1 ∪ p.2 ∧ (f j \\ p.2).ncard = t)} := by\n    intro p hp\n    refine ⟨hp.1, hp.2.1, ?_, ?_⟩\n    · intro a ha\n      rw [← hp.2.2]\n      exact (minimalFragment_spec f p.1 p.2).2 a ha\n    · exact ⟨minimalFragmentLabel f p.1 p.2, (minimalFragment_spec f p.1 p.2).1, hp.2.2⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:38443","line":833,"endLine":834,"code":"  apply normalize_fragment_rank_bound V.ncard k m t _ κ N q\n    (Nat.cast_nonneg _) hκ.le hN hq hV hscale\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:38549","line":835,"endLine":836,"code":"  exact (mul_le_mul_of_nonneg_right (by exact_mod_cast Set.ncard_le_ncard hsub)\n    (pow_nonneg hκ.le t)).trans (minimal_fragment_count n d k m t V f κ N hκ hN hsys hcode)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:38721","name":"Submission.Helpers.bad_fragment_pair_count","kind":"theorem","type":"bad_fragment_pair_count (n d k m : ℕ) (V : Set (Fin n)) (f : Fin d → Set (Fin n)) (κ N q : ℝ) (hκ : 0 < κ) (hN : 0 ≤ N) (hq : 2 ≤ q) (hV : 0 < V.ncard) (hscale : q ^ 2 * (V.ncard : ℝ) ≤ (m : ℝ) * κ) (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ k) (hcode : ∀ U : Set (Fin n), ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) : ({p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧ k / 2 < (minimalFragment f p.1 p.2).ncard}.ncard : ℝ) ≤ (V.ncard.choose m : ℝ) * N * (2 / q) ^ k","line":837,"endLine":883,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34469","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34913","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:35149","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:37350","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:32247"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:39246","line":846,"endLine":847,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:39262","line":848,"endLine":848,"code":"  letI := Fintype.ofFinite (Set (Fin n))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:39303","line":849,"endLine":850,"code":"  let s : Set (Fin d × Set (Fin n)) := {p | p.2 ⊆ V ∧ p.2.ncard = m ∧\n    k / 2 < (minimalFragment f p.1 p.2).ncard}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:39420","line":851,"endLine":851,"code":"  let rank (p : Fin d × Set (Fin n)) := (minimalFragment f p.1 p.2).ncard\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:39494","line":852,"endLine":855,"code":"  have hmap (p : Fin d × Set (Fin n)) (hp : p ∈ s) :\n      rank p ∈ Finset.Icc (k / 2 + 1) k := by\n    have hle := (Set.ncard_le_ncard (minimalFragment_subset f p.1 p.2)).trans (hsys p.1).2\n    exact Finset.mem_Icc.mpr ⟨Nat.succ_le_iff.mpr hp.2.2, hle⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:39747","line":856,"endLine":856,"code":"  change (s.ncard : ℝ) ≤ _\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:39774","line":857,"endLine":857,"code":"  rw [ncard_eq_sum_ncard_fibers s (Finset.Icc (k / 2 + 1) k) rank hmap]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:39846","line":858,"endLine":883,"code":"  calc\n    (∑ t ∈ Finset.Icc (k / 2 + 1) k, ({p | p ∈ s ∧ rank p = t}.ncard : ℝ)) ≤\n        ∑ t ∈ Finset.Icc (k / 2 + 1) k,\n          (V.ncard.choose m : ℝ) * (k.choose t : ℝ) * N * (q⁻¹) ^ (2 * t) := by\n      apply Finset.sum_le_sum\n      intro t _ht\n      have hsub : {p | p ∈ s ∧ rank p = t} ⊆\n          {p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧\n            (minimalFragment f p.1 p.2).ncard = t} := by\n        intro p hp\n        exact ⟨hp.1.1, hp.1.2.1, hp.2⟩\n      have hc : ({p | p ∈ s ∧ rank p = t}.ncard : ℝ) ≤\n          ({p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧\n            (minimalFragment f p.1 p.2).ncard = t}.ncard : ℝ) := by\n        exact_mod_cast Set.ncard_le_ncard hsub\n      exact hc.trans\n        (minimal_fragment_rank_bound n d k m t V f κ N q hκ hN hq hV hscale hsys hcode)\n    _ = (V.ncard.choose m : ℝ) * N *\n        (∑ t ∈ Finset.Icc (k / 2 + 1) k, (k.choose t : ℝ) * (q⁻¹) ^ (2 * t)) := by\n      rw [Finset.mul_sum]\n      apply Finset.sum_congr rfl\n      intro t _\n      ring\n    _ ≤ (V.ncard.choose m : ℝ) * N * (2 / q) ^ k :=\n      mul_le_mul_of_nonneg_left (binomial_upper_half_tail k q hq)\n        (mul_nonneg (Nat.cast_nonneg _) hN)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:41032","name":"Submission.Helpers.retained_fragment_family","kind":"theorem","type":"retained_fragment_family (n d k : ℕ) (V W : Set (Fin n)) (f : Fin d → Set (Fin n)) (κ N : ℝ) (hκ : 0 ≤ κ) (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ k) (hcode : ∀ U : Set (Fin n), ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) : ∃ (d' : ℕ) (g : Fin d' → Set (Fin n)) (e : Fin d' → Fin d), Function.Injective e ∧ d' = {i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}.ncard ∧ (∀ a, g a ⊆ f (e a)) ∧ (∀ a, g a ⊆ V \\ W ∧ (g a).ncard ≤ k / 2) ∧ (∀ U : Set (Fin n), ({a : Fin d' | U ⊆ g a}.ncard : ℝ) * κ ^ U.ncard ≤ N) ∧ (∀ a, ∃ i : Fin d, f i ⊆ g a ∪ W)","line":884,"endLine":918,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34469","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34913","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:12347","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34288"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:41661","line":896,"endLine":897,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:41677","line":898,"endLine":898,"code":"  let L : Set (Fin d) := {i | (minimalFragment f i W).ncard ≤ k / 2}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:41746","line":899,"endLine":899,"code":"  let b : Fin (Fintype.card L) ≃ L := (Fintype.equivFin L).symm\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:41810","line":900,"endLine":900,"code":"  let e (a : Fin (Fintype.card L)) : Fin d := (b a).val\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:41866","line":901,"endLine":901,"code":"  let g (a : Fin (Fintype.card L)) : Set (Fin n) := minimalFragment f (e a) W\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:41944","line":902,"endLine":902,"code":"  have he : Function.Injective e := fun a a' h ↦ b.injective (Subtype.ext h)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:42021","line":903,"endLine":904,"code":"  have hshrink (a : Fin (Fintype.card L)) : g a ⊆ f (e a) :=\n    minimalFragment_subset f (e a) W\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:42119","line":905,"endLine":905,"code":"  refine ⟨Fintype.card L, g, e, he, ?_, hshrink, ?_, ?_, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:42180","line":906,"endLine":907,"code":"  · simpa only [Nat.card_coe_set_eq] using\n      (show Fintype.card L = Nat.card L from Nat.card_eq_fintype_card.symm)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:42299","line":908,"endLine":911,"code":"  · intro a\n    refine ⟨?_, (b a).property⟩\n    intro x hx\n    exact ⟨(hsys (e a)).1 (hshrink a hx), hx.2⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:42406","line":912,"endLine":912,"code":"  · exact codegree_bound_of_injective_shrinking f g e he hshrink κ N hκ hcode\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:42484","line":913,"endLine":918,"code":"  · intro a\n    refine ⟨minimalFragmentLabel f (e a) W, ?_⟩\n    intro x hx\n    by_cases hxW : x ∈ W\n    · exact Or.inr hxW\n    · exact Or.inl ⟨hx, hxW⟩\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:42636","name":"Submission.Helpers.dyadic_loss_step","kind":"theorem","type":"dyadic_loss_step (w : ℕ) (hw : 0 < w) (a : ℝ) (ha : 0 ≤ a) : (∑ j ∈ Finset.Icc 1 (w / 2), a ^ j) + a ^ w ≤ ∑ j ∈ Finset.Icc 1 w, a ^ j","line":919,"endLine":931,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:42791","line":921,"endLine":922,"code":" by\n  have hnot : w ∉ Finset.Icc 1 (w / 2) := by simp only [Finset.mem_Icc]; omega\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:42874","line":923,"endLine":923,"code":"  rw [add_comm, ← Finset.sum_insert hnot]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:42916","line":924,"endLine":924,"code":"  apply Finset.sum_le_sum_of_subset_of_nonneg\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:42962","line":925,"endLine":929,"code":"  · intro j hj\n    rcases Finset.mem_insert.mp hj with rfl | hj\n    · exact Finset.mem_Icc.mpr ⟨hw, le_rfl⟩\n    · exact Finset.mem_Icc.mpr\n        ⟨(Finset.mem_Icc.mp hj).1, (Finset.mem_Icc.mp hj).2.trans (Nat.div_le_self _ _)⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:43190","line":930,"endLine":931,"code":"  · intro j _ _\n    exact pow_nonneg ha j\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:43232","name":"Submission.Helpers.ncard_pair_snd_fiber","kind":"theorem","type":"ncard_pair_snd_fiber {α β : Type*} [Finite α] [Finite β] (P : α → β → Prop) (b : β) : {p : α × β | P p.1 p.2 ∧ p.2 = b}.ncard = {a : α | P a b}.ncard","line":932,"endLine":947,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:43400","line":934,"endLine":935,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:43416","line":936,"endLine":946,"code":"  have he : {p : α × β | P p.1 p.2 ∧ p.2 = b} =\n      (fun a : α ↦ (a, b)) '' {a : α | P a b} := by\n    ext p\n    constructor\n    · rintro ⟨hp, hb⟩\n      refine ⟨p.1, ?_, ?_⟩\n      · change P p.1 b\n        simpa only [hb] using hp\n      · exact Prod.ext rfl hb.symm\n    · rintro ⟨a, ha, rfl⟩\n      exact ⟨ha, rfl⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:43730","line":947,"endLine":947,"code":"  rw [he, Set.ncard_image_of_injective _ (fun _ _ h ↦ congrArg Prod.fst h)]\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:43806","name":"Submission.Helpers.ncard_pair_fst_fiber","kind":"theorem","type":"ncard_pair_fst_fiber {α β : Type*} [Finite α] [Finite β] (P : α → β → Prop) (a : α) : {p : α × β | P p.1 p.2 ∧ p.1 = a}.ncard = {b : β | P a b}.ncard","line":948,"endLine":963,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:43974","line":950,"endLine":951,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:43990","line":952,"endLine":962,"code":"  have he : {p : α × β | P p.1 p.2 ∧ p.1 = a} =\n      (fun b : β ↦ (a, b)) '' {b : β | P a b} := by\n    ext p\n    constructor\n    · rintro ⟨hp, ha⟩\n      refine ⟨p.2, ?_, ?_⟩\n      · change P a p.2\n        simpa only [ha] using hp\n      · exact Prod.ext ha.symm rfl\n    · rintro ⟨b, hb, rfl⟩\n      exact ⟨hb, rfl⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:44304","line":963,"endLine":963,"code":"  rw [he, Set.ncard_image_of_injective _ (fun _ _ h ↦ congrArg Prod.snd h)]\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:44380","name":"Submission.Helpers.retained_fragment_average","kind":"theorem","type":"retained_fragment_average (n d k m : ℕ) (V : Set (Fin n)) (f : Fin d → Set (Fin n)) (κ N q : ℝ) (hκ : 0 < κ) (hN : 0 ≤ N) (hq : 2 ≤ q) (hV : 0 < V.ncard) (hscale : q ^ 2 * (V.ncard : ℝ) ≤ (m : ℝ) * κ) (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ k) (hcode : ∀ U : Set (Fin n), ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) : ((d : ℝ) - N * (2 / q) ^ k) * (V.ncard.choose m : ℝ) ≤ ∑ W ∈ (Set.toFinite {W : Set (Fin n) | W ⊆ V ∧ W.ncard = m}).toFinset, ({i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}.ncard : ℝ)","line":964,"endLine":1020,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34469","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:38721","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:35149","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:43232"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:44948","line":973,"endLine":974,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:44964","line":975,"endLine":975,"code":"  letI := Fintype.ofFinite (Set (Fin n))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:45005","line":976,"endLine":976,"code":"  let B : Set (Set (Fin n)) := {W | W ⊆ V ∧ W.ncard = m}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:45062","line":977,"endLine":978,"code":"  let bad : Set (Fin d × Set (Fin n)) := {p | p.2 ∈ B ∧\n    k / 2 < (minimalFragment f p.1 p.2).ncard}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:45165","line":979,"endLine":983,"code":"  have hbad : (bad.ncard : ℝ) ≤ (V.ncard.choose m : ℝ) * N * (2 / q) ^ k := by\n    convert bad_fragment_pair_count n d k m V f κ N q hκ hN hq hV hscale hsys hcode using 1\n    congr 2\n    ext p\n    simp only [bad, B, Set.mem_setOf_eq, and_assoc]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:45410","line":984,"endLine":995,"code":"  have hpartition : (bad.ncard : ℝ) =\n      ∑ W ∈ B.toFinset, ({i : Fin d | k / 2 < (minimalFragment f i W).ncard}.ncard : ℝ) := by\n    rw [ncard_eq_sum_ncard_fibers bad B.toFinset Prod.snd\n      (fun p hp ↦ Set.mem_toFinset.mpr hp.1)]\n    apply Finset.sum_congr rfl\n    intro W hW\n    change ({p : Fin d × Set (Fin n) | (p.2 ∈ B ∧\n      k / 2 < (minimalFragment f p.1 p.2).ncard) ∧ p.2 = W}.ncard : ℝ) = _\n    rw [ncard_pair_snd_fiber (fun i W ↦ W ∈ B ∧\n      k / 2 < (minimalFragment f i W).ncard) W]\n    have hWB := Set.mem_toFinset.mp hW\n    simp only [hWB, true_and]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:45982","line":996,"endLine":1009,"code":"  have hcompl (W : Set (Fin n)) :\n      ({i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}.ncard : ℝ) =\n        (d : ℝ) - ({i : Fin d | k / 2 < (minimalFragment f i W).ncard}.ncard : ℝ) := by\n    have he : {i : Fin d | k / 2 < (minimalFragment f i W).ncard} =\n        {i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}ᶜ := by\n      ext i\n      simp\n    have hc := Set.ncard_add_ncard_compl\n      {i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}\n    rw [← he] at hc\n    have hcR : ({i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}.ncard : ℝ) +\n        ({i : Fin d | k / 2 < (minimalFragment f i W).ncard}.ncard : ℝ) = d := by\n      simpa only [Nat.cast_add, Nat.card_fin] using congrArg (fun z : ℕ ↦ (z : ℝ)) hc\n    linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:46715","line":1010,"endLine":1010,"code":"  rw [Set.toFinite_toFinset]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:46744","line":1011,"endLine":1013,"code":"  change ((d : ℝ) - N * (2 / q) ^ k) * (V.ncard.choose m : ℝ) ≤\n    ∑ W ∈ B.toFinset,\n      ({i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}.ncard : ℝ)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:46900","line":1014,"endLine":1014,"code":"  simp_rw [hcompl]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:46919","line":1015,"endLine":1015,"code":"  rw [Finset.sum_sub_distrib, ← hpartition]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:46963","line":1016,"endLine":1017,"code":"  have hBcard : (B.toFinset.card : ℝ) = (V.ncard.choose m : ℝ) := by\n    rw [← Set.ncard_eq_toFinset_card', Set.ncard_powerset_ncard (Set.toFinite V) m]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:47116","line":1018,"endLine":1018,"code":"  simp only [Finset.sum_const, nsmul_eq_mul]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:47161","line":1019,"endLine":1019,"code":"  rw [hBcard]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:47175","line":1020,"endLine":1020,"code":"  nlinarith\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:47187","name":"Submission.Helpers.disjoint_union_pair_count","kind":"theorem","type":"disjoint_union_pair_count (n a b : ℕ) (P : Set (Set (Fin n) × Set (Fin n))) (G : Set (Set (Fin n))) (hG : ∀ U ∈ G, U.ncard = a + b) (hunion : ∀ p ∈ P, p.1 ∪ p.2 ∈ G) (hcard : ∀ p ∈ P, p.1.ncard = a) (hdis : ∀ p ∈ P, Disjoint p.1 p.2) : (P.ncard : ℝ) ≤ (G.ncard : ℝ) * ((a + b).choose a : ℝ)","line":1021,"endLine":1059,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4818"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:47512","line":1027,"endLine":1028,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:47528","line":1029,"endLine":1029,"code":"  letI := Fintype.ofFinite (Set (Fin n))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:47569","line":1030,"endLine":1054,"code":"  have hfiber (U : Set (Fin n)) (hU : U ∈ G) :\n      ({p | p ∈ P ∧ p.1 ∪ p.2 = U}.ncard : ℝ) ≤ ((a + b).choose a : ℝ) := by\n    have hrecover (p : Set (Fin n) × Set (Fin n)) (hp : p ∈ P)\n        (hpU : p.1 ∪ p.2 = U) : p.2 = U \\ p.1 := by\n      ext x\n      constructor\n      · intro hx\n        refine ⟨?_, fun hx₁ ↦ Set.disjoint_left.mp (hdis p hp) hx₁ hx⟩\n        rw [← hpU]\n        exact Or.inr hx\n      · rintro ⟨hxU, hx₁⟩\n        rw [← hpU] at hxU\n        exact hxU.resolve_left hx₁\n    have hc : {p | p ∈ P ∧ p.1 ∪ p.2 = U}.ncard ≤\n        {W : Set (Fin n) | W ⊆ U ∧ W.ncard = a}.ncard := by\n      apply Set.ncard_le_ncard_of_injOn Prod.fst\n      · intro p hp\n        refine ⟨?_, hcard p hp.1⟩\n        rw [← hp.2]\n        exact Set.subset_union_left\n      · intro p hp q hq hpq\n        apply Prod.ext hpq\n        rw [hrecover p hp.1 hp.2, hrecover q hq.1 hq.2, hpq]\n    rw [Set.ncard_powerset_ncard (Set.toFinite U) a, hG U hU] at hc\n    exact_mod_cast hc\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:48530","line":1055,"endLine":1059,"code":"  simpa only [mul_one] using\n    ncard_mul_le_of_fiber_bounds P G (fun p ↦ p.1 ∪ p.2)\n      1 ((a + b).choose a : ℝ) hunion (by\n        intro U hU\n        simpa only [mul_one] using hfiber U hU)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:48725","name":"Submission.Helpers.choose_block_identity","kind":"theorem","type":"choose_block_identity (v m s : ℕ) : (v.choose m : ℝ) * ((v - m).choose s : ℝ) = (v.choose (m + s) : ℝ) * ((m + s).choose m : ℝ)","line":1060,"endLine":1065,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:48873","line":1062,"endLine":1063,"code":" by\n  have h := Nat.choose_mul (n := v) (k := m + s) (s := m) (Nat.le_add_right m s)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:48958","line":1064,"endLine":1065,"code":"  simpa only [Nat.add_sub_cancel_left, Nat.cast_mul] using\n    congrArg (fun z : ℕ ↦ (z : ℝ)) h.symm\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:49059","name":"Submission.Helpers.zero_width_hitting","kind":"theorem","type":"zero_width_hitting (n d s : ℕ) (V : Set (Fin n)) (f : Fin d → Set (Fin n)) (N : ℝ) (hN : 0 ≤ N) (hdN : (d : ℝ) ≤ N) (hf : ∀ i, (f i).ncard = 0) : (d : ℝ) * (V.ncard.choose s : ℝ) ≤ N * ({U : Set (Fin n) | U ⊆ V ∧ U.ncard = s ∧ ∃ i : Fin d, f i ⊆ U}.ncard : ℝ)","line":1066,"endLine":1088,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:49347","line":1070,"endLine":1071,"code":" by\n  by_cases hd : d = 0\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:49373","line":1072,"endLine":1076,"code":"  · subst d\n    simpa only [Nat.cast_zero, zero_mul] using\n      mul_nonneg hN (Nat.cast_nonneg\n        {U : Set (Fin n) | U ⊆ V ∧ U.ncard = s ∧ ∃ i : Fin 0, f i ⊆ U}.ncard :\n          (0 : ℝ) ≤ _)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:49571","line":1077,"endLine":1088,"code":"  · let i : Fin d := ⟨0, Nat.pos_of_ne_zero hd⟩\n    have hempty : f i = ∅ := (Set.ncard_eq_zero (Set.toFinite (f i))).mp (hf i)\n    have hG : {U : Set (Fin n) | U ⊆ V ∧ U.ncard = s ∧ ∃ i : Fin d, f i ⊆ U} =\n        {U : Set (Fin n) | U ⊆ V ∧ U.ncard = s} := by\n      ext U\n      constructor\n      · intro hU\n        exact ⟨hU.1, hU.2.1⟩\n      · intro hU\n        exact ⟨hU.1, hU.2, i, by rw [hempty]; exact Set.empty_subset U⟩\n    rw [hG, Set.ncard_powerset_ncard (Set.toFinite V) s]\n    exact mul_le_mul_of_nonneg_right hdN (Nat.cast_nonneg _)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:50115","name":"Submission.Helpers.labelled_halving_hitting_step","kind":"theorem","type":"labelled_halving_hitting_step (n d w ℓ m : ℕ) (V : Set (Fin n)) (f : Fin d → Set (Fin n)) (κ N q : ℝ) (hκ : 0 < κ) (hN : 0 < N) (hq : 2 ≤ q) (hw : 0 < w) (hV : 0 < V.ncard) (hscale : q ^ 2 * (V.ncard : ℝ) ≤ (m : ℝ) * κ) (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ w) (hcode : ∀ U : Set (Fin n), ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) (hchild : ∀ W ⊆ V, W.ncard = m → ∀ (d' : ℕ) (g : Fin d' → Set (Fin n)), (∀ a, g a ⊆ V \\ W ∧ (g a).ncard ≤ w / 2) → (∀ U : Set (Fin n), ({a : Fin d' | U ⊆ g a}.ncard : ℝ) * κ ^ U.ncard ≤ N) → ((d' : ℝ) - N * (∑ j ∈ Finset.Icc 1 (w / 2), (2 / q) ^ j)) * ((V \\ W).ncard.choose (ℓ * m) : ℝ) ≤ N * ({U : Set (Fin n) | U ⊆ V \\ W ∧ U.ncard = ℓ * m ∧ ∃ a : Fin d', g a ⊆ U}.ncard : ℝ)) : ((d : ℝ) - N * (∑ j ∈ Finset.Icc 1 w, (2 / q) ^ j)) * (V.ncard.choose ((ℓ + 1) * m) : ℝ) ≤ N * ({U : Set (Fin n) | U ⊆ V ∧ U.ncard = (ℓ + 1) * m ∧ ∃ i : Fin d, f i ⊆ U}.ncard : ℝ)","line":1089,"endLine":1198,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:41032","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:34469","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:35149","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:43806","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:44380","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:42636","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:47187","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:48725"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:51128","line":1106,"endLine":1107,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:51144","line":1108,"endLine":1108,"code":"  letI := Fintype.ofFinite (Set (Fin n))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:51185","line":1109,"endLine":1109,"code":"  let B : Set (Set (Fin n)) := {W | W ⊆ V ∧ W.ncard = m}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:51242","line":1110,"endLine":1110,"code":"  let L (k : ℕ) : ℝ := ∑ j ∈ Finset.Icc 1 k, (2 / q) ^ j\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:51299","line":1111,"endLine":1112,"code":"  choose dW gW eW hdata using\n    (fun W : Set (Fin n) ↦ retained_fragment_family n d w V W f κ N hκ.le hsys hcode)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:51415","line":1113,"endLine":1115,"code":"  have hdim (W : Set (Fin n)) :\n      dW W = {i : Fin d | (minimalFragment f i W).ncard ≤ w / 2}.ncard :=\n    (hdata W).2.1\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:51539","line":1116,"endLine":1117,"code":"  let hit (W : Set (Fin n)) : Set (Set (Fin n)) :=\n    {U | U ⊆ V \\ W ∧ U.ncard = ℓ * m ∧ ∃ a : Fin (dW W), gW W a ⊆ U}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:51659","line":1118,"endLine":1118,"code":"  let H : Set (Set (Fin n) × Set (Fin n)) := {p | p.1 ∈ B ∧ p.2 ∈ hit p.1}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:51734","line":1119,"endLine":1120,"code":"  let G : Set (Set (Fin n)) :=\n    {U | U ⊆ V ∧ U.ncard = (ℓ + 1) * m ∧ ∃ i : Fin d, f i ⊆ U}\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:51828","line":1121,"endLine":1130,"code":"  have hHsum : (H.ncard : ℝ) = ∑ W ∈ B.toFinset, ((hit W).ncard : ℝ) := by\n    rw [ncard_eq_sum_ncard_fibers H B.toFinset Prod.fst\n      (fun p hp ↦ Set.mem_toFinset.mpr hp.1)]\n    apply Finset.sum_congr rfl\n    intro W hW\n    change ({p : Set (Fin n) × Set (Fin n) |\n      (p.1 ∈ B ∧ p.2 ∈ hit p.1) ∧ p.1 = W}.ncard : ℝ) = _\n    rw [ncard_pair_fst_fiber (fun W U ↦ W ∈ B ∧ U ∈ hit W) W]\n    have hWB := Set.mem_toFinset.mp hW\n    simp only [hWB, true_and, Set.setOf_mem_eq]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:52303","line":1131,"endLine":1132,"code":"  have hBcard : (B.toFinset.card : ℝ) = (V.ncard.choose m : ℝ) := by\n    rw [← Set.ncard_eq_toFinset_card', Set.ncard_powerset_ncard (Set.toFinite V) m]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:52456","line":1133,"endLine":1136,"code":"  have havg : ((d : ℝ) - N * (2 / q) ^ w) * (V.ncard.choose m : ℝ) ≤\n      ∑ W ∈ B.toFinset, (dW W : ℝ) := by\n    simpa only [hdim, Set.toFinite_toFinset] using\n      retained_fragment_average n d w m V f κ N q hκ hN.le hq hV hscale hsys hcode\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:52700","line":1137,"endLine":1150,"code":"  have hsum : (∑ W ∈ B.toFinset,\n      ((dW W : ℝ) - N * L (w / 2)) * ((V.ncard - m).choose (ℓ * m) : ℝ)) ≤\n      ∑ W ∈ B.toFinset, N * ((hit W).ncard : ℝ) := by\n    apply Finset.sum_le_sum\n    intro W hW\n    have hWB := Set.mem_toFinset.mp hW\n    have hc := hchild W hWB.1 hWB.2 (dW W) (gW W)\n      (hdata W).2.2.2.1 (hdata W).2.2.2.2.1\n    have hrem : (V \\ W).ncard = V.ncard - m := by\n      have hc := Set.ncard_sdiff_add_ncard_of_subset hWB.1\n      rw [hWB.2] at hc\n      omega\n    rw [hrem] at hc\n    exact hc\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:53215","line":1151,"endLine":1152,"code":"  rw [← Finset.sum_mul, Finset.sum_sub_distrib, Finset.sum_const, nsmul_eq_mul,\n    hBcard, ← Finset.mul_sum, ← hHsum] at hsum\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:53342","line":1153,"endLine":1154,"code":"  have hloss : L (w / 2) + (2 / q) ^ w ≤ L w :=\n    dyadic_loss_step w hw (2 / q) (div_nonneg (by norm_num) (by linarith))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:53465","line":1155,"endLine":1155,"code":"  have hloss_scaled := mul_le_mul_of_nonneg_left hloss hN.le\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:53526","line":1156,"endLine":1157,"code":"  have hloss_scaled' := mul_le_mul_of_nonneg_left hloss_scaled\n    (Nat.cast_nonneg (V.ncard.choose m) : (0 : ℝ) ≤ V.ncard.choose m)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:53659","line":1158,"endLine":1163,"code":"  have hlower :\n      ((d : ℝ) - N * L w) * (V.ncard.choose m : ℝ) *\n          ((V.ncard - m).choose (ℓ * m) : ℝ) ≤ N * (H.ncard : ℝ) := by\n    apply le_trans ?_ hsum\n    apply mul_le_mul_of_nonneg_right ?_ (Nat.cast_nonneg _)\n    nlinarith [havg, hloss_scaled']\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:53922","line":1164,"endLine":1164,"code":"  have htotal : (ℓ + 1) * m = m + ℓ * m := by ring\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:53973","line":1165,"endLine":1166,"code":"  have hdis (p : Set (Fin n) × Set (Fin n)) (hp : p ∈ H) : Disjoint p.1 p.2 := by\n    exact Set.disjoint_left.mpr fun x hxW hxU ↦ (hp.2.1 hxU).2 hxW\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:54122","line":1167,"endLine":1183,"code":"  have hHbound : (H.ncard : ℝ) ≤ (G.ncard : ℝ) * ((m + ℓ * m).choose m : ℝ) := by\n    apply disjoint_union_pair_count n m (ℓ * m) H G\n    · intro U hU\n      exact hU.2.1.trans htotal\n    · intro p hp\n      refine ⟨Set.union_subset hp.1.1 (fun x hx ↦ (hp.2.1 hx).1), ?_, ?_⟩\n      · rw [Set.ncard_union_eq (hdis p hp), hp.1.2, hp.2.2.1, htotal]\n      · obtain ⟨a, ha⟩ := hp.2.2.2\n        obtain ⟨i, hi⟩ := (hdata p.1).2.2.2.2.2 a\n        refine ⟨i, ?_⟩\n        intro x hx\n        rcases hi hx with hxg | hxW\n        · exact Or.inr (ha hxg)\n        · exact Or.inl hxW\n    · intro p hp\n      exact hp.1.2\n    · exact hdis\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:54741","line":1184,"endLine":1184,"code":"  change ((d : ℝ) - N * L w) * (V.ncard.choose ((ℓ + 1) * m) : ℝ) ≤ N * (G.ncard : ℝ)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:54827","line":1185,"endLine":1186,"code":"  have hchoosepos : (0 : ℝ) < ((m + ℓ * m).choose m : ℝ) := by\n    exact_mod_cast Nat.choose_pos (Nat.le_add_right m (ℓ * m))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:54953","line":1187,"endLine":1187,"code":"  apply (mul_le_mul_iff_left₀ hchoosepos).mp\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:54998","line":1188,"endLine":1198,"code":"  calc\n    (((d : ℝ) - N * L w) * (V.ncard.choose ((ℓ + 1) * m) : ℝ)) *\n        ((m + ℓ * m).choose m : ℝ) =\n        ((d : ℝ) - N * L w) * (V.ncard.choose m : ℝ) *\n          ((V.ncard - m).choose (ℓ * m) : ℝ) := by\n      rw [htotal, mul_assoc, ← choose_block_identity]\n      ring\n    _ ≤ N * (H.ncard : ℝ) := hlower\n    _ ≤ N * ((G.ncard : ℝ) * ((m + ℓ * m).choose m : ℝ)) :=\n      mul_le_mul_of_nonneg_left hHbound hN.le\n    _ = (N * (G.ncard : ℝ)) * ((m + ℓ * m).choose m : ℝ) := by ring\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:55488","name":"Submission.Helpers.labelled_halving_hitting","kind":"theorem","type":"labelled_halving_hitting (n d w ℓ m : ℕ) (V : Set (Fin n)) (f : Fin d → Set (Fin n)) (κ N q : ℝ) (hκ : 0 < κ) (hN : 0 < N) (hq : 2 ≤ q) (hm : 0 < m) (hroom : ℓ * m ≤ V.ncard) (hw : w < 2 ^ ℓ) (hscale : q ^ 2 * (V.ncard : ℝ) ≤ (m : ℝ) * κ) (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ w) (hcode : ∀ U : Set (Fin n), ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) : ((d : ℝ) - N * (∑ j ∈ Finset.Icc 1 w, (2 / q) ^ j)) * (V.ncard.choose (ℓ * m) : ℝ) ≤ N * ({U : Set (Fin n) | U ⊆ V ∧ U.ncard = ℓ * m ∧ ∃ i : Fin d, f i ⊆ U}.ncard : ℝ)","line":1199,"endLine":1240,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:49059","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:50115"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:56080","line":1209,"endLine":1240,"code":" by\n  induction ℓ generalizing d w V f with\n  | zero =>\n    have hwzero : w = 0 := by simpa using hw\n    subst w\n    have hdN : (d : ℝ) ≤ N := by simpa using hcode ∅\n    simpa using zero_width_hitting n d 0 V f N hN.le hdN\n      (fun i ↦ Nat.eq_zero_of_le_zero (hsys i).2)\n  | succ ℓ ih =>\n    by_cases hwzero : w = 0\n    · subst w\n      have hdN : (d : ℝ) ≤ N := by simpa using hcode ∅\n      simpa using zero_width_hitting n d ((ℓ + 1) * m) V f N hN.le hdN\n        (fun i ↦ Nat.eq_zero_of_le_zero (hsys i).2)\n    · have hV : 0 < V.ncard := by\n        have hmle : m ≤ (ℓ + 1) * m := by rw [Nat.add_mul]; omega\n        exact hm.trans_le (hmle.trans hroom)\n      apply labelled_halving_hitting_step n d w ℓ m V f κ N q hκ hN hq\n        (Nat.pos_of_ne_zero hwzero) hV hscale hsys hcode\n      intro W hWV hWcard d' g hgsys hgcode\n      apply ih (d := d') (w := w / 2) (V := V \\ W) (f := g)\n      · have hc := Set.ncard_sdiff_add_ncard_of_subset hWV\n        rw [hWcard] at hc\n        rw [Nat.succ_mul] at hroom\n        omega\n      · rw [pow_succ] at hw\n        omega\n      · apply le_trans _ hscale\n        apply mul_le_mul_of_nonneg_left _ (sq_nonneg q)\n        exact_mod_cast Set.ncard_le_ncard (Set.sdiff_subset : V \\ W ⊆ V)\n      · exact hgsys\n      · exact hgcode\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:57344","name":"Submission.Helpers.spread_parameter_le_ground_size","kind":"theorem","type":"spread_parameter_le_ground_size (n : ℕ) (ℋ : Set (Set (Fin n))) (κ : ℝ) (hκ : 0 ≤ κ) (hne : ℋ.Nonempty) (hempty : (∅ : Set (Fin n)) ∉ ℋ) (hcode : ∀ U : Set (Fin n), ({A : Set (Fin n) | A ∈ ℋ ∧ U ⊆ A}.ncard : ℝ) * κ ^ U.ncard ≤ (ℋ.ncard : ℝ)) : κ ≤ n","line":1241,"endLine":1277,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:4818"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:57626","line":1245,"endLine":1246,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:57642","line":1247,"endLine":1247,"code":"  letI := Fintype.ofFinite ℋ\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:57671","line":1248,"endLine":1251,"code":"  have hA (A : ℋ) : (A : Set (Fin n)).Nonempty := by\n    apply Set.nonempty_iff_ne_empty.mpr\n    intro he\n    exact hempty (he ▸ A.property)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:57812","line":1252,"endLine":1252,"code":"  let p (A : ℋ) : Fin n := (hA A).choose\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:57853","line":1253,"endLine":1253,"code":"  have hp (A : ℋ) : p A ∈ (A : Set (Fin n)) := (hA A).choose_spec\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:57919","line":1254,"endLine":1270,"code":"  have htotal := ncard_mul_le_of_fiber_bounds\n    (Set.univ : Set ℋ) (Set.univ : Set (Fin n)) p κ (ℋ.ncard : ℝ)\n    (fun _ _ ↦ Set.mem_univ _) (by\n      intro x _\n      have hfib : {A : ℋ | A ∈ Set.univ ∧ p A = x}.ncard ≤\n          {A : Set (Fin n) | A ∈ ℋ ∧ ({x} : Set (Fin n)) ⊆ A}.ncard := by\n        apply Set.ncard_le_ncard_of_injOn (fun A : ℋ ↦ A.val)\n        · intro A hAx\n          refine ⟨A.property, Set.singleton_subset_iff.mpr ?_⟩\n          exact hAx.2 ▸ hp A\n        · intro A _ B _ hAB\n          exact Subtype.ext hAB\n      have hmul := mul_le_mul_of_nonneg_right\n        (show ({A : ℋ | A ∈ Set.univ ∧ p A = x}.ncard : ℝ) ≤\n          ({A : Set (Fin n) | A ∈ ℋ ∧ ({x} : Set (Fin n)) ⊆ A}.ncard : ℝ)\n          by exact_mod_cast hfib) hκ\n      exact hmul.trans (by simpa using hcode {x}))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:58720","line":1271,"endLine":1272,"code":"  have hsource : (Set.univ : Set ℋ).ncard = ℋ.ncard := by\n    rw [Set.ncard_univ, Nat.card_coe_set_eq]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:58823","line":1273,"endLine":1273,"code":"  have htarget : (Set.univ : Set (Fin n)).ncard = n := by simp\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:58886","line":1274,"endLine":1274,"code":"  rw [hsource, htarget] at htotal\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:58920","line":1275,"endLine":1276,"code":"  have hmass : (0 : ℝ) < (ℋ.ncard : ℝ) := by\n    exact_mod_cast (Set.ncard_pos).mpr hne\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:59008","line":1277,"endLine":1277,"code":"  nlinarith\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:59020","name":"Submission.Helpers.spread_matching_block_parameters","kind":"theorem","type":"spread_matching_block_parameters (r n ℓ : ℕ) (κ : ℝ) (hr : 3 ≤ r) (hℓ : 0 < ℓ) (hκ : 0 < κ) (hκn : κ ≤ n) (hlarge : 260 * (r : ℝ) ^ 3 * (ℓ : ℝ) ≤ κ) : ∃ m : ℕ, 0 < m ∧ r * (ℓ * m) ≤ n ∧ ℓ * m ≤ n ∧ (8 * (r : ℝ)) ^ 2 * (n : ℝ) ≤ (m : ℝ) * κ","line":1278,"endLine":1317,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:59288","line":1282,"endLine":1283,"code":" by\n  have hrR : (3 : ℝ) ≤ r := by exact_mod_cast hr\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:59341","line":1284,"endLine":1284,"code":"  have hℓR : (1 : ℝ) ≤ ℓ := by exact_mod_cast hℓ\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:59390","line":1285,"endLine":1285,"code":"  have hn : (0 : ℝ) < n := hκ.trans_le hκn\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:59433","line":1286,"endLine":1286,"code":"  let x : ℝ := 64 * (r : ℝ) ^ 2 * (n : ℝ) / κ\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:59479","line":1287,"endLine":1287,"code":"  have hx : 0 < x := by dsimp [x]; positivity\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:59525","line":1288,"endLine":1288,"code":"  let m : ℕ := Nat.ceil x\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:59551","line":1289,"endLine":1289,"code":"  have hm : 0 < m := Nat.ceil_pos.mpr hx\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:59592","line":1290,"endLine":1291,"code":"  have hlower : 64 * (r : ℝ) ^ 2 * (n : ℝ) ≤ (m : ℝ) * κ := by\n    exact (div_le_iff₀ hκ).mp (Nat.le_ceil x)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:59701","line":1292,"endLine":1300,"code":"  have hupper : (m : ℝ) * κ ≤ 65 * (r : ℝ) ^ 2 * (n : ℝ) := by\n    have hmceil : (m : ℝ) < x + 1 := Nat.ceil_lt_add_one hx.le\n    have hceil := (mul_lt_mul_iff_left₀ hκ).mpr hmceil\n    have hxeq : x * κ = 64 * (r : ℝ) ^ 2 * (n : ℝ) := by\n      dsimp [x]\n      exact div_mul_cancel₀ _ hκ.ne'\n    have hr2 : (1 : ℝ) ≤ (r : ℝ) ^ 2 := by nlinarith\n    have hlast := mul_le_mul_of_nonneg_right hr2 hn.le\n    nlinarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:60114","line":1301,"endLine":1303,"code":"  have hcoef : 65 * (r : ℝ) ^ 3 * (ℓ : ℝ) ≤ κ := by\n    have hnonneg : (0 : ℝ) ≤ (r : ℝ) ^ 3 * (ℓ : ℝ) := by positivity\n    linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:60247","line":1304,"endLine":1313,"code":"  have hroomR : (r : ℝ) * ((ℓ : ℝ) * (m : ℝ)) ≤ n := by\n    apply (mul_le_mul_iff_left₀ hκ).mp\n    calc\n      (r : ℝ) * ((ℓ : ℝ) * (m : ℝ)) * κ =\n          ((r : ℝ) * (ℓ : ℝ)) * ((m : ℝ) * κ) := by ring\n      _ ≤ ((r : ℝ) * (ℓ : ℝ)) * (65 * (r : ℝ) ^ 2 * (n : ℝ)) :=\n        mul_le_mul_of_nonneg_left hupper (by positivity)\n      _ = (65 * (r : ℝ) ^ 3 * (ℓ : ℝ)) * (n : ℝ) := by ring\n      _ ≤ κ * (n : ℝ) := mul_le_mul_of_nonneg_right hcoef hn.le\n      _ = (n : ℝ) * κ := by ring\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:60728","line":1314,"endLine":1314,"code":"  have hroom : r * (ℓ * m) ≤ n := by exact_mod_cast hroomR\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:60787","line":1315,"endLine":1315,"code":"  refine ⟨m, hm, hroom, ?_, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:60819","line":1316,"endLine":1316,"code":"  · exact (Nat.le_mul_of_pos_left (ℓ * m) (by omega : 0 < r)).trans hroom\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:60893","line":1317,"endLine":1317,"code":"  · nlinarith [hlower]\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:60916","name":"Submission.Helpers.matching_of_dense_hitting_sets","kind":"theorem","type":"matching_of_dense_hitting_sets (n r s : ℕ) (ℋ : Set (Set (Fin n))) (hempty : (∅ : Set (Fin n)) ∉ ℋ) (hroom : r * s ≤ n) (hdense : (r : ℝ) * ((n.choose s : ℝ) - ({U : Set (Fin n) | U.ncard = s ∧ ∃ A ∈ ℋ, A ⊆ U}.ncard : ℝ)) < (n.choose s : ℝ)) : ∃ P ⊆ ℋ, P.ncard = r ∧ P.Pairwise Disjoint","line":1318,"endLine":1343,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:27524"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:61239","line":1323,"endLine":1324,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:61255","line":1325,"endLine":1327,"code":"  obtain ⟨B, hB, hBdis⟩ := disjoint_blocks_from_dense_family n r s\n    {U : Set (Fin n) | U.ncard = s ∧ ∃ A ∈ ℋ, A ⊆ U}\n    hroom (fun U hU ↦ hU.1) hdense\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:61410","line":1328,"endLine":1328,"code":"  choose A hA hAsub using fun i ↦ (hB i).2\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:61453","line":1329,"endLine":1330,"code":"  have hAdis (i j : Fin r) (hij : i ≠ j) : Disjoint (A i) (A j) :=\n    (hBdis i j hij).mono (hAsub i) (hAsub j)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:61565","line":1331,"endLine":1336,"code":"  have hAinj : Function.Injective A := by\n    intro i j heq\n    by_contra hij\n    have hself : Disjoint (A i) (A i) := by simpa only [← heq] using hAdis i j hij\n    have hzero : A i = ∅ := disjoint_self.mp hself\n    exact hempty (hzero ▸ hA i)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:61809","line":1337,"endLine":1337,"code":"  refine ⟨Set.range A, ?_, ?_, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:61844","line":1338,"endLine":1339,"code":"  · rintro _ ⟨i, rfl⟩\n    exact hA i\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:61881","line":1340,"endLine":1341,"code":"  · rw [Set.ncard_range_of_injective hAinj]\n    simp\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:61934","line":1342,"endLine":1343,"code":"  · rintro _ ⟨i, rfl⟩ _ ⟨j, rfl⟩ hne\n    exact hAdis i j (fun hij ↦ hne (congrArg A hij))\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:62024","name":"Submission.Helpers.geometric_spread_loss","kind":"theorem","type":"geometric_spread_loss (r w : ℕ) (hr : 3 ≤ r) : (r : ℝ) * (∑ j ∈ Finset.Icc 1 w, (2 / (8 * (r : ℝ))) ^ j) ≤ 1 / 2","line":1344,"endLine":1369,"references":[],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:62151","line":1345,"endLine":1346,"code":" by\n  have hrR : (3 : ℝ) ≤ r := by exact_mod_cast hr\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:62204","line":1347,"endLine":1347,"code":"  have hrpos : (0 : ℝ) < r := by linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:62246","line":1348,"endLine":1348,"code":"  let z : ℝ := 2 / (8 * (r : ℝ))\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:62279","line":1349,"endLine":1349,"code":"  have hz : 0 ≤ z := by dsimp [z]; positivity\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:62325","line":1350,"endLine":1353,"code":"  have hzhalf : z ≤ 1 / 2 := by\n    dsimp [z]\n    apply (div_le_iff₀ (by positivity : (0 : ℝ) < 8 * (r : ℝ))).mpr\n    linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:62452","line":1354,"endLine":1354,"code":"  have hzlt : z < 1 := by linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:62487","line":1355,"endLine":1358,"code":"  have hsum : (∑ j ∈ Finset.Icc 1 w, z ^ j) ≤ z / (1 - z) := by\n    rw [← Finset.Ico_add_one_right_eq_Icc]\n    simpa only [pow_one] using\n      (geom_sum_Ico_le_of_lt_one (m := 1) (n := w + 1) hz hzlt)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:62689","line":1359,"endLine":1361,"code":"  have hratio : z / (1 - z) ≤ 2 * z := by\n    apply (div_le_iff₀ (by linarith : 0 < 1 - z)).mpr\n    nlinarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:62799","line":1362,"endLine":1365,"code":"  have hrz : (r : ℝ) * (2 * z) = 1 / 2 := by\n    dsimp [z]\n    field_simp\n    <;> ring\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:62886","line":1366,"endLine":1369,"code":"  calc\n    (r : ℝ) * (∑ j ∈ Finset.Icc 1 w, z ^ j) ≤ (r : ℝ) * (2 * z) :=\n      mul_le_mul_of_nonneg_left (hsum.trans hratio) hrpos.le\n    _ = 1 / 2 := hrz\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:63042","name":"Submission.Helpers.spread_hitting_density","kind":"theorem","type":"spread_hitting_density (r n w ℓ m : ℕ) (ℋ : Set (Set (Fin n))) (κ : ℝ) (hr : 3 ≤ r) (hκ : 0 < κ) (hne : ℋ.Nonempty) (hm : 0 < m) (hroom : ℓ * m ≤ n) (hw : w < 2 ^ ℓ) (hscale : (8 * (r : ℝ)) ^ 2 * (n : ℝ) ≤ (m : ℝ) * κ) (hsys : Set.IsSystem w ℋ) (hcode : ∀ U : Set (Fin n), ({A : Set (Fin n) | A ∈ ℋ ∧ U ⊆ A}.ncard : ℝ) * κ ^ U.ncard ≤ (ℋ.ncard : ℝ)) : (r : ℝ) * ((n.choose (ℓ * m) : ℝ) - ({U : Set (Fin n) | U.ncard = ℓ * m ∧ ∃ A ∈ ℋ, A ⊆ U}.ncard : ℝ)) < (n.choose (ℓ * m) : ℝ)","line":1370,"endLine":1442,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:55488","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:62024"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:63583","line":1380,"endLine":1381,"code":" by\n  classical\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:63599","line":1382,"endLine":1382,"code":"  letI := Fintype.ofFinite ℋ\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:63628","line":1383,"endLine":1383,"code":"  let b : Fin (Fintype.card ℋ) ≃ ℋ := (Fintype.equivFin ℋ).symm\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:63692","line":1384,"endLine":1384,"code":"  let f (i : Fin (Fintype.card ℋ)) : Set (Fin n) := (b i).val\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:63754","line":1385,"endLine":1386,"code":"  have hd : Fintype.card ℋ = ℋ.ncard := by\n    rw [← Nat.card_eq_fintype_card, Nat.card_coe_set_eq]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:63854","line":1387,"endLine":1388,"code":"  have hmass : (0 : ℝ) < (ℋ.ncard : ℝ) := by\n    exact_mod_cast (Set.ncard_pos).mpr hne\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:63942","line":1389,"endLine":1400,"code":"  have henum (U : Set (Fin n)) :\n      {i : Fin (Fintype.card ℋ) | U ⊆ f i}.ncard =\n        {A : Set (Fin n) | A ∈ ℋ ∧ U ⊆ A}.ncard := by\n    apply Set.ncard_congr (fun i _ ↦ f i)\n    · intro i hi\n      exact ⟨(b i).property, hi⟩\n    · intro i j _ _ heq\n      exact b.injective (Subtype.ext heq)\n    · intro A hA\n      obtain ⟨i, hi⟩ := b.surjective ⟨A, hA.1⟩\n      have hfi : f i = A := congrArg Subtype.val hi\n      exact ⟨i, by simpa only [Set.mem_setOf_eq, hfi] using hA.2, hfi⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:64425","line":1401,"endLine":1401,"code":"  have hVcard : (Set.univ : Set (Fin n)).ncard = n := by simp\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:64487","line":1402,"endLine":1413,"code":"  have hgood :\n      {U : Set (Fin n) | U ⊆ Set.univ ∧ U.ncard = ℓ * m ∧\n        ∃ i : Fin (Fintype.card ℋ), f i ⊆ U} =\n      {U : Set (Fin n) | U.ncard = ℓ * m ∧ ∃ A ∈ ℋ, A ⊆ U} := by\n    ext U\n    constructor\n    · rintro ⟨_, hsize, i, hi⟩\n      exact ⟨hsize, f i, (b i).property, hi⟩\n    · rintro ⟨hsize, A, hA, hAU⟩\n      obtain ⟨i, hi⟩ := b.surjective ⟨A, hA⟩\n      have hfi : f i = A := congrArg Subtype.val hi\n      exact ⟨Set.subset_univ U, hsize, i, hfi ▸ hAU⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:64957","line":1414,"endLine":1414,"code":"  have hrR : (3 : ℝ) ≤ r := by exact_mod_cast hr\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:65006","line":1415,"endLine":1420,"code":"  have hhit := labelled_halving_hitting n (Fintype.card ℋ) w ℓ m Set.univ f κ\n    (ℋ.ncard : ℝ) (8 * (r : ℝ)) hκ hmass (by linarith) hm\n    (by simpa only [hVcard] using hroom) hw\n    (by simpa only [hVcard] using hscale)\n    (fun i ↦ ⟨Set.subset_univ _, hsys _ (b i).property⟩)\n    (fun U ↦ by rw [henum U]; exact hcode U)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:65330","line":1421,"endLine":1421,"code":"  rw [hVcard, hgood, hd] at hhit\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:65363","line":1422,"endLine":1422,"code":"  let E : ℝ := ∑ j ∈ Finset.Icc 1 w, (2 / (8 * (r : ℝ))) ^ j\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:65424","line":1423,"endLine":1423,"code":"  let B : ℝ := (n.choose (ℓ * m) : ℝ)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:65462","line":1424,"endLine":1425,"code":"  let G : ℝ :=\n    ({U : Set (Fin n) | U.ncard = ℓ * m ∧ ∃ A ∈ ℋ, A ⊆ U}.ncard : ℝ)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:65546","line":1426,"endLine":1431,"code":"  have hnormalized : (1 - E) * B ≤ G := by\n    apply (mul_le_mul_iff_right₀ hmass).mp\n    change (ℋ.ncard : ℝ) * ((1 - E) * B) ≤ (ℋ.ncard : ℝ) * G\n    change ((ℋ.ncard : ℝ) - (ℋ.ncard : ℝ) * E) * B ≤\n      (ℋ.ncard : ℝ) * G at hhit\n    nlinarith only [hhit]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:65804","line":1432,"endLine":1434,"code":"  have hB : 0 < B := by\n    change (0 : ℝ) < (n.choose (ℓ * m) : ℝ)\n    exact_mod_cast Nat.choose_pos hroom\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:65912","line":1435,"endLine":1435,"code":"  have hloss : (r : ℝ) * E ≤ 1 / 2 := geometric_spread_loss r w hr\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:65979","line":1436,"endLine":1439,"code":"  have hbad : (r : ℝ) * (B - G) ≤ ((r : ℝ) * E) * B := by\n    have hdiff : B - G ≤ E * B := by nlinarith only [hnormalized]\n    have hmul := mul_le_mul_of_nonneg_left hdiff (by positivity : (0 : ℝ) ≤ r)\n    nlinarith only [hmul]\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:66208","line":1440,"endLine":1440,"code":"  have hbound := mul_le_mul_of_nonneg_right hloss hB.le\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:66264","line":1441,"endLine":1441,"code":"  change (r : ℝ) * (B - G) < B\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:66295","line":1442,"endLine":1442,"code":"  nlinarith only [hbad, hbound, hB]\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:66331","name":"Submission.Helpers.dyadic_spread_matching","kind":"theorem","type":"dyadic_spread_matching (r n w ℓ : ℕ) (ℋ : Set (Set (Fin n))) (κ : ℝ) (hr : 3 ≤ r) (hw : 0 < w) (hdyadic : w < 2 ^ ℓ) (hκ : 0 < κ) (hlarge : 260 * (r : ℝ) ^ 3 * (ℓ : ℝ) ≤ κ) (hne : ℋ.Nonempty) (hempty : (∅ : Set (Fin n)) ∉ ℋ) (hsys : Set.IsSystem w ℋ) (hcode : ∀ U : Set (Fin n), ({A : Set (Fin n) | A ∈ ℋ ∧ U ⊆ A}.ncard : ℝ) * κ ^ U.ncard ≤ (ℋ.ncard : ℝ)) : ∃ P ⊆ ℋ, P.ncard = r ∧ P.Pairwise Disjoint","line":1443,"endLine":1460,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:57344","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:59020","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:60916","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:63042"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:66776","line":1450,"endLine":1455,"code":" by\n  have hℓ : 0 < ℓ := by\n    by_contra hzero\n    have heq : ℓ = 0 := by omega\n    simp only [heq, pow_zero] at hdyadic\n    omega\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:66908","line":1456,"endLine":1456,"code":"  have hκn := spread_parameter_le_ground_size n ℋ κ hκ.le hne hempty hcode\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:66983","line":1457,"endLine":1458,"code":"  obtain ⟨m, hm, hroom, hroom', hscale⟩ :=\n    spread_matching_block_parameters r n ℓ κ hr hℓ hκ hκn hlarge\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67091","line":1459,"endLine":1460,"code":"  exact matching_of_dense_hitting_sets n r (ℓ * m) ℋ hempty hroom\n    (spread_hitting_density r n w ℓ m ℋ κ hr hκ hne hm hroom' hdyadic hscale hsys hcode)\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67246","name":"Submission.Helpers.exists_uniform_sunflower_constant","kind":"theorem","type":"exists_uniform_sunflower_constant : ∃ c : ℝ, 0 < c ∧ ∀ (r : ℕ), 3 ≤ r → ∀ (n : ℕ) (ℱ : Set (Set (Fin n))) (w : ℕ), 2 ≤ w → Set.IsSystem w ℱ → _root_.ImprovedBoundsSunflowerLemma.lowerBound r c w ≤ (ℱ.ncard : ℝ) → ∃ S ⊆ ℱ, Set.IsSunflower r S","line":1461,"endLine":1489,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:20609","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:7544","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:66331","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:19140"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67524","line":1465,"endLine":1466,"code":" by\n  refine ⟨40000, by norm_num, ?_⟩\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67562","line":1467,"endLine":1467,"code":"  intro r hr n ℱ w hw hsys hsize\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67595","line":1468,"endLine":1468,"code":"  let ℓ : ℕ := Nat.log 2 w + 1\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67626","line":1469,"endLine":1469,"code":"  let κ : ℝ := 520 * (r : ℝ) ^ 3 * (ℓ : ℝ)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67669","line":1470,"endLine":1470,"code":"  obtain ⟨hκ, hthreshold, hdyadic⟩ := scalar_threshold_comparison r w hr hw\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67745","line":1471,"endLine":1471,"code":"  change 2 ≤ κ at hκ\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67766","line":1472,"endLine":1473,"code":"  change κ < 40000 * (r : ℝ) ^ 3 * Real.logb (1.9 : ℝ) (w : ℝ) *\n    Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ)) at hthreshold\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67899","line":1474,"endLine":1474,"code":"  change w < 2 ^ ℓ at hdyadic\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67929","line":1475,"endLine":1475,"code":"  have hκpos : 0 < κ := by linarith\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67965","line":1476,"endLine":1478,"code":"  have hstrict : κ ^ w < (ℱ.ncard : ℝ) := by\n    apply lt_of_lt_of_le ?_ hsize\n    exact pow_lt_pow_left₀ hthreshold hκpos.le (by omega : w ≠ 0)\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:68110","line":1479,"endLine":1480,"code":"  obtain ⟨T, ℋ, hne, hempty, hsysH, hprop, hcode⟩ :=\n    extract_spread_petals n w ℱ κ hκ hsys hstrict\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:68213","line":1481,"endLine":1484,"code":"  have hscale : 260 * (r : ℝ) ^ 3 * (ℓ : ℝ) ≤ κ / 2 := by\n    dsimp [κ]\n    ring_nf\n    exact le_rfl\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:68314","line":1485,"endLine":1487,"code":"  obtain ⟨P, hPH, hcard, hdis⟩ :=\n    dyadic_spread_matching r n w ℓ ℋ (κ / 2) hr (by omega) hdyadic\n      (div_pos hκpos (by norm_num)) hscale hne hempty hsysH hcode\n"},{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:68481","line":1488,"endLine":1489,"code":"  exact sunflower_of_disjoint_petals n r ℱ T P (by omega) hcard hdis\n    (fun A hA ↦ hprop A (hPH hA))\n"}]},{"id":"declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:68584","name":"Submission.Helpers.chosen_constant_sunflower","kind":"theorem","type":"chosen_constant_sunflower (r : ℕ) (hr : 3 ≤ r) (X : Type*) [Finite X] (ℱ : Set (Set X)) (w : ℕ) (hw : 2 ≤ w) (hℱ₁ : Set.IsSystem w ℱ) (hℱ₂ : _root_.ImprovedBoundsSunflowerLemma.lowerBound r (Classical.choose Submission.Helpers.exists_uniform_sunflower_constant) w ≤ (ℱ.ncard : ℝ)) : ∃ S ⊆ ℱ, Set.IsSunflower r S","line":1490,"endLine":1500,"references":["declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:67246","declaration:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:869"],"steps":[{"id":"proof-step:9059e07d4ef5973c4a44e2eb54a47baf9355d93c2004bce141516e655e805b42:68936","line":1496,"endLine":1500,"code":" by\n  exact transfer_from_numbered_ground_sets\n    (Classical.choose exists_uniform_sunflower_constant)\n    (Classical.choose_spec exists_uniform_sunflower_constant).2\n    r hr X ℱ w hw hℱ₁ hℱ₂\n"}]}],"code":"import Mathlib.Algebra.Order.Floor.Semiring\nimport Mathlib.Algebra.Order.Field.GeomSum\nimport Mathlib.Data.Nat.Choose.Sum\nimport Mathlib.Data.Fintype.Perm\nimport Mathlib.Logic.Equiv.Fintype\nimport Mathlib.Data.Finset.Max\nimport Mathlib.Analysis.SpecialFunctions.Log.Base\nimport Mathlib.Data.Fintype.EquivFin\nimport Mathlib.Data.Set.Card\nimport ChallengeDeps\nnamespace Submission.Helpers\n\ntheorem isSunflower_preimage_equiv {X Y : Type*} (e : X ≃ Y) {r : ℕ}\n    {S : Set (Set Y)} (hS : Set.IsSunflower r S) :\n    Set.IsSunflower r (Set.preimage e '' S) := by\n  refine ⟨?_, ?_⟩\n  · rw [Set.ncard_image_of_injective S (Set.preimage_injective.mpr e.surjective)]\n    exact hS.1\n  · rintro _ ⟨A, hA, rfl⟩ _ ⟨B, hB, rfl⟩ hAB\n    have hne : A ≠ B := fun h ↦ hAB (congrArg (Set.preimage e) h)\n    rw [← Set.preimage_inter, hS.2 hA hB hne, Set.preimage_sInter, Set.sInter_image]\ntheorem transfer_from_numbered_ground_sets\n    (c : ℝ)\n    (hc : ∀ (r : ℕ), 3 ≤ r → ∀ (n : ℕ) (ℱ : Set (Set (Fin n))) (w : ℕ),\n      2 ≤ w → Set.IsSystem w ℱ →\n      _root_.ImprovedBoundsSunflowerLemma.lowerBound r c w ≤ (ℱ.ncard : ℝ) →\n      ∃ S ⊆ ℱ, Set.IsSunflower r S)\n    (r : ℕ) (hr : 3 ≤ r) (X : Type*) [Finite X] (ℱ : Set (Set X)) (w : ℕ)\n    (hw : 2 ≤ w) (hℱ₁ : Set.IsSystem w ℱ)\n    (hℱ₂ : _root_.ImprovedBoundsSunflowerLemma.lowerBound r c w ≤ (ℱ.ncard : ℝ)) :\n    ∃ S ⊆ ℱ, Set.IsSunflower r S := by\n  classical\n  letI := Fintype.ofFinite X\n  let e : X ≃ Fin (Fintype.card X) := Fintype.equivFin X\n  let ℱ' : Set (Set (Fin (Fintype.card X))) := Set.image (Set.image e) ℱ\n  have hℱ₁' : Set.IsSystem w ℱ' := by\n    rintro _ ⟨A, hA, rfl⟩\n    rw [Set.ncard_image_of_injective A e.injective]\n    exact hℱ₁ A hA\n  have hℱ₂' :\n      _root_.ImprovedBoundsSunflowerLemma.lowerBound r c w ≤ (ℱ'.ncard : ℝ) := by\n    change _ ≤ ((Set.image (Set.image e) ℱ).ncard : ℝ)\n    rw [Set.ncard_image_of_injective ℱ e.injective.image_injective]\n    exact hℱ₂\n  obtain ⟨S, hSℱ, hS⟩ := hc r hr (Fintype.card X) ℱ' w hw hℱ₁' hℱ₂'\n  refine ⟨Set.preimage e '' S, ?_, isSunflower_preimage_equiv e hS⟩\n  rintro _ ⟨A, hA, rfl⟩\n  obtain ⟨B, hB, hBA⟩ := hSℱ hA\n  simpa only [← hBA, Set.preimage_image_eq B e.injective] using hB\ntheorem one_lt_logb_of_two_le (w : ℕ) (hw : 2 ≤ w) :\n    1 < Real.logb (1.9 : ℝ) (w : ℝ) := by\n  have hwR : (2 : ℝ) ≤ (w : ℝ) := by exact_mod_cast hw\n  apply (Real.lt_logb_iff_rpow_lt (by norm_num : (1 : ℝ) < 1.9)\n    (by linarith : 0 < (w : ℝ))).2\n  simpa using (lt_of_lt_of_le (by norm_num : (1.9 : ℝ) < 2) hwR)\ntheorem positive_log_factors (w : ℕ) (hw : 2 ≤ w) :\n    0 < Real.logb (1.9 : ℝ) (w : ℝ) ∧\n      0 < Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ)) := by\n  have hlog := one_lt_logb_of_two_le w hw\n  exact ⟨lt_trans zero_lt_one hlog, Real.logb_pos (by norm_num) hlog⟩\ntheorem rational_log_factors_lower_bounds (w : ℕ) (hw : 2 ≤ w) :\n    (15 / 14 : ℝ) ≤ Real.logb (1.9 : ℝ) (w : ℝ) ∧\n      (1 / 10 : ℝ) ≤ Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ)) := by\n  have hb : (1 : ℝ) < 1.9 := by norm_num\n  have hpow₁ : (1.9 : ℝ) ^ 15 ≤ (2 : ℝ) ^ 14 := by norm_num\n  have h₁ := Real.logb_le_logb_of_le hb\n    (pow_pos (by norm_num : (0 : ℝ) < 1.9) 15) hpow₁\n  rw [Real.logb_pow, Real.logb_pow, Real.logb_self_eq_one hb] at h₁\n  have hwR : (2 : ℝ) ≤ (w : ℝ) := by exact_mod_cast hw\n  have hmono₁ := Real.logb_le_logb_of_le hb (by norm_num : (0 : ℝ) < 2) hwR\n  have hfirst : (15 / 14 : ℝ) ≤ Real.logb (1.9 : ℝ) (w : ℝ) := by\n    norm_num at h₁\n    linarith\n  refine ⟨hfirst, ?_⟩\n  have hpow₂ : (1.9 : ℝ) ≤ (15 / 14 : ℝ) ^ 10 := by norm_num\n  have h₂ := Real.logb_le_logb_of_le hb (by norm_num : (0 : ℝ) < 1.9) hpow₂\n  rw [Real.logb_self_eq_one hb, Real.logb_pow] at h₂\n  have hmono₂ := Real.logb_le_logb_of_le hb\n    (by norm_num : (0 : ℝ) < 15 / 14) hfirst\n  norm_num at h₂\n  linarith\ntheorem log_product_lower_bound (w : ℕ) (hw : 2 ≤ w) :\n    (3 / 28 : ℝ) ≤ Real.logb (1.9 : ℝ) (w : ℝ) *\n      Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ)) := by\n  obtain ⟨hfirst, hsecond⟩ := rational_log_factors_lower_bounds w hw\n  calc\n    (3 / 28 : ℝ) = (15 / 14 : ℝ) * (1 / 10 : ℝ) := by norm_num\n    _ ≤ Real.logb (1.9 : ℝ) (w : ℝ) *\n        Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ)) :=\n      mul_le_mul hfirst hsecond (by norm_num) (le_trans (by norm_num) hfirst)\ntheorem minimal_fragment_decode {X ι : Type*} [Finite X]\n    (f : ι → Set X) (i j j₀ : ι) (W : Set X) (t : ℕ)\n    (hj : f j ⊆ f i ∪ W) (ht : (f j \\ W).ncard = t)\n    (hmin : ∀ a, f a ⊆ f i ∪ W → t ≤ (f a \\ W).ncard)\n    (h₀ : f j₀ ⊆ W ∪ (f j \\ W)) : f j₀ \\ W = f j \\ W := by\n  have hsub : f j₀ \\ W ⊆ f j \\ W := by\n    intro x hx\n    rcases h₀ hx.1 with hxW | hxT\n    · exact False.elim (hx.2 hxW)\n    · exact hxT\n  apply Set.eq_of_subset_of_ncard_le hsub\n  rw [ht]\n  apply hmin j₀\n  intro x hx\n  rcases h₀ hx with hxW | hxT\n  · exact Or.inr hxW\n  · exact hj hxT.1\ntheorem ncard_mul_le_of_fiber_bounds {α β : Type*} [Fintype α] [Fintype β]\n    (s : Set α) (t : Set β) (f : α → β) (a b : ℝ)\n    (hf : ∀ x ∈ s, f x ∈ t)\n    (hb : ∀ y ∈ t, ({x | x ∈ s ∧ f x = y}.ncard : ℝ) * a ≤ b) :\n    (s.ncard : ℝ) * a ≤ (t.ncard : ℝ) * b := by\n  classical\n  have hc := Finset.card_eq_sum_card_fiberwise\n    (s := s.toFinset) (t := t.toFinset) (f := f)\n    (by\n      intro x hx\n      simpa using hf x (by simpa using hx))\n  have he (y : β) :\n      {x | x ∈ s ∧ f x = y}.toFinset = {x ∈ s.toFinset | f x = y} := by\n    ext x\n    simp\n  have hc' : (s.ncard : ℝ) =\n      ∑ y ∈ t.toFinset, ({x | x ∈ s ∧ f x = y}.ncard : ℝ) := by\n    simp_rw [Set.ncard_eq_toFinset_card', he]\n    exact_mod_cast hc\n  calc\n    (s.ncard : ℝ) * a =\n        ∑ y ∈ t.toFinset, ({x | x ∈ s ∧ f x = y}.ncard : ℝ) * a := by\n      rw [← Finset.sum_mul, ← hc']\n    _ ≤ ∑ _y ∈ t.toFinset, b := Finset.sum_le_sum fun y hy ↦ hb y (by simpa using hy)\n    _ = (t.ncard : ℝ) * b := by simp [Set.ncard_eq_toFinset_card']\ntheorem maximal_weighted_link (n w : ℕ) (ℱ : Set (Set (Fin n))) (κ : ℝ)\n    (hκ : 2 ≤ κ) (hsys : Set.IsSystem w ℱ) (hsize : κ ^ w < (ℱ.ncard : ℝ)) :\n    ∃ T : Set (Fin n),\n      2 ≤ {A : Set (Fin n) | A ∈ ℱ ∧ T ⊆ A}.ncard ∧\n      ∀ U : Set (Fin n),\n        ({A : Set (Fin n) | A ∈ ℱ ∧ U ⊆ A}.ncard : ℝ) * κ ^ U.ncard ≤\n          ({A : Set (Fin n) | A ∈ ℱ ∧ T ⊆ A}.ncard : ℝ) * κ ^ T.ncard := by\n  classical\n  letI := Fintype.ofFinite (Set (Fin n))\n  let L (T : Set (Fin n)) : Set (Set (Fin n)) := {A | A ∈ ℱ ∧ T ⊆ A}\n  let score (T : Set (Fin n)) : ℝ := (L T).ncard * κ ^ T.ncard\n  obtain ⟨T, _, hmax⟩ := Finset.exists_max_image Finset.univ score Finset.univ_nonempty\n  have hmax' (U : Set (Fin n)) : score U ≤ score T := hmax U (Finset.mem_univ U)\n  have hbot : score ∅ = (ℱ.ncard : ℝ) := by simp [score, L]\n  have hlarge : κ ^ w < score T := lt_of_lt_of_le hsize (hbot ▸ hmax' ∅)\n  have hκpos : 0 < κ := by linarith\n  have hscorepos : 0 < score T := lt_trans (pow_pos hκpos w) hlarge\n  have hLpos : 0 < (L T).ncard := by\n    by_contra h\n    have hzero : (L T).ncard = 0 := Nat.eq_zero_of_not_pos h\n    simp [score, hzero] at hscorepos\n  obtain ⟨A, hA⟩ := (Set.ncard_pos (Set.toFinite (L T))).mp hLpos\n  have hTcard : T.ncard ≤ w := le_trans (Set.ncard_le_ncard hA.2) (hsys A hA.1)\n  have htwo : 2 ≤ (L T).ncard := by\n    by_contra h\n    have hle : ((L T).ncard : ℝ) ≤ 1 := by exact_mod_cast (by omega : (L T).ncard ≤ 1)\n    have hscorele : score T ≤ κ ^ T.ncard := by\n      simpa [score] using mul_le_mul_of_nonneg_right hle (le_of_lt (pow_pos hκpos T.ncard))\n    have hpowle : κ ^ T.ncard ≤ κ ^ w := pow_le_pow_right₀ (by linarith) hTcard\n    exact (not_lt_of_ge (hscorele.trans hpowle)) hlarge\n  exact ⟨T, htwo, hmax'⟩\ntheorem extract_spread_petals (n w : ℕ) (ℱ : Set (Set (Fin n))) (κ : ℝ)\n    (hκ : 2 ≤ κ) (hsys : Set.IsSystem w ℱ) (hsize : κ ^ w < (ℱ.ncard : ℝ)) :\n    ∃ (T : Set (Fin n)) (ℋ : Set (Set (Fin n))),\n      ℋ.Nonempty ∧ (∅ : Set (Fin n)) ∉ ℋ ∧ Set.IsSystem w ℋ ∧\n      (∀ A ∈ ℋ, Disjoint T A ∧ T ∪ A ∈ ℱ) ∧\n      (∀ U : Set (Fin n),\n        ({A : Set (Fin n) | A ∈ ℋ ∧ U ⊆ A}.ncard : ℝ) * (κ / 2) ^ U.ncard ≤\n          (ℋ.ncard : ℝ)) := by\n  classical\n  obtain ⟨T, htwo, hmax⟩ := maximal_weighted_link n w ℱ κ hκ hsys hsize\n  let L (U : Set (Fin n)) : Set (Set (Fin n)) := {A | A ∈ ℱ ∧ U ⊆ A}\n  let G : Set (Set (Fin n)) := (fun A : Set (Fin n) ↦ A \\ T) '' L T\n  let ℋ : Set (Set (Fin n)) := G \\ {∅}\n  have hκpos : 0 < κ := by linarith\n  have hrec (A : Set (Fin n)) (hA : A ∈ L T) : T ∪ (A \\ T) = A := by\n    rw [Set.union_comm]\n    exact Set.sdiff_union_of_subset hA.2\n  have hinj : Set.InjOn (fun A : Set (Fin n) ↦ A \\ T) (L T) := by\n    intro A hA B hB hAB\n    calc\n      A = T ∪ (A \\ T) := (hrec A hA).symm\n      _ = T ∪ (B \\ T) := congrArg (fun U ↦ T ∪ U) hAB\n      _ = B := hrec B hB\n  have hGcard : G.ncard = (L T).ncard := hinj.ncard_image\n  have hHcard : (L T).ncard ≤ ℋ.ncard + 1 := by\n    rw [← hGcard]\n    have hsub : G ⊆ insert (∅ : Set (Fin n)) ℋ := by\n      intro A hA\n      by_cases he : A = ∅\n      · exact Or.inl he\n      · exact Or.inr ⟨hA, by simpa using he⟩\n    exact (Set.ncard_le_ncard hsub).trans (Set.ncard_insert_le _ _)\n  have hHpos : 0 < ℋ.ncard := by change 2 ≤ (L T).ncard at htwo; omega\n  have hhalf : ((L T).ncard : ℝ) ≤ 2 * (ℋ.ncard : ℝ) := by\n    have hnat : (L T).ncard ≤ 2 * ℋ.ncard := by omega\n    exact_mod_cast hnat\n  have hproperties (A : Set (Fin n)) (hA : A ∈ ℋ) :\n      Disjoint T A ∧ T ∪ A ∈ ℱ := by\n    obtain ⟨B, hB, rfl⟩ := hA.1\n    exact ⟨Set.disjoint_sdiff_right, (hrec B hB).symm ▸ hB.1⟩\n  have hsysH : Set.IsSystem w ℋ := by\n    intro A hA\n    obtain ⟨B, hB, rfl⟩ := hA.1\n    exact (Set.ncard_le_ncard Set.sdiff_subset).trans (hsys B hB.1)\n  refine ⟨T, ℋ, (Set.ncard_pos (Set.toFinite ℋ)).mp hHpos, ?_, hsysH,\n    hproperties, ?_⟩\n  · simp [ℋ]\n  · intro U\n    by_cases hU : U = ∅\n    · simp [hU]\n    by_cases hdis : Disjoint T U\n    · let K : Set (Set (Fin n)) := {A | A ∈ ℋ ∧ U ⊆ A}\n      have hrecovery (A : Set (Fin n)) (hA : A ∈ ℋ) : (T ∪ A) \\ T = A := by\n        ext x\n        constructor\n        · intro hx\n          exact hx.1.resolve_left hx.2\n        · intro hx\n          exact ⟨Or.inr hx, fun hxT ↦ Set.disjoint_left.mp (hproperties A hA).1 hxT hx⟩\n      have hrootinj : Set.InjOn (fun A : Set (Fin n) ↦ T ∪ A) K := by\n        intro A hA B hB hAB\n        calc\n          A = (T ∪ A) \\ T := (hrecovery A hA.1).symm\n          _ = (T ∪ B) \\ T := congrArg (fun D ↦ D \\ T) hAB\n          _ = B := hrecovery B hB.1\n      have hrootmap : (fun A : Set (Fin n) ↦ T ∪ A) '' K ⊆ L (T ∪ U) := by\n        rintro _ ⟨A, hA, rfl⟩\n        refine ⟨(hproperties A hA.1).2, ?_⟩\n        intro x hx\n        exact hx.elim Or.inl (fun hxU ↦ Or.inr (hA.2 hxU))\n      have hKcard : K.ncard ≤ (L (T ∪ U)).ncard := by\n        rw [← hrootinj.ncard_image]\n        exact Set.ncard_le_ncard hrootmap\n      have hfull : ((L (T ∪ U)).ncard : ℝ) * κ ^ U.ncard ≤ ((L T).ncard : ℝ) := by\n        apply (mul_le_mul_iff_left₀ (pow_pos hκpos T.ncard)).mp\n        calc\n          ((L (T ∪ U)).ncard : ℝ) * κ ^ U.ncard * κ ^ T.ncard =\n              ((L (T ∪ U)).ncard : ℝ) * κ ^ (T ∪ U).ncard := by\n            rw [Set.ncard_union_eq hdis, pow_add]\n            ring\n          _ ≤ ((L T).ncard : ℝ) * κ ^ T.ncard := hmax (T ∪ U)\n      have hcount : (K.ncard : ℝ) * κ ^ U.ncard ≤ ((L T).ncard : ℝ) := by\n        exact (mul_le_mul_of_nonneg_right (by exact_mod_cast hKcard)\n          (le_of_lt (pow_pos hκpos U.ncard))).trans hfull\n      have hUpos : 1 ≤ U.ncard := by\n        exact (Set.ncard_pos (Set.toFinite U)).mpr (Set.nonempty_iff_ne_empty.mpr hU)\n      have hpowtwo : (2 : ℝ) ≤ (2 : ℝ) ^ U.ncard := by\n        simpa using (pow_le_pow_right₀ (by norm_num : (1 : ℝ) ≤ 2) hUpos)\n      have hpow : 2 * (κ / 2) ^ U.ncard ≤ κ ^ U.ncard := by\n        calc\n          2 * (κ / 2) ^ U.ncard ≤ (2 : ℝ) ^ U.ncard * (κ / 2) ^ U.ncard :=\n            mul_le_mul_of_nonneg_right hpowtwo (pow_nonneg (by linarith) _)\n          _ = (2 * (κ / 2)) ^ U.ncard := (mul_pow _ _ _).symm\n          _ = κ ^ U.ncard := by congr 1; ring\n      have hscaled := mul_le_mul_of_nonneg_left hpow (Nat.cast_nonneg K.ncard : (0 : ℝ) ≤ K.ncard)\n      change (K.ncard : ℝ) * (κ / 2) ^ U.ncard ≤ (ℋ.ncard : ℝ)\n      nlinarith\n    · have hzero : {A : Set (Fin n) | A ∈ ℋ ∧ U ⊆ A} = ∅ := by\n        apply Set.eq_empty_iff_forall_notMem.mpr\n        intro A hA\n        apply hdis\n        exact Set.disjoint_left.mpr fun x hxT hxU ↦\n          Set.disjoint_left.mp (hproperties A hA.1).1 hxT (hA.2 hxU)\n      rw [hzero]\n      simp\ntheorem codegree_bound_of_injective_shrinking\n    {X ι ι' : Type*} [Finite X] [Finite ι] [Finite ι']\n    (f : ι → Set X) (g : ι' → Set X) (e : ι' → ι)\n    (he : Function.Injective e) (hgf : ∀ i, g i ⊆ f (e i))\n    (κ N : ℝ) (hκ : 0 ≤ κ)\n    (hbound : ∀ U : Set X,\n      ({i : ι | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) :\n    ∀ U : Set X, ({i : ι' | U ⊆ g i}.ncard : ℝ) * κ ^ U.ncard ≤ N := by\n  intro U\n  have hc : {i : ι' | U ⊆ g i}.ncard ≤ {i : ι | U ⊆ f i}.ncard :=\n    Set.ncard_le_ncard_of_injOn e\n      (fun i hi ↦ Set.Subset.trans hi (hgf i))\n      (fun i _ j _ hij ↦ he hij)\n  exact (mul_le_mul_of_nonneg_right (by exact_mod_cast hc)\n    (pow_nonneg hκ _)).trans (hbound U)\ntheorem fragment_shrinks_current_edge {X ι : Type*}\n    (f : ι → Set X) (i j : ι) (W : Set X)\n    (hj : f j ⊆ f i ∪ W) : f j \\ W ⊆ f i := by\n  intro x hx\n  rcases hj hx.1 with hxi | hxW\n  · exact hxi\n  · exact False.elim (hx.2 hxW)\ntheorem fragment_preserves_existential_provenance {X ι : Type*}\n    (ℱ : Set (Set X)) (f : ι → Set X) (Wold W : Set X) (j : ι)\n    (hprov : ∀ i, ∃ A ∈ ℱ, A ⊆ f i ∪ Wold) :\n    ∃ A ∈ ℱ, A ⊆ (f j \\ W) ∪ (Wold ∪ W) := by\n  obtain ⟨A, hA, hsub⟩ := hprov j\n  refine ⟨A, hA, ?_⟩\n  intro x hx\n  rcases hsub hx with hxj | hxold\n  · by_cases hxW : x ∈ W\n    · exact Or.inr (Or.inr hxW)\n    · exact Or.inl ⟨hxj, hxW⟩\n  · exact Or.inr (Or.inl hxold)\ntheorem fragment_code_fiber_bound {X ι : Type*} [Finite X] [Fintype ι]\n    (f : ι → Set X) (s : Set (ι × Set X)) (T : ι × Set X → Set X)\n    (Z E : Set X) (k t : ℕ) (κ N : ℝ)\n    (hκ : 0 ≤ κ) (hN : 0 ≤ N) (hE : E.ncard ≤ k)\n    (hcode : ∀ U : Set X, ({i : ι | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N)\n    (hZ : ∀ p ∈ s, p.2 ∪ T p = Z)\n    (hdis : ∀ p ∈ s, Disjoint p.2 (T p))\n    (hTE : ∀ p ∈ s, T p ⊆ E)\n    (ht : ∀ p ∈ s, (T p).ncard = t)\n    (hf : ∀ p ∈ s, T p ⊆ f p.1) :\n    (s.ncard : ℝ) * κ ^ t ≤ (k.choose t : ℝ) * N := by\n  classical\n  letI := Fintype.ofFinite (Set X)\n  have hrecover (A : Set X) (p : ι × Set X) (hp : p ∈ s) (hA : T p = A) :\n      p.2 = Z \\ A := by\n    ext x\n    constructor\n    · intro hx\n      refine ⟨?_, ?_⟩\n      · rw [← hZ p hp]\n        exact Or.inl hx\n      · intro hxA\n        exact Set.disjoint_left.mp (hdis p hp) hx (by simpa only [hA] using hxA)\n    · rintro ⟨hxZ, hxA⟩\n      rw [← hZ p hp] at hxZ\n      rcases hxZ with hxW | hxT\n      · exact hxW\n      · exact False.elim (hxA (by simpa only [hA] using hxT))\n  have hbound (A : Set X) (hA : A ⊆ E ∧ A.ncard = t) :\n      ({p | p ∈ s ∧ T p = A}.ncard : ℝ) * κ ^ t ≤ N := by\n    have hc : {p | p ∈ s ∧ T p = A}.ncard ≤ {i : ι | A ⊆ f i}.ncard := by\n      apply Set.ncard_le_ncard_of_injOn Prod.fst\n      · intro p hp\n        change A ⊆ f p.1\n        simpa only [← hp.2] using hf p hp.1\n      · intro p hp q hq hpq\n        apply Prod.ext hpq\n        exact (hrecover A p hp.1 hp.2).trans (hrecover A q hq.1 hq.2).symm\n    rw [← hA.2]\n    exact (mul_le_mul_of_nonneg_right (by exact_mod_cast hc)\n      (pow_nonneg hκ _)).trans (hcode A)\n  have hsum := ncard_mul_le_of_fiber_bounds s {A : Set X | A ⊆ E ∧ A.ncard = t}\n    T (κ ^ t) N (fun p hp ↦ ⟨hTE p hp, ht p hp⟩) hbound\n  rw [Set.ncard_powerset_ncard (Set.toFinite E) t] at hsum\n  exact hsum.trans (mul_le_mul_of_nonneg_right\n    (by exact_mod_cast Nat.choose_le_choose t hE) hN)\ntheorem minimal_fragment_count (n d k m t : ℕ) (V : Set (Fin n))\n    (f : Fin d → Set (Fin n)) (κ N : ℝ) (hκ : 0 < κ) (hN : 0 ≤ N)\n    (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ k)\n    (hcode : ∀ U : Set (Fin n),\n      ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) :\n    ({p : Fin d × Set (Fin n) |\n        p.2 ⊆ V ∧ p.2.ncard = m ∧\n        (∀ j : Fin d, f j ⊆ f p.1 ∪ p.2 → t ≤ (f j \\ p.2).ncard) ∧\n        (∃ j : Fin d, f j ⊆ f p.1 ∪ p.2 ∧ (f j \\ p.2).ncard = t)}.ncard : ℝ) *\n        κ ^ t ≤ (V.ncard.choose (m + t) : ℝ) * (k.choose t : ℝ) * N := by\n  classical\n  letI := Fintype.ofFinite (Set (Fin n))\n  let S : Set (Fin d × Set (Fin n)) := {p |\n    p.2 ⊆ V ∧ p.2.ncard = m ∧\n    (∀ a : Fin d, f a ⊆ f p.1 ∪ p.2 → t ≤ (f a \\ p.2).ncard) ∧\n    (∃ a : Fin d, f a ⊆ f p.1 ∪ p.2 ∧ (f a \\ p.2).ncard = t)}\n  let j (p : Fin d × Set (Fin n)) : Fin d :=\n    if h : ∃ a : Fin d, f a ⊆ f p.1 ∪ p.2 ∧ (f a \\ p.2).ncard = t\n    then Classical.choose h else p.1\n  have hj (p : Fin d × Set (Fin n)) (hp : p ∈ S) :\n      f (j p) ⊆ f p.1 ∪ p.2 ∧ (f (j p) \\ p.2).ncard = t := by\n    dsimp [j]\n    split_ifs with h\n    · exact Classical.choose_spec h\n    · exact False.elim (h hp.2.2.2)\n  let T (p : Fin d × Set (Fin n)) : Set (Fin n) := f (j p) \\ p.2\n  let Z (p : Fin d × Set (Fin n)) : Set (Fin n) := p.2 ∪ T p\n  have hTcard (p : Fin d × Set (Fin n)) (hp : p ∈ S) : (T p).ncard = t :=\n    (hj p hp).2\n  have hTsub (p : Fin d × Set (Fin n)) (hp : p ∈ S) : T p ⊆ f p.1 :=\n    fragment_shrinks_current_edge f p.1 (j p) p.2 (hj p hp).1\n  have hTdis (p : Fin d × Set (Fin n)) : Disjoint p.2 (T p) :=\n    Set.disjoint_sdiff_right\n  have hmaps (p : Fin d × Set (Fin n)) (hp : p ∈ S) :\n      Z p ⊆ V ∧ (Z p).ncard = m + t := by\n    refine ⟨Set.union_subset hp.1 (Set.sdiff_subset.trans (hsys (j p)).1), ?_⟩\n    change (p.2 ∪ T p).ncard = m + t\n    rw [Set.ncard_union_eq (hTdis p), hp.2.1, hTcard p hp]\n  have hedge (p : Fin d × Set (Fin n)) : f (j p) ⊆ Z p := by\n    intro x hx\n    by_cases hxW : x ∈ p.2\n    · exact Or.inl hxW\n    · exact Or.inr ⟨hx, hxW⟩\n  have hbound (Z₀ : Set (Fin n)) (_hZ₀ : Z₀ ⊆ V ∧ Z₀.ncard = m + t) :\n      ({p | p ∈ S ∧ Z p = Z₀}.ncard : ℝ) * κ ^ t ≤ (k.choose t : ℝ) * N := by\n    let sZ : Set (Fin d × Set (Fin n)) := {p | p ∈ S ∧ Z p = Z₀}\n    change (sZ.ncard : ℝ) * κ ^ t ≤ (k.choose t : ℝ) * N\n    by_cases hne : sZ.Nonempty\n    · obtain ⟨p₀, hp₀⟩ := hne\n      have hcanonical : f (j p₀) ⊆ Z₀ := by\n        rw [← hp₀.2]\n        exact hedge p₀\n      apply fragment_code_fiber_bound f sZ T Z₀ (f (j p₀)) k t κ N\n        (le_of_lt hκ) hN (hsys (j p₀)).2 hcode\n      · intro p hp\n        exact hp.2\n      · intro p _hp\n        exact hTdis p\n      · intro p hp\n        have hdecode : f (j p₀) \\ p.2 = T p := by\n          apply minimal_fragment_decode f p.1 (j p) (j p₀) p.2 t\n            (hj p hp.1).1 (hj p hp.1).2 hp.1.2.2.1\n          change f (j p₀) ⊆ Z p\n          rw [hp.2]\n          exact hcanonical\n        rw [← hdecode]\n        exact Set.sdiff_subset\n      · intro p hp\n        exact hTcard p hp.1\n      · intro p hp\n        exact hTsub p hp.1\n    · have hzero : sZ = ∅ := Set.not_nonempty_iff_eq_empty.mp hne\n      simpa only [hzero, Set.ncard_empty, Nat.cast_zero, zero_mul] using\n        mul_nonneg (Nat.cast_nonneg (k.choose t) : (0 : ℝ) ≤ k.choose t) hN\n  have hsum := ncard_mul_le_of_fiber_bounds S\n    {Z₀ : Set (Fin n) | Z₀ ⊆ V ∧ Z₀.ncard = m + t} Z\n    (κ ^ t) ((k.choose t : ℝ) * N) hmaps hbound\n  rw [Set.ncard_powerset_ncard (Set.toFinite V) (m + t)] at hsum\n  simpa only [mul_assoc] using hsum\ntheorem sunflower_of_disjoint_petals\n    (n r : ℕ) (ℱ : Set (Set (Fin n))) (T : Set (Fin n)) (P : Set (Set (Fin n)))\n    (_hr : 2 ≤ r) (hcard : P.ncard = r) (hdis : P.Pairwise Disjoint)\n    (hprop : ∀ A ∈ P, Disjoint T A ∧ T ∪ A ∈ ℱ) :\n    ∃ S ⊆ ℱ, Set.IsSunflower r S := by\n  have hrecovery (A : Set (Fin n)) (hA : A ∈ P) : (T ∪ A) \\ T = A := by\n    ext x\n    constructor\n    · intro hx\n      exact hx.1.resolve_left hx.2\n    · intro hx\n      exact ⟨Or.inr hx, fun hxT ↦ Set.disjoint_left.mp (hprop A hA).1 hxT hx⟩\n  have hinj : Set.InjOn (fun A : Set (Fin n) ↦ T ∪ A) P := by\n    intro A hA B hB hAB\n    calc\n      A = (T ∪ A) \\ T := (hrecovery A hA).symm\n      _ = (T ∪ B) \\ T := congrArg (fun D ↦ D \\ T) hAB\n      _ = B := hrecovery B hB\n  refine ⟨(fun A : Set (Fin n) ↦ T ∪ A) '' P, ?_, ?_⟩\n  · rintro _ ⟨A, hA, rfl⟩\n    exact (hprop A hA).2\n  · refine ⟨?_, ?_⟩\n    · rw [hinj.ncard_image]\n      exact hcard\n    · rintro _ ⟨A, hA, rfl⟩ _ ⟨B, hB, rfl⟩ hAB\n      have hne : A ≠ B := fun h ↦ hAB (congrArg (fun D ↦ T ∪ D) h)\n      have hd : Disjoint A B := hdis hA hB hne\n      ext x\n      constructor\n      · intro hx\n        have hxT : x ∈ T := by\n          by_contra hxT\n          exact Set.disjoint_left.mp hd (hx.1.resolve_left hxT) (hx.2.resolve_left hxT)\n        apply Set.mem_sInter.mpr\n        rintro _ ⟨D, _hD, rfl⟩\n        exact Or.inl hxT\n      · intro hx\n        exact ⟨Set.mem_sInter.mp hx _ ⟨A, hA, rfl⟩,\n          Set.mem_sInter.mp hx _ ⟨B, hB, rfl⟩⟩\ntheorem scalar_threshold_comparison (r w : ℕ) (hr : 3 ≤ r) (hw : 2 ≤ w) :\n    2 ≤ 520 * (r : ℝ) ^ 3 * ((Nat.log 2 w + 1 : ℕ) : ℝ) ∧\n      520 * (r : ℝ) ^ 3 * ((Nat.log 2 w + 1 : ℕ) : ℝ) <\n        40000 * (r : ℝ) ^ 3 * Real.logb (1.9 : ℝ) (w : ℝ) *\n          Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ)) ∧\n      w < 2 ^ (Nat.log 2 w + 1) := by\n  have hb : (1 : ℝ) < 1.9 := by norm_num\n  have hrR : (3 : ℝ) ≤ (r : ℝ) := by exact_mod_cast hr\n  have hwR : (2 : ℝ) ≤ (w : ℝ) := by exact_mod_cast hw\n  have hL := one_lt_logb_of_two_le w hw\n  have hLL := (rational_log_factors_lower_bounds w hw).2\n  have hcompare : Real.logb (2 : ℝ) (w : ℝ) ≤ Real.logb (1.9 : ℝ) (w : ℝ) := by\n    change Real.log (w : ℝ) / Real.log 2 ≤ Real.log (w : ℝ) / Real.log 1.9\n    exact div_le_div_of_nonneg_left (Real.log_nonneg (by linarith)) (Real.log_pos hb)\n      (Real.log_le_log (by norm_num) (by norm_num))\n  have hnatlog : (Nat.log 2 w : ℝ) ≤ Real.logb (1.9 : ℝ) (w : ℝ) :=\n    (Real.natLog_le_logb w 2).trans hcompare\n  have hell : ((Nat.log 2 w + 1 : ℕ) : ℝ) ≤ 2 * Real.logb (1.9 : ℝ) (w : ℝ) := by\n    push_cast\n    linarith\n  have hellone : (1 : ℝ) ≤ ((Nat.log 2 w + 1 : ℕ) : ℝ) := by\n    exact_mod_cast (Nat.succ_le_succ (Nat.zero_le (Nat.log 2 w)))\n  have hr3 : (1 : ℝ) ≤ (r : ℝ) ^ 3 := by\n    simpa using pow_le_pow_left₀ (by norm_num : (0 : ℝ) ≤ 1)\n      (by linarith : (1 : ℝ) ≤ (r : ℝ)) 3\n  have hr3pos : (0 : ℝ) < (r : ℝ) ^ 3 := lt_of_lt_of_le zero_lt_one hr3\n  have hLpos : 0 < Real.logb (1.9 : ℝ) (w : ℝ) := lt_trans zero_lt_one hL\n  refine ⟨?_, ?_, ?_⟩\n  · have hmul : (1 : ℝ) ≤ (r : ℝ) ^ 3 * ((Nat.log 2 w + 1 : ℕ) : ℝ) := by\n      simpa using mul_le_mul hr3 hellone (by norm_num : (0 : ℝ) ≤ 1) hr3pos.le\n    calc\n      (2 : ℝ) ≤ 520 * 1 := by norm_num\n      _ ≤ 520 * ((r : ℝ) ^ 3 * ((Nat.log 2 w + 1 : ℕ) : ℝ)) :=\n        mul_le_mul_of_nonneg_left hmul (by norm_num)\n      _ = 520 * (r : ℝ) ^ 3 * ((Nat.log 2 w + 1 : ℕ) : ℝ) := by ring\n  · calc\n      520 * (r : ℝ) ^ 3 * ((Nat.log 2 w + 1 : ℕ) : ℝ) ≤\n          520 * (r : ℝ) ^ 3 * (2 * Real.logb (1.9 : ℝ) (w : ℝ)) :=\n        mul_le_mul_of_nonneg_left hell (mul_nonneg (by norm_num) hr3pos.le)\n      _ = 1040 * ((r : ℝ) ^ 3 * Real.logb (1.9 : ℝ) (w : ℝ)) := by ring\n      _ < 4000 * ((r : ℝ) ^ 3 * Real.logb (1.9 : ℝ) (w : ℝ)) :=\n        mul_lt_mul_of_pos_right (by norm_num) (mul_pos hr3pos hLpos)\n      _ = (40000 * (r : ℝ) ^ 3 * Real.logb (1.9 : ℝ) (w : ℝ)) * (1 / 10) := by ring\n      _ ≤ 40000 * (r : ℝ) ^ 3 * Real.logb (1.9 : ℝ) (w : ℝ) *\n          Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ)) :=\n        mul_le_mul_of_nonneg_left hLL\n          (mul_nonneg (mul_nonneg (by norm_num) hr3pos.le) hLpos.le)\n  · simpa only [Nat.succ_eq_add_one] using Nat.lt_pow_succ_log_self (by norm_num : 1 < 2) w\ntheorem exists_perm_image_eq_of_ncard_eq {α : Type*} [Finite α]\n    (A B : Set α) (h : A.ncard = B.ncard) :\n    ∃ σ : Equiv.Perm α, σ '' A = B := by\n  classical\n  letI := Fintype.ofFinite α\n  obtain ⟨σ, hσ⟩ := Equiv.Perm.exists_map_finset_eq A.toFinset B.toFinset\n    (by simpa only [← Set.ncard_eq_toFinset_card'] using h)\n  refine ⟨σ, ?_⟩\n  have he := congrArg (fun D : Finset α ↦ (D : Set α)) hσ\n  simpa using he\ntheorem permutation_image_fiber_ncard_eq {α : Type*} [Fintype α]\n    (A U : Set α) (h : A.ncard = U.ncard) :\n    {σ : Equiv.Perm α | σ '' A = A}.ncard =\n      {σ : Equiv.Perm α | σ '' A = U}.ncard := by\n  classical\n  obtain ⟨τ, hτ⟩ := exists_perm_image_eq_of_ncard_eq A U h\n  apply Set.ncard_congr (fun σ _ ↦ σ.trans τ)\n  · intro σ hσ\n    change (τ ∘ σ) '' A = U\n    calc\n      (τ ∘ σ) '' A = τ '' (σ '' A) := (Set.image_image τ σ A).symm\n      _ = U := by rw [hσ, hτ]\n  · intro σ π _ _ he\n    apply Equiv.ext\n    intro x\n    exact τ.injective (congrArg (fun e : Equiv.Perm α ↦ e x) he)\n  · intro π hπ\n    refine ⟨π.trans τ.symm, ?_, ?_⟩\n    · change (τ.symm ∘ π) '' A = A\n      calc\n        (τ.symm ∘ π) '' A = τ.symm '' (π '' A) := (Set.image_image τ.symm π A).symm\n        _ = A := by rw [hπ, ← hτ]; simp [Set.image_image]\n    · apply Equiv.ext\n      intro x\n      exact τ.apply_symm_apply (π x)\ntheorem ncard_eq_sum_fiber_ncard {α β : Type*} [Fintype α] [Fintype β]\n    (S : Set α) (T : Finset β) (f : α → β) (hf : ∀ x ∈ S, f x ∈ T) :\n    S.ncard = ∑ y ∈ T, {x | x ∈ S ∧ f x = y}.ncard := by\n  classical\n  have hc := Finset.card_eq_sum_card_fiberwise\n    (s := S.toFinset) (t := T) (f := f)\n    (by intro x hx; simpa using hf x (by simpa using hx))\n  have he (y : β) :\n      {x | x ∈ S ∧ f x = y}.toFinset = {x ∈ S.toFinset | f x = y} := by\n    ext x\n    simp\n  simpa only [Set.ncard_eq_toFinset_card', he] using hc\ntheorem permutation_image_family_ncard_mul {α : Type*} [Fintype α]\n    (A : Set α) (H : Set (Set α)) (hH : ∀ U ∈ H, U.ncard = A.ncard) :\n    {σ : Equiv.Perm α | σ '' A ∈ H}.ncard * {U : Set α | U.ncard = A.ncard}.ncard =\n      H.ncard * (Set.univ : Set (Equiv.Perm α)).ncard := by\n  classical\n  let K := {σ : Equiv.Perm α | σ '' A = A}.ncard\n  have hc (G : Set (Set α)) (hG : ∀ U ∈ G, U.ncard = A.ncard) :\n      {σ : Equiv.Perm α | σ '' A ∈ G}.ncard = G.ncard * K := by\n    rw [ncard_eq_sum_fiber_ncard _ G.toFinset (fun σ : Equiv.Perm α ↦ σ '' A)\n      (by intro σ hσ; simpa using hσ)]\n    calc\n      (∑ U ∈ G.toFinset,\n          {σ : Equiv.Perm α | σ '' A ∈ G ∧ σ '' A = U}.ncard) =\n          ∑ _U ∈ G.toFinset, K := by\n        apply Finset.sum_congr rfl\n        intro U hU\n        have hUG : U ∈ G := by simpa using hU\n        have he : {σ : Equiv.Perm α | σ '' A ∈ G ∧ σ '' A = U} =\n            {σ : Equiv.Perm α | σ '' A = U} := by\n          ext σ\n          exact ⟨And.right, fun h ↦ ⟨h ▸ hUG, h⟩⟩\n        rw [he]\n        exact (permutation_image_fiber_ncard_eq A U (hG U hUG).symm).symm\n      _ = G.ncard * K := by\n        simp only [Finset.sum_const, nsmul_eq_mul, Set.ncard_eq_toFinset_card', Nat.cast_id]\n  let T : Set (Set α) := {U | U.ncard = A.ncard}\n  have htotal : {σ : Equiv.Perm α | σ '' A ∈ T} = Set.univ := by\n    ext σ\n    simp [T, Set.ncard_image_of_injective A σ.injective]\n  have hall := hc T (fun _ h ↦ h)\n  rw [htotal] at hall\n  calc\n    _ = (H.ncard * K) * T.ncard := by rw [hc H hH]\n    _ = H.ncard * (T.ncard * K) := by ac_rfl\n    _ = _ := by rw [← hall]\ntheorem numbered_disjoint_blocks (n r s : ℕ) (hrs : r * s ≤ n) :\n    ∃ A : Fin r → Set (Fin n), (∀ i, (A i).ncard = s) ∧\n      (∀ i j, i ≠ j → Disjoint (A i) (A j)) := by\n  classical\n  obtain ⟨e⟩ := Function.Embedding.nonempty_of_card_le\n    (α := Fin r × Fin s) (β := Fin n) (by simpa using hrs)\n  let A : Fin r → Set (Fin n) := fun i ↦ Set.range (fun j : Fin s ↦ e (i, j))\n  refine ⟨A, ?_, ?_⟩\n  · intro i\n    have hi : Function.Injective (fun j : Fin s ↦ e (i, j)) := by\n      intro j k hjk\n      exact congrArg Prod.snd (e.injective hjk)\n    simpa [A] using Set.ncard_range_of_injective hi\n  · intro i j hij\n    apply Set.disjoint_left.mpr\n    rintro x ⟨a, ha⟩ ⟨b, hb⟩\n    exact hij (congrArg Prod.fst (e.injective (ha.trans hb.symm)))\ntheorem disjoint_blocks_from_dense_family\n    (n r s : ℕ) (𝒢 : Set (Set (Fin n))) (hrs : r * s ≤ n)\n    (h𝒢 : ∀ U ∈ 𝒢, U.ncard = s)\n    (hdense : (r : ℝ) * ((n.choose s : ℝ) - (𝒢.ncard : ℝ)) < (n.choose s : ℝ)) :\n    ∃ B : Fin r → Set (Fin n), (∀ i, B i ∈ 𝒢) ∧\n      (∀ i j, i ≠ j → Disjoint (B i) (B j)) := by\n  classical\n  obtain ⟨A, hA, hAdis⟩ := numbered_disjoint_blocks n r s hrs\n  let T : Set (Set (Fin n)) := {U | U.ncard = s}\n  let H : Set (Set (Fin n)) := T \\ 𝒢\n  have hGT : 𝒢 ⊆ T := fun U hU ↦ h𝒢 U hU\n  have hTcard : T.ncard = n.choose s := by\n    simpa [T] using Set.ncard_powerset_ncard\n      (Set.toFinite (Set.univ : Set (Fin n))) s\n  have hHcard : (H.ncard : ℝ) = (n.choose s : ℝ) - (𝒢.ncard : ℝ) := by\n    have hc := Set.ncard_sdiff_add_ncard_of_subset hGT\n    have hcR : (H.ncard : ℝ) + (𝒢.ncard : ℝ) = (n.choose s : ℝ) := by\n      exact_mod_cast hc.trans hTcard\n    linarith\n  have hgood : ∃ σ : Equiv.Perm (Fin n), ∀ i, σ '' A i ∈ 𝒢 := by\n    by_contra hnone\n    have hbad : ∀ σ : Equiv.Perm (Fin n), ∃ i, σ '' A i ∈ H := by\n      intro σ\n      have hnot : ¬ ∀ i, σ '' A i ∈ 𝒢 := fun h ↦ hnone ⟨σ, h⟩\n      obtain ⟨i, hi⟩ := not_forall.mp hnot\n      refine ⟨i, ?_, hi⟩\n      change (σ '' A i).ncard = s\n      rw [Set.ncard_image_of_injective _ σ.injective, hA i]\n    let S : Set (Equiv.Perm (Fin n) × Fin r) := {p | p.1 '' A p.2 ∈ H}\n    have hP_le : (Set.univ : Set (Equiv.Perm (Fin n))).ncard ≤ S.ncard := by\n      apply Set.ncard_le_ncard_of_injOn (fun σ ↦ (σ, (hbad σ).choose))\n      · intro σ _\n        exact (hbad σ).choose_spec\n      · intro σ π _ _ he\n        exact congrArg Prod.fst he\n    have hfiber (i : Fin r) :\n        {p : Equiv.Perm (Fin n) × Fin r | p ∈ S ∧ p.2 = i}.ncard =\n          {σ : Equiv.Perm (Fin n) | σ '' A i ∈ H}.ncard := by\n      apply Set.ncard_congr (fun p _ ↦ p.1)\n      · intro p hp\n        change p.1 '' A i ∈ H\n        simpa only [S, Set.mem_ofPred_eq, hp.2] using hp.1\n      · intro p q hp hq he\n        exact Prod.ext he (hp.2.trans hq.2.symm)\n      · intro σ hσ\n        exact ⟨(σ, i), ⟨hσ, rfl⟩, rfl⟩\n    have hbound (i : Fin r) :\n        ({p : Equiv.Perm (Fin n) × Fin r | p ∈ S ∧ p.2 = i}.ncard : ℝ) *\n            (n.choose s : ℝ) ≤\n          (H.ncard : ℝ) * ((Set.univ : Set (Equiv.Perm (Fin n))).ncard : ℝ) := by\n      rw [hfiber i]\n      have hc := permutation_image_family_ncard_mul (A i) H\n        (fun U hU ↦ hU.1.trans (hA i).symm)\n      rw [hA i] at hc\n      change _ * T.ncard = _ at hc\n      rw [hTcard] at hc\n      exact le_of_eq (by exact_mod_cast hc)\n    have hsum := ncard_mul_le_of_fiber_bounds S (Set.univ : Set (Fin r))\n      Prod.snd (n.choose s : ℝ)\n      ((H.ncard : ℝ) * ((Set.univ : Set (Equiv.Perm (Fin n))).ncard : ℝ))\n      (fun _ _ ↦ Set.mem_univ _) (fun i _ ↦ hbound i)\n    have hPpos : 0 < ((Set.univ : Set (Equiv.Perm (Fin n))).ncard : ℝ) := by\n      exact_mod_cast ((Set.ncard_pos (Set.toFinite _)).mpr\n        (⟨Equiv.refl (Fin n), Set.mem_univ _⟩ :\n          (Set.univ : Set (Equiv.Perm (Fin n))).Nonempty))\n    have hleft : ((Set.univ : Set (Equiv.Perm (Fin n))).ncard : ℝ) *\n        (n.choose s : ℝ) ≤ (S.ncard : ℝ) * (n.choose s : ℝ) := by\n      exact mul_le_mul_of_nonneg_right (by exact_mod_cast hP_le) (by positivity)\n    have hsum' : ((Set.univ : Set (Equiv.Perm (Fin n))).ncard : ℝ) *\n        (n.choose s : ℝ) ≤ (r : ℝ) * ((n.choose s : ℝ) - (𝒢.ncard : ℝ)) *\n          ((Set.univ : Set (Equiv.Perm (Fin n))).ncard : ℝ) := by\n      simpa only [Set.ncard_univ, Nat.card_fin, hHcard, mul_assoc] using hleft.trans hsum\n    have hd := mul_lt_mul_of_pos_right hdense hPpos\n    nlinarith\n  obtain ⟨σ, hσ⟩ := hgood\n  refine ⟨fun i ↦ σ '' A i, hσ, ?_⟩\n  intro i j hij\n  apply Set.disjoint_left.mpr\n  rintro x ⟨a, ha, hax⟩ ⟨b, hb, hbx⟩\n  have hab : a = b := σ.injective (hax.trans hbx.symm)\n  exact Set.disjoint_left.mp (hAdis i j hij) ha (hab ▸ hb)\ntheorem choose_add_mul_pow_le (v m t : ℕ) :\n    v.choose (m + t) * m ^ t ≤ v.choose m * v ^ t := by\n  induction t with\n  | zero => simp\n  | succ t ih =>\n    have hstep : v.choose (m + t + 1) * m ≤ v.choose (m + t) * v := by\n      calc\n        v.choose (m + t + 1) * m ≤ v.choose (m + t + 1) * (m + t + 1) :=\n          Nat.mul_le_mul_left _ (by omega)\n        _ = v.choose (m + t) * (v - (m + t)) := Nat.choose_succ_right_eq v (m + t)\n        _ ≤ v.choose (m + t) * v := Nat.mul_le_mul_left _ (Nat.sub_le _ _)\n    calc\n      v.choose (m + (t + 1)) * m ^ (t + 1) =\n          (v.choose (m + t + 1) * m) * m ^ t := by ring\n      _ ≤ (v.choose (m + t) * v) * m ^ t := Nat.mul_le_mul_right _ hstep\n      _ = (v.choose (m + t) * m ^ t) * v := by ring\n      _ ≤ (v.choose m * v ^ t) * v := Nat.mul_le_mul_right _ ih\n      _ = v.choose m * v ^ (t + 1) := by rw [pow_succ]; ring\ntheorem binomial_upper_half_tail (w : ℕ) (q : ℝ) (hq : 2 ≤ q) :\n    (∑ t ∈ Finset.Icc (w / 2 + 1) w, (w.choose t : ℝ) * (q⁻¹) ^ (2 * t)) ≤\n      (2 / q) ^ w := by\n  have hqpos : 0 < q := by linarith\n  have hinv : 0 ≤ q⁻¹ := inv_nonneg.mpr hqpos.le\n  have hinvone : q⁻¹ ≤ 1 := (inv_le_one₀ hqpos).mpr (by linarith)\n  have hsum : (∑ t ∈ Finset.Icc (w / 2 + 1) w, (w.choose t : ℝ)) ≤ (2 : ℝ) ^ w := by\n    calc\n      (∑ t ∈ Finset.Icc (w / 2 + 1) w, (w.choose t : ℝ)) ≤\n          ∑ t ∈ Finset.range (w + 1), (w.choose t : ℝ) := by\n        apply Finset.sum_le_sum_of_subset_of_nonneg\n        · intro t ht\n          simp only [Finset.mem_Icc] at ht\n          exact Finset.mem_range.mpr (by omega)\n        · intro t _ _\n          exact Nat.cast_nonneg _\n      _ = (2 : ℝ) ^ w := by exact_mod_cast Nat.sum_range_choose w\n  calc\n    (∑ t ∈ Finset.Icc (w / 2 + 1) w, (w.choose t : ℝ) * (q⁻¹) ^ (2 * t)) ≤\n        ∑ t ∈ Finset.Icc (w / 2 + 1) w, (w.choose t : ℝ) * (q⁻¹) ^ w := by\n      apply Finset.sum_le_sum\n      intro t ht\n      have hwt : w ≤ 2 * t := by\n        simp only [Finset.mem_Icc] at ht\n        omega\n      exact mul_le_mul_of_nonneg_left (pow_le_pow_of_le_one hinv hinvone hwt)\n        (Nat.cast_nonneg _)\n    _ = (∑ t ∈ Finset.Icc (w / 2 + 1) w, (w.choose t : ℝ)) * (q⁻¹) ^ w :=\n      (Finset.sum_mul _ _ _).symm\n    _ ≤ (2 : ℝ) ^ w * (q⁻¹) ^ w := mul_le_mul_of_nonneg_right hsum (pow_nonneg hinv _)\n    _ = (2 / q) ^ w := by rw [← mul_pow, div_eq_mul_inv]\ntheorem exists_minimal_fragment_label (n d : ℕ) (f : Fin d → Set (Fin n))\n    (i : Fin d) (W : Set (Fin n)) :\n    ∃ j : Fin d, f j ⊆ f i ∪ W ∧\n      ∀ a : Fin d, f a ⊆ f i ∪ W → (f j \\ W).ncard ≤ (f a \\ W).ncard := by\n  classical\n  let s : Finset (Fin d) := Finset.univ.filter fun j ↦ f j ⊆ f i ∪ W\n  have hi : i ∈ s := by simp [s, Set.subset_union_left]\n  obtain ⟨j, hj, hmin⟩ := Finset.exists_min_image s (fun j ↦ (f j \\ W).ncard) ⟨i, hi⟩\n  refine ⟨j, (Finset.mem_filter.mp hj).2, ?_⟩\n  intro a ha\n  exact hmin a (Finset.mem_filter.mpr ⟨Finset.mem_univ a, ha⟩)\nnoncomputable def minimalFragmentLabel {n d : ℕ} (f : Fin d → Set (Fin n))\n    (i : Fin d) (W : Set (Fin n)) : Fin d :=\n  Classical.choose (exists_minimal_fragment_label n d f i W)\nnoncomputable def minimalFragment {n d : ℕ} (f : Fin d → Set (Fin n))\n    (i : Fin d) (W : Set (Fin n)) : Set (Fin n) :=\n  f (minimalFragmentLabel f i W) \\ W\ntheorem minimalFragment_spec {n d : ℕ} (f : Fin d → Set (Fin n))\n    (i : Fin d) (W : Set (Fin n)) :\n    f (minimalFragmentLabel f i W) ⊆ f i ∪ W ∧\n      ∀ a : Fin d, f a ⊆ f i ∪ W → (minimalFragment f i W).ncard ≤ (f a \\ W).ncard :=\n  Classical.choose_spec (exists_minimal_fragment_label n d f i W)\ntheorem minimalFragment_subset {n d : ℕ} (f : Fin d → Set (Fin n))\n    (i : Fin d) (W : Set (Fin n)) : minimalFragment f i W ⊆ f i :=\n  fragment_shrinks_current_edge f i (minimalFragmentLabel f i W) W\n    (minimalFragment_spec f i W).1\ntheorem ncard_eq_sum_ncard_fibers {α β : Type*} [Fintype α] [DecidableEq β]\n    (s : Set α) (t : Finset β) (f : α → β) (hf : ∀ x ∈ s, f x ∈ t) :\n    (s.ncard : ℝ) = ∑ y ∈ t, ({x | x ∈ s ∧ f x = y}.ncard : ℝ) := by\n  classical\n  have hc := Finset.card_eq_sum_card_fiberwise\n    (s := s.toFinset) (t := t) (f := f)\n    (by intro x hx; exact hf x (by simpa using hx))\n  have he (y : β) :\n      {x | x ∈ s ∧ f x = y}.toFinset = {x ∈ s.toFinset | f x = y} := by\n    ext x\n    simp\n  simp_rw [Set.ncard_eq_toFinset_card', he]\n  exact_mod_cast hc\ntheorem normalize_fragment_rank_bound (v k m t : ℕ) (c κ N q : ℝ)\n    (hc : 0 ≤ c) (hκ : 0 ≤ κ) (hN : 0 ≤ N) (hq : 2 ≤ q) (hv : 0 < v)\n    (hscale : q ^ 2 * (v : ℝ) ≤ (m : ℝ) * κ)\n    (hcount : c * κ ^ t ≤ (v.choose (m + t) : ℝ) * (k.choose t : ℝ) * N) :\n    c ≤ (v.choose m : ℝ) * (k.choose t : ℝ) * N * (q⁻¹) ^ (2 * t) := by\n  have hqpos : 0 < q := by linarith\n  have hvpos : (0 : ℝ) < v := by exact_mod_cast hv\n  have hbinom : (v.choose (m + t) : ℝ) * (m : ℝ) ^ t ≤\n      (v.choose m : ℝ) * (v : ℝ) ^ t := by exact_mod_cast choose_add_mul_pow_le v m t\n  have hscale_pow := pow_le_pow_left₀\n    (mul_nonneg (sq_nonneg q) (Nat.cast_nonneg v)) hscale t\n  have hmain : (c * q ^ (2 * t)) * (v : ℝ) ^ t ≤\n      ((v.choose m : ℝ) * (k.choose t : ℝ) * N) * (v : ℝ) ^ t := by\n    calc\n      (c * q ^ (2 * t)) * (v : ℝ) ^ t = c * (q ^ 2 * (v : ℝ)) ^ t := by\n        rw [mul_pow, ← pow_mul]\n        ring\n      _ ≤ c * ((m : ℝ) * κ) ^ t := mul_le_mul_of_nonneg_left hscale_pow hc\n      _ = (c * κ ^ t) * (m : ℝ) ^ t := by rw [mul_pow]; ring\n      _ ≤ ((v.choose (m + t) : ℝ) * (k.choose t : ℝ) * N) * (m : ℝ) ^ t :=\n        mul_le_mul_of_nonneg_right hcount (pow_nonneg (Nat.cast_nonneg m) t)\n      _ ≤ ((v.choose m : ℝ) * (k.choose t : ℝ) * N) * (v : ℝ) ^ t := by\n        convert mul_le_mul_of_nonneg_right hbinom\n          (mul_nonneg (Nat.cast_nonneg (k.choose t)) hN) using 1 <;> ring\n  have hcancel := (mul_le_mul_iff_left₀ (pow_pos hvpos t)).mp hmain\n  have hnorm := mul_le_mul_of_nonneg_right hcancel\n    (pow_nonneg (inv_nonneg.mpr hqpos.le) (2 * t))\n  simpa only [inv_pow, mul_assoc, mul_inv_cancel₀ (ne_of_gt (pow_pos hqpos (2 * t))),\n    mul_one] using hnorm\ntheorem minimal_fragment_rank_bound (n d k m t : ℕ) (V : Set (Fin n))\n    (f : Fin d → Set (Fin n)) (κ N q : ℝ) (hκ : 0 < κ) (hN : 0 ≤ N)\n    (hq : 2 ≤ q) (hV : 0 < V.ncard)\n    (hscale : q ^ 2 * (V.ncard : ℝ) ≤ (m : ℝ) * κ)\n    (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ k)\n    (hcode : ∀ U : Set (Fin n),\n      ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) :\n    ({p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧\n      (minimalFragment f p.1 p.2).ncard = t}.ncard : ℝ) ≤\n      (V.ncard.choose m : ℝ) * (k.choose t : ℝ) * N * (q⁻¹) ^ (2 * t) := by\n  have hsub : {p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧\n      (minimalFragment f p.1 p.2).ncard = t} ⊆\n      {p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧\n        (∀ j : Fin d, f j ⊆ f p.1 ∪ p.2 → t ≤ (f j \\ p.2).ncard) ∧\n        (∃ j : Fin d, f j ⊆ f p.1 ∪ p.2 ∧ (f j \\ p.2).ncard = t)} := by\n    intro p hp\n    refine ⟨hp.1, hp.2.1, ?_, ?_⟩\n    · intro a ha\n      rw [← hp.2.2]\n      exact (minimalFragment_spec f p.1 p.2).2 a ha\n    · exact ⟨minimalFragmentLabel f p.1 p.2, (minimalFragment_spec f p.1 p.2).1, hp.2.2⟩\n  apply normalize_fragment_rank_bound V.ncard k m t _ κ N q\n    (Nat.cast_nonneg _) hκ.le hN hq hV hscale\n  exact (mul_le_mul_of_nonneg_right (by exact_mod_cast Set.ncard_le_ncard hsub)\n    (pow_nonneg hκ.le t)).trans (minimal_fragment_count n d k m t V f κ N hκ hN hsys hcode)\ntheorem bad_fragment_pair_count (n d k m : ℕ) (V : Set (Fin n))\n    (f : Fin d → Set (Fin n)) (κ N q : ℝ) (hκ : 0 < κ) (hN : 0 ≤ N)\n    (hq : 2 ≤ q) (hV : 0 < V.ncard)\n    (hscale : q ^ 2 * (V.ncard : ℝ) ≤ (m : ℝ) * κ)\n    (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ k)\n    (hcode : ∀ U : Set (Fin n),\n      ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) :\n    ({p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧\n      k / 2 < (minimalFragment f p.1 p.2).ncard}.ncard : ℝ) ≤\n      (V.ncard.choose m : ℝ) * N * (2 / q) ^ k := by\n  classical\n  letI := Fintype.ofFinite (Set (Fin n))\n  let s : Set (Fin d × Set (Fin n)) := {p | p.2 ⊆ V ∧ p.2.ncard = m ∧\n    k / 2 < (minimalFragment f p.1 p.2).ncard}\n  let rank (p : Fin d × Set (Fin n)) := (minimalFragment f p.1 p.2).ncard\n  have hmap (p : Fin d × Set (Fin n)) (hp : p ∈ s) :\n      rank p ∈ Finset.Icc (k / 2 + 1) k := by\n    have hle := (Set.ncard_le_ncard (minimalFragment_subset f p.1 p.2)).trans (hsys p.1).2\n    exact Finset.mem_Icc.mpr ⟨Nat.succ_le_iff.mpr hp.2.2, hle⟩\n  change (s.ncard : ℝ) ≤ _\n  rw [ncard_eq_sum_ncard_fibers s (Finset.Icc (k / 2 + 1) k) rank hmap]\n  calc\n    (∑ t ∈ Finset.Icc (k / 2 + 1) k, ({p | p ∈ s ∧ rank p = t}.ncard : ℝ)) ≤\n        ∑ t ∈ Finset.Icc (k / 2 + 1) k,\n          (V.ncard.choose m : ℝ) * (k.choose t : ℝ) * N * (q⁻¹) ^ (2 * t) := by\n      apply Finset.sum_le_sum\n      intro t _ht\n      have hsub : {p | p ∈ s ∧ rank p = t} ⊆\n          {p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧\n            (minimalFragment f p.1 p.2).ncard = t} := by\n        intro p hp\n        exact ⟨hp.1.1, hp.1.2.1, hp.2⟩\n      have hc : ({p | p ∈ s ∧ rank p = t}.ncard : ℝ) ≤\n          ({p : Fin d × Set (Fin n) | p.2 ⊆ V ∧ p.2.ncard = m ∧\n            (minimalFragment f p.1 p.2).ncard = t}.ncard : ℝ) := by\n        exact_mod_cast Set.ncard_le_ncard hsub\n      exact hc.trans\n        (minimal_fragment_rank_bound n d k m t V f κ N q hκ hN hq hV hscale hsys hcode)\n    _ = (V.ncard.choose m : ℝ) * N *\n        (∑ t ∈ Finset.Icc (k / 2 + 1) k, (k.choose t : ℝ) * (q⁻¹) ^ (2 * t)) := by\n      rw [Finset.mul_sum]\n      apply Finset.sum_congr rfl\n      intro t _\n      ring\n    _ ≤ (V.ncard.choose m : ℝ) * N * (2 / q) ^ k :=\n      mul_le_mul_of_nonneg_left (binomial_upper_half_tail k q hq)\n        (mul_nonneg (Nat.cast_nonneg _) hN)\ntheorem retained_fragment_family (n d k : ℕ) (V W : Set (Fin n))\n    (f : Fin d → Set (Fin n)) (κ N : ℝ) (hκ : 0 ≤ κ)\n    (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ k)\n    (hcode : ∀ U : Set (Fin n),\n      ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) :\n    ∃ (d' : ℕ) (g : Fin d' → Set (Fin n)) (e : Fin d' → Fin d),\n      Function.Injective e ∧\n      d' = {i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}.ncard ∧\n      (∀ a, g a ⊆ f (e a)) ∧\n      (∀ a, g a ⊆ V \\ W ∧ (g a).ncard ≤ k / 2) ∧\n      (∀ U : Set (Fin n),\n        ({a : Fin d' | U ⊆ g a}.ncard : ℝ) * κ ^ U.ncard ≤ N) ∧\n      (∀ a, ∃ i : Fin d, f i ⊆ g a ∪ W) := by\n  classical\n  let L : Set (Fin d) := {i | (minimalFragment f i W).ncard ≤ k / 2}\n  let b : Fin (Fintype.card L) ≃ L := (Fintype.equivFin L).symm\n  let e (a : Fin (Fintype.card L)) : Fin d := (b a).val\n  let g (a : Fin (Fintype.card L)) : Set (Fin n) := minimalFragment f (e a) W\n  have he : Function.Injective e := fun a a' h ↦ b.injective (Subtype.ext h)\n  have hshrink (a : Fin (Fintype.card L)) : g a ⊆ f (e a) :=\n    minimalFragment_subset f (e a) W\n  refine ⟨Fintype.card L, g, e, he, ?_, hshrink, ?_, ?_, ?_⟩\n  · simpa only [Nat.card_coe_set_eq] using\n      (show Fintype.card L = Nat.card L from Nat.card_eq_fintype_card.symm)\n  · intro a\n    refine ⟨?_, (b a).property⟩\n    intro x hx\n    exact ⟨(hsys (e a)).1 (hshrink a hx), hx.2⟩\n  · exact codegree_bound_of_injective_shrinking f g e he hshrink κ N hκ hcode\n  · intro a\n    refine ⟨minimalFragmentLabel f (e a) W, ?_⟩\n    intro x hx\n    by_cases hxW : x ∈ W\n    · exact Or.inr hxW\n    · exact Or.inl ⟨hx, hxW⟩\ntheorem dyadic_loss_step (w : ℕ) (hw : 0 < w) (a : ℝ) (ha : 0 ≤ a) :\n    (∑ j ∈ Finset.Icc 1 (w / 2), a ^ j) + a ^ w ≤\n      ∑ j ∈ Finset.Icc 1 w, a ^ j := by\n  have hnot : w ∉ Finset.Icc 1 (w / 2) := by simp only [Finset.mem_Icc]; omega\n  rw [add_comm, ← Finset.sum_insert hnot]\n  apply Finset.sum_le_sum_of_subset_of_nonneg\n  · intro j hj\n    rcases Finset.mem_insert.mp hj with rfl | hj\n    · exact Finset.mem_Icc.mpr ⟨hw, le_rfl⟩\n    · exact Finset.mem_Icc.mpr\n        ⟨(Finset.mem_Icc.mp hj).1, (Finset.mem_Icc.mp hj).2.trans (Nat.div_le_self _ _)⟩\n  · intro j _ _\n    exact pow_nonneg ha j\ntheorem ncard_pair_snd_fiber {α β : Type*} [Finite α] [Finite β]\n    (P : α → β → Prop) (b : β) :\n    {p : α × β | P p.1 p.2 ∧ p.2 = b}.ncard = {a : α | P a b}.ncard := by\n  classical\n  have he : {p : α × β | P p.1 p.2 ∧ p.2 = b} =\n      (fun a : α ↦ (a, b)) '' {a : α | P a b} := by\n    ext p\n    constructor\n    · rintro ⟨hp, hb⟩\n      refine ⟨p.1, ?_, ?_⟩\n      · change P p.1 b\n        simpa only [hb] using hp\n      · exact Prod.ext rfl hb.symm\n    · rintro ⟨a, ha, rfl⟩\n      exact ⟨ha, rfl⟩\n  rw [he, Set.ncard_image_of_injective _ (fun _ _ h ↦ congrArg Prod.fst h)]\ntheorem ncard_pair_fst_fiber {α β : Type*} [Finite α] [Finite β]\n    (P : α → β → Prop) (a : α) :\n    {p : α × β | P p.1 p.2 ∧ p.1 = a}.ncard = {b : β | P a b}.ncard := by\n  classical\n  have he : {p : α × β | P p.1 p.2 ∧ p.1 = a} =\n      (fun b : β ↦ (a, b)) '' {b : β | P a b} := by\n    ext p\n    constructor\n    · rintro ⟨hp, ha⟩\n      refine ⟨p.2, ?_, ?_⟩\n      · change P a p.2\n        simpa only [ha] using hp\n      · exact Prod.ext ha.symm rfl\n    · rintro ⟨b, hb, rfl⟩\n      exact ⟨hb, rfl⟩\n  rw [he, Set.ncard_image_of_injective _ (fun _ _ h ↦ congrArg Prod.snd h)]\ntheorem retained_fragment_average (n d k m : ℕ) (V : Set (Fin n))\n    (f : Fin d → Set (Fin n)) (κ N q : ℝ) (hκ : 0 < κ) (hN : 0 ≤ N)\n    (hq : 2 ≤ q) (hV : 0 < V.ncard)\n    (hscale : q ^ 2 * (V.ncard : ℝ) ≤ (m : ℝ) * κ)\n    (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ k)\n    (hcode : ∀ U : Set (Fin n),\n      ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) :\n    ((d : ℝ) - N * (2 / q) ^ k) * (V.ncard.choose m : ℝ) ≤\n      ∑ W ∈ (Set.toFinite {W : Set (Fin n) | W ⊆ V ∧ W.ncard = m}).toFinset,\n        ({i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}.ncard : ℝ) := by\n  classical\n  letI := Fintype.ofFinite (Set (Fin n))\n  let B : Set (Set (Fin n)) := {W | W ⊆ V ∧ W.ncard = m}\n  let bad : Set (Fin d × Set (Fin n)) := {p | p.2 ∈ B ∧\n    k / 2 < (minimalFragment f p.1 p.2).ncard}\n  have hbad : (bad.ncard : ℝ) ≤ (V.ncard.choose m : ℝ) * N * (2 / q) ^ k := by\n    convert bad_fragment_pair_count n d k m V f κ N q hκ hN hq hV hscale hsys hcode using 1\n    congr 2\n    ext p\n    simp only [bad, B, Set.mem_setOf_eq, and_assoc]\n  have hpartition : (bad.ncard : ℝ) =\n      ∑ W ∈ B.toFinset, ({i : Fin d | k / 2 < (minimalFragment f i W).ncard}.ncard : ℝ) := by\n    rw [ncard_eq_sum_ncard_fibers bad B.toFinset Prod.snd\n      (fun p hp ↦ Set.mem_toFinset.mpr hp.1)]\n    apply Finset.sum_congr rfl\n    intro W hW\n    change ({p : Fin d × Set (Fin n) | (p.2 ∈ B ∧\n      k / 2 < (minimalFragment f p.1 p.2).ncard) ∧ p.2 = W}.ncard : ℝ) = _\n    rw [ncard_pair_snd_fiber (fun i W ↦ W ∈ B ∧\n      k / 2 < (minimalFragment f i W).ncard) W]\n    have hWB := Set.mem_toFinset.mp hW\n    simp only [hWB, true_and]\n  have hcompl (W : Set (Fin n)) :\n      ({i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}.ncard : ℝ) =\n        (d : ℝ) - ({i : Fin d | k / 2 < (minimalFragment f i W).ncard}.ncard : ℝ) := by\n    have he : {i : Fin d | k / 2 < (minimalFragment f i W).ncard} =\n        {i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}ᶜ := by\n      ext i\n      simp\n    have hc := Set.ncard_add_ncard_compl\n      {i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}\n    rw [← he] at hc\n    have hcR : ({i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}.ncard : ℝ) +\n        ({i : Fin d | k / 2 < (minimalFragment f i W).ncard}.ncard : ℝ) = d := by\n      simpa only [Nat.cast_add, Nat.card_fin] using congrArg (fun z : ℕ ↦ (z : ℝ)) hc\n    linarith\n  rw [Set.toFinite_toFinset]\n  change ((d : ℝ) - N * (2 / q) ^ k) * (V.ncard.choose m : ℝ) ≤\n    ∑ W ∈ B.toFinset,\n      ({i : Fin d | (minimalFragment f i W).ncard ≤ k / 2}.ncard : ℝ)\n  simp_rw [hcompl]\n  rw [Finset.sum_sub_distrib, ← hpartition]\n  have hBcard : (B.toFinset.card : ℝ) = (V.ncard.choose m : ℝ) := by\n    rw [← Set.ncard_eq_toFinset_card', Set.ncard_powerset_ncard (Set.toFinite V) m]\n  simp only [Finset.sum_const, nsmul_eq_mul]\n  rw [hBcard]\n  nlinarith\ntheorem disjoint_union_pair_count (n a b : ℕ)\n    (P : Set (Set (Fin n) × Set (Fin n))) (G : Set (Set (Fin n)))\n    (hG : ∀ U ∈ G, U.ncard = a + b)\n    (hunion : ∀ p ∈ P, p.1 ∪ p.2 ∈ G)\n    (hcard : ∀ p ∈ P, p.1.ncard = a)\n    (hdis : ∀ p ∈ P, Disjoint p.1 p.2) :\n    (P.ncard : ℝ) ≤ (G.ncard : ℝ) * ((a + b).choose a : ℝ) := by\n  classical\n  letI := Fintype.ofFinite (Set (Fin n))\n  have hfiber (U : Set (Fin n)) (hU : U ∈ G) :\n      ({p | p ∈ P ∧ p.1 ∪ p.2 = U}.ncard : ℝ) ≤ ((a + b).choose a : ℝ) := by\n    have hrecover (p : Set (Fin n) × Set (Fin n)) (hp : p ∈ P)\n        (hpU : p.1 ∪ p.2 = U) : p.2 = U \\ p.1 := by\n      ext x\n      constructor\n      · intro hx\n        refine ⟨?_, fun hx₁ ↦ Set.disjoint_left.mp (hdis p hp) hx₁ hx⟩\n        rw [← hpU]\n        exact Or.inr hx\n      · rintro ⟨hxU, hx₁⟩\n        rw [← hpU] at hxU\n        exact hxU.resolve_left hx₁\n    have hc : {p | p ∈ P ∧ p.1 ∪ p.2 = U}.ncard ≤\n        {W : Set (Fin n) | W ⊆ U ∧ W.ncard = a}.ncard := by\n      apply Set.ncard_le_ncard_of_injOn Prod.fst\n      · intro p hp\n        refine ⟨?_, hcard p hp.1⟩\n        rw [← hp.2]\n        exact Set.subset_union_left\n      · intro p hp q hq hpq\n        apply Prod.ext hpq\n        rw [hrecover p hp.1 hp.2, hrecover q hq.1 hq.2, hpq]\n    rw [Set.ncard_powerset_ncard (Set.toFinite U) a, hG U hU] at hc\n    exact_mod_cast hc\n  simpa only [mul_one] using\n    ncard_mul_le_of_fiber_bounds P G (fun p ↦ p.1 ∪ p.2)\n      1 ((a + b).choose a : ℝ) hunion (by\n        intro U hU\n        simpa only [mul_one] using hfiber U hU)\ntheorem choose_block_identity (v m s : ℕ) :\n    (v.choose m : ℝ) * ((v - m).choose s : ℝ) =\n      (v.choose (m + s) : ℝ) * ((m + s).choose m : ℝ) := by\n  have h := Nat.choose_mul (n := v) (k := m + s) (s := m) (Nat.le_add_right m s)\n  simpa only [Nat.add_sub_cancel_left, Nat.cast_mul] using\n    congrArg (fun z : ℕ ↦ (z : ℝ)) h.symm\ntheorem zero_width_hitting (n d s : ℕ) (V : Set (Fin n))\n    (f : Fin d → Set (Fin n)) (N : ℝ) (hN : 0 ≤ N) (hdN : (d : ℝ) ≤ N)\n    (hf : ∀ i, (f i).ncard = 0) :\n    (d : ℝ) * (V.ncard.choose s : ℝ) ≤ N *\n      ({U : Set (Fin n) | U ⊆ V ∧ U.ncard = s ∧ ∃ i : Fin d, f i ⊆ U}.ncard : ℝ) := by\n  by_cases hd : d = 0\n  · subst d\n    simpa only [Nat.cast_zero, zero_mul] using\n      mul_nonneg hN (Nat.cast_nonneg\n        {U : Set (Fin n) | U ⊆ V ∧ U.ncard = s ∧ ∃ i : Fin 0, f i ⊆ U}.ncard :\n          (0 : ℝ) ≤ _)\n  · let i : Fin d := ⟨0, Nat.pos_of_ne_zero hd⟩\n    have hempty : f i = ∅ := (Set.ncard_eq_zero (Set.toFinite (f i))).mp (hf i)\n    have hG : {U : Set (Fin n) | U ⊆ V ∧ U.ncard = s ∧ ∃ i : Fin d, f i ⊆ U} =\n        {U : Set (Fin n) | U ⊆ V ∧ U.ncard = s} := by\n      ext U\n      constructor\n      · intro hU\n        exact ⟨hU.1, hU.2.1⟩\n      · intro hU\n        exact ⟨hU.1, hU.2, i, by rw [hempty]; exact Set.empty_subset U⟩\n    rw [hG, Set.ncard_powerset_ncard (Set.toFinite V) s]\n    exact mul_le_mul_of_nonneg_right hdN (Nat.cast_nonneg _)\ntheorem labelled_halving_hitting_step (n d w ℓ m : ℕ) (V : Set (Fin n))\n    (f : Fin d → Set (Fin n)) (κ N q : ℝ) (hκ : 0 < κ) (hN : 0 < N)\n    (hq : 2 ≤ q) (hw : 0 < w) (hV : 0 < V.ncard)\n    (hscale : q ^ 2 * (V.ncard : ℝ) ≤ (m : ℝ) * κ)\n    (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ w)\n    (hcode : ∀ U : Set (Fin n),\n      ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N)\n    (hchild : ∀ W ⊆ V, W.ncard = m → ∀ (d' : ℕ) (g : Fin d' → Set (Fin n)),\n      (∀ a, g a ⊆ V \\ W ∧ (g a).ncard ≤ w / 2) →\n      (∀ U : Set (Fin n), ({a : Fin d' | U ⊆ g a}.ncard : ℝ) * κ ^ U.ncard ≤ N) →\n      ((d' : ℝ) - N * (∑ j ∈ Finset.Icc 1 (w / 2), (2 / q) ^ j)) *\n          ((V \\ W).ncard.choose (ℓ * m) : ℝ) ≤ N *\n        ({U : Set (Fin n) | U ⊆ V \\ W ∧ U.ncard = ℓ * m ∧\n          ∃ a : Fin d', g a ⊆ U}.ncard : ℝ)) :\n    ((d : ℝ) - N * (∑ j ∈ Finset.Icc 1 w, (2 / q) ^ j)) *\n        (V.ncard.choose ((ℓ + 1) * m) : ℝ) ≤ N *\n      ({U : Set (Fin n) | U ⊆ V ∧ U.ncard = (ℓ + 1) * m ∧\n        ∃ i : Fin d, f i ⊆ U}.ncard : ℝ) := by\n  classical\n  letI := Fintype.ofFinite (Set (Fin n))\n  let B : Set (Set (Fin n)) := {W | W ⊆ V ∧ W.ncard = m}\n  let L (k : ℕ) : ℝ := ∑ j ∈ Finset.Icc 1 k, (2 / q) ^ j\n  choose dW gW eW hdata using\n    (fun W : Set (Fin n) ↦ retained_fragment_family n d w V W f κ N hκ.le hsys hcode)\n  have hdim (W : Set (Fin n)) :\n      dW W = {i : Fin d | (minimalFragment f i W).ncard ≤ w / 2}.ncard :=\n    (hdata W).2.1\n  let hit (W : Set (Fin n)) : Set (Set (Fin n)) :=\n    {U | U ⊆ V \\ W ∧ U.ncard = ℓ * m ∧ ∃ a : Fin (dW W), gW W a ⊆ U}\n  let H : Set (Set (Fin n) × Set (Fin n)) := {p | p.1 ∈ B ∧ p.2 ∈ hit p.1}\n  let G : Set (Set (Fin n)) :=\n    {U | U ⊆ V ∧ U.ncard = (ℓ + 1) * m ∧ ∃ i : Fin d, f i ⊆ U}\n  have hHsum : (H.ncard : ℝ) = ∑ W ∈ B.toFinset, ((hit W).ncard : ℝ) := by\n    rw [ncard_eq_sum_ncard_fibers H B.toFinset Prod.fst\n      (fun p hp ↦ Set.mem_toFinset.mpr hp.1)]\n    apply Finset.sum_congr rfl\n    intro W hW\n    change ({p : Set (Fin n) × Set (Fin n) |\n      (p.1 ∈ B ∧ p.2 ∈ hit p.1) ∧ p.1 = W}.ncard : ℝ) = _\n    rw [ncard_pair_fst_fiber (fun W U ↦ W ∈ B ∧ U ∈ hit W) W]\n    have hWB := Set.mem_toFinset.mp hW\n    simp only [hWB, true_and, Set.setOf_mem_eq]\n  have hBcard : (B.toFinset.card : ℝ) = (V.ncard.choose m : ℝ) := by\n    rw [← Set.ncard_eq_toFinset_card', Set.ncard_powerset_ncard (Set.toFinite V) m]\n  have havg : ((d : ℝ) - N * (2 / q) ^ w) * (V.ncard.choose m : ℝ) ≤\n      ∑ W ∈ B.toFinset, (dW W : ℝ) := by\n    simpa only [hdim, Set.toFinite_toFinset] using\n      retained_fragment_average n d w m V f κ N q hκ hN.le hq hV hscale hsys hcode\n  have hsum : (∑ W ∈ B.toFinset,\n      ((dW W : ℝ) - N * L (w / 2)) * ((V.ncard - m).choose (ℓ * m) : ℝ)) ≤\n      ∑ W ∈ B.toFinset, N * ((hit W).ncard : ℝ) := by\n    apply Finset.sum_le_sum\n    intro W hW\n    have hWB := Set.mem_toFinset.mp hW\n    have hc := hchild W hWB.1 hWB.2 (dW W) (gW W)\n      (hdata W).2.2.2.1 (hdata W).2.2.2.2.1\n    have hrem : (V \\ W).ncard = V.ncard - m := by\n      have hc := Set.ncard_sdiff_add_ncard_of_subset hWB.1\n      rw [hWB.2] at hc\n      omega\n    rw [hrem] at hc\n    exact hc\n  rw [← Finset.sum_mul, Finset.sum_sub_distrib, Finset.sum_const, nsmul_eq_mul,\n    hBcard, ← Finset.mul_sum, ← hHsum] at hsum\n  have hloss : L (w / 2) + (2 / q) ^ w ≤ L w :=\n    dyadic_loss_step w hw (2 / q) (div_nonneg (by norm_num) (by linarith))\n  have hloss_scaled := mul_le_mul_of_nonneg_left hloss hN.le\n  have hloss_scaled' := mul_le_mul_of_nonneg_left hloss_scaled\n    (Nat.cast_nonneg (V.ncard.choose m) : (0 : ℝ) ≤ V.ncard.choose m)\n  have hlower :\n      ((d : ℝ) - N * L w) * (V.ncard.choose m : ℝ) *\n          ((V.ncard - m).choose (ℓ * m) : ℝ) ≤ N * (H.ncard : ℝ) := by\n    apply le_trans ?_ hsum\n    apply mul_le_mul_of_nonneg_right ?_ (Nat.cast_nonneg _)\n    nlinarith [havg, hloss_scaled']\n  have htotal : (ℓ + 1) * m = m + ℓ * m := by ring\n  have hdis (p : Set (Fin n) × Set (Fin n)) (hp : p ∈ H) : Disjoint p.1 p.2 := by\n    exact Set.disjoint_left.mpr fun x hxW hxU ↦ (hp.2.1 hxU).2 hxW\n  have hHbound : (H.ncard : ℝ) ≤ (G.ncard : ℝ) * ((m + ℓ * m).choose m : ℝ) := by\n    apply disjoint_union_pair_count n m (ℓ * m) H G\n    · intro U hU\n      exact hU.2.1.trans htotal\n    · intro p hp\n      refine ⟨Set.union_subset hp.1.1 (fun x hx ↦ (hp.2.1 hx).1), ?_, ?_⟩\n      · rw [Set.ncard_union_eq (hdis p hp), hp.1.2, hp.2.2.1, htotal]\n      · obtain ⟨a, ha⟩ := hp.2.2.2\n        obtain ⟨i, hi⟩ := (hdata p.1).2.2.2.2.2 a\n        refine ⟨i, ?_⟩\n        intro x hx\n        rcases hi hx with hxg | hxW\n        · exact Or.inr (ha hxg)\n        · exact Or.inl hxW\n    · intro p hp\n      exact hp.1.2\n    · exact hdis\n  change ((d : ℝ) - N * L w) * (V.ncard.choose ((ℓ + 1) * m) : ℝ) ≤ N * (G.ncard : ℝ)\n  have hchoosepos : (0 : ℝ) < ((m + ℓ * m).choose m : ℝ) := by\n    exact_mod_cast Nat.choose_pos (Nat.le_add_right m (ℓ * m))\n  apply (mul_le_mul_iff_left₀ hchoosepos).mp\n  calc\n    (((d : ℝ) - N * L w) * (V.ncard.choose ((ℓ + 1) * m) : ℝ)) *\n        ((m + ℓ * m).choose m : ℝ) =\n        ((d : ℝ) - N * L w) * (V.ncard.choose m : ℝ) *\n          ((V.ncard - m).choose (ℓ * m) : ℝ) := by\n      rw [htotal, mul_assoc, ← choose_block_identity]\n      ring\n    _ ≤ N * (H.ncard : ℝ) := hlower\n    _ ≤ N * ((G.ncard : ℝ) * ((m + ℓ * m).choose m : ℝ)) :=\n      mul_le_mul_of_nonneg_left hHbound hN.le\n    _ = (N * (G.ncard : ℝ)) * ((m + ℓ * m).choose m : ℝ) := by ring\ntheorem labelled_halving_hitting (n d w ℓ m : ℕ) (V : Set (Fin n))\n    (f : Fin d → Set (Fin n)) (κ N q : ℝ) (hκ : 0 < κ) (hN : 0 < N)\n    (hq : 2 ≤ q) (hm : 0 < m) (hroom : ℓ * m ≤ V.ncard) (hw : w < 2 ^ ℓ)\n    (hscale : q ^ 2 * (V.ncard : ℝ) ≤ (m : ℝ) * κ)\n    (hsys : ∀ i, f i ⊆ V ∧ (f i).ncard ≤ w)\n    (hcode : ∀ U : Set (Fin n),\n      ({i : Fin d | U ⊆ f i}.ncard : ℝ) * κ ^ U.ncard ≤ N) :\n    ((d : ℝ) - N * (∑ j ∈ Finset.Icc 1 w, (2 / q) ^ j)) *\n        (V.ncard.choose (ℓ * m) : ℝ) ≤ N *\n      ({U : Set (Fin n) | U ⊆ V ∧ U.ncard = ℓ * m ∧\n        ∃ i : Fin d, f i ⊆ U}.ncard : ℝ) := by\n  induction ℓ generalizing d w V f with\n  | zero =>\n    have hwzero : w = 0 := by simpa using hw\n    subst w\n    have hdN : (d : ℝ) ≤ N := by simpa using hcode ∅\n    simpa using zero_width_hitting n d 0 V f N hN.le hdN\n      (fun i ↦ Nat.eq_zero_of_le_zero (hsys i).2)\n  | succ ℓ ih =>\n    by_cases hwzero : w = 0\n    · subst w\n      have hdN : (d : ℝ) ≤ N := by simpa using hcode ∅\n      simpa using zero_width_hitting n d ((ℓ + 1) * m) V f N hN.le hdN\n        (fun i ↦ Nat.eq_zero_of_le_zero (hsys i).2)\n    · have hV : 0 < V.ncard := by\n        have hmle : m ≤ (ℓ + 1) * m := by rw [Nat.add_mul]; omega\n        exact hm.trans_le (hmle.trans hroom)\n      apply labelled_halving_hitting_step n d w ℓ m V f κ N q hκ hN hq\n        (Nat.pos_of_ne_zero hwzero) hV hscale hsys hcode\n      intro W hWV hWcard d' g hgsys hgcode\n      apply ih (d := d') (w := w / 2) (V := V \\ W) (f := g)\n      · have hc := Set.ncard_sdiff_add_ncard_of_subset hWV\n        rw [hWcard] at hc\n        rw [Nat.succ_mul] at hroom\n        omega\n      · rw [pow_succ] at hw\n        omega\n      · apply le_trans _ hscale\n        apply mul_le_mul_of_nonneg_left _ (sq_nonneg q)\n        exact_mod_cast Set.ncard_le_ncard (Set.sdiff_subset : V \\ W ⊆ V)\n      · exact hgsys\n      · exact hgcode\ntheorem spread_parameter_le_ground_size (n : ℕ) (ℋ : Set (Set (Fin n)))\n    (κ : ℝ) (hκ : 0 ≤ κ) (hne : ℋ.Nonempty) (hempty : (∅ : Set (Fin n)) ∉ ℋ)\n    (hcode : ∀ U : Set (Fin n),\n      ({A : Set (Fin n) | A ∈ ℋ ∧ U ⊆ A}.ncard : ℝ) * κ ^ U.ncard ≤\n        (ℋ.ncard : ℝ)) : κ ≤ n := by\n  classical\n  letI := Fintype.ofFinite ℋ\n  have hA (A : ℋ) : (A : Set (Fin n)).Nonempty := by\n    apply Set.nonempty_iff_ne_empty.mpr\n    intro he\n    exact hempty (he ▸ A.property)\n  let p (A : ℋ) : Fin n := (hA A).choose\n  have hp (A : ℋ) : p A ∈ (A : Set (Fin n)) := (hA A).choose_spec\n  have htotal := ncard_mul_le_of_fiber_bounds\n    (Set.univ : Set ℋ) (Set.univ : Set (Fin n)) p κ (ℋ.ncard : ℝ)\n    (fun _ _ ↦ Set.mem_univ _) (by\n      intro x _\n      have hfib : {A : ℋ | A ∈ Set.univ ∧ p A = x}.ncard ≤\n          {A : Set (Fin n) | A ∈ ℋ ∧ ({x} : Set (Fin n)) ⊆ A}.ncard := by\n        apply Set.ncard_le_ncard_of_injOn (fun A : ℋ ↦ A.val)\n        · intro A hAx\n          refine ⟨A.property, Set.singleton_subset_iff.mpr ?_⟩\n          exact hAx.2 ▸ hp A\n        · intro A _ B _ hAB\n          exact Subtype.ext hAB\n      have hmul := mul_le_mul_of_nonneg_right\n        (show ({A : ℋ | A ∈ Set.univ ∧ p A = x}.ncard : ℝ) ≤\n          ({A : Set (Fin n) | A ∈ ℋ ∧ ({x} : Set (Fin n)) ⊆ A}.ncard : ℝ)\n          by exact_mod_cast hfib) hκ\n      exact hmul.trans (by simpa using hcode {x}))\n  have hsource : (Set.univ : Set ℋ).ncard = ℋ.ncard := by\n    rw [Set.ncard_univ, Nat.card_coe_set_eq]\n  have htarget : (Set.univ : Set (Fin n)).ncard = n := by simp\n  rw [hsource, htarget] at htotal\n  have hmass : (0 : ℝ) < (ℋ.ncard : ℝ) := by\n    exact_mod_cast (Set.ncard_pos).mpr hne\n  nlinarith\ntheorem spread_matching_block_parameters (r n ℓ : ℕ) (κ : ℝ)\n    (hr : 3 ≤ r) (hℓ : 0 < ℓ) (hκ : 0 < κ) (hκn : κ ≤ n)\n    (hlarge : 260 * (r : ℝ) ^ 3 * (ℓ : ℝ) ≤ κ) :\n    ∃ m : ℕ, 0 < m ∧ r * (ℓ * m) ≤ n ∧ ℓ * m ≤ n ∧\n      (8 * (r : ℝ)) ^ 2 * (n : ℝ) ≤ (m : ℝ) * κ := by\n  have hrR : (3 : ℝ) ≤ r := by exact_mod_cast hr\n  have hℓR : (1 : ℝ) ≤ ℓ := by exact_mod_cast hℓ\n  have hn : (0 : ℝ) < n := hκ.trans_le hκn\n  let x : ℝ := 64 * (r : ℝ) ^ 2 * (n : ℝ) / κ\n  have hx : 0 < x := by dsimp [x]; positivity\n  let m : ℕ := Nat.ceil x\n  have hm : 0 < m := Nat.ceil_pos.mpr hx\n  have hlower : 64 * (r : ℝ) ^ 2 * (n : ℝ) ≤ (m : ℝ) * κ := by\n    exact (div_le_iff₀ hκ).mp (Nat.le_ceil x)\n  have hupper : (m : ℝ) * κ ≤ 65 * (r : ℝ) ^ 2 * (n : ℝ) := by\n    have hmceil : (m : ℝ) < x + 1 := Nat.ceil_lt_add_one hx.le\n    have hceil := (mul_lt_mul_iff_left₀ hκ).mpr hmceil\n    have hxeq : x * κ = 64 * (r : ℝ) ^ 2 * (n : ℝ) := by\n      dsimp [x]\n      exact div_mul_cancel₀ _ hκ.ne'\n    have hr2 : (1 : ℝ) ≤ (r : ℝ) ^ 2 := by nlinarith\n    have hlast := mul_le_mul_of_nonneg_right hr2 hn.le\n    nlinarith\n  have hcoef : 65 * (r : ℝ) ^ 3 * (ℓ : ℝ) ≤ κ := by\n    have hnonneg : (0 : ℝ) ≤ (r : ℝ) ^ 3 * (ℓ : ℝ) := by positivity\n    linarith\n  have hroomR : (r : ℝ) * ((ℓ : ℝ) * (m : ℝ)) ≤ n := by\n    apply (mul_le_mul_iff_left₀ hκ).mp\n    calc\n      (r : ℝ) * ((ℓ : ℝ) * (m : ℝ)) * κ =\n          ((r : ℝ) * (ℓ : ℝ)) * ((m : ℝ) * κ) := by ring\n      _ ≤ ((r : ℝ) * (ℓ : ℝ)) * (65 * (r : ℝ) ^ 2 * (n : ℝ)) :=\n        mul_le_mul_of_nonneg_left hupper (by positivity)\n      _ = (65 * (r : ℝ) ^ 3 * (ℓ : ℝ)) * (n : ℝ) := by ring\n      _ ≤ κ * (n : ℝ) := mul_le_mul_of_nonneg_right hcoef hn.le\n      _ = (n : ℝ) * κ := by ring\n  have hroom : r * (ℓ * m) ≤ n := by exact_mod_cast hroomR\n  refine ⟨m, hm, hroom, ?_, ?_⟩\n  · exact (Nat.le_mul_of_pos_left (ℓ * m) (by omega : 0 < r)).trans hroom\n  · nlinarith [hlower]\ntheorem matching_of_dense_hitting_sets (n r s : ℕ) (ℋ : Set (Set (Fin n)))\n    (hempty : (∅ : Set (Fin n)) ∉ ℋ) (hroom : r * s ≤ n)\n    (hdense : (r : ℝ) * ((n.choose s : ℝ) -\n      ({U : Set (Fin n) | U.ncard = s ∧ ∃ A ∈ ℋ, A ⊆ U}.ncard : ℝ)) <\n        (n.choose s : ℝ)) :\n    ∃ P ⊆ ℋ, P.ncard = r ∧ P.Pairwise Disjoint := by\n  classical\n  obtain ⟨B, hB, hBdis⟩ := disjoint_blocks_from_dense_family n r s\n    {U : Set (Fin n) | U.ncard = s ∧ ∃ A ∈ ℋ, A ⊆ U}\n    hroom (fun U hU ↦ hU.1) hdense\n  choose A hA hAsub using fun i ↦ (hB i).2\n  have hAdis (i j : Fin r) (hij : i ≠ j) : Disjoint (A i) (A j) :=\n    (hBdis i j hij).mono (hAsub i) (hAsub j)\n  have hAinj : Function.Injective A := by\n    intro i j heq\n    by_contra hij\n    have hself : Disjoint (A i) (A i) := by simpa only [← heq] using hAdis i j hij\n    have hzero : A i = ∅ := disjoint_self.mp hself\n    exact hempty (hzero ▸ hA i)\n  refine ⟨Set.range A, ?_, ?_, ?_⟩\n  · rintro _ ⟨i, rfl⟩\n    exact hA i\n  · rw [Set.ncard_range_of_injective hAinj]\n    simp\n  · rintro _ ⟨i, rfl⟩ _ ⟨j, rfl⟩ hne\n    exact hAdis i j (fun hij ↦ hne (congrArg A hij))\ntheorem geometric_spread_loss (r w : ℕ) (hr : 3 ≤ r) :\n    (r : ℝ) * (∑ j ∈ Finset.Icc 1 w, (2 / (8 * (r : ℝ))) ^ j) ≤ 1 / 2 := by\n  have hrR : (3 : ℝ) ≤ r := by exact_mod_cast hr\n  have hrpos : (0 : ℝ) < r := by linarith\n  let z : ℝ := 2 / (8 * (r : ℝ))\n  have hz : 0 ≤ z := by dsimp [z]; positivity\n  have hzhalf : z ≤ 1 / 2 := by\n    dsimp [z]\n    apply (div_le_iff₀ (by positivity : (0 : ℝ) < 8 * (r : ℝ))).mpr\n    linarith\n  have hzlt : z < 1 := by linarith\n  have hsum : (∑ j ∈ Finset.Icc 1 w, z ^ j) ≤ z / (1 - z) := by\n    rw [← Finset.Ico_add_one_right_eq_Icc]\n    simpa only [pow_one] using\n      (geom_sum_Ico_le_of_lt_one (m := 1) (n := w + 1) hz hzlt)\n  have hratio : z / (1 - z) ≤ 2 * z := by\n    apply (div_le_iff₀ (by linarith : 0 < 1 - z)).mpr\n    nlinarith\n  have hrz : (r : ℝ) * (2 * z) = 1 / 2 := by\n    dsimp [z]\n    field_simp\n    <;> ring\n  calc\n    (r : ℝ) * (∑ j ∈ Finset.Icc 1 w, z ^ j) ≤ (r : ℝ) * (2 * z) :=\n      mul_le_mul_of_nonneg_left (hsum.trans hratio) hrpos.le\n    _ = 1 / 2 := hrz\ntheorem spread_hitting_density (r n w ℓ m : ℕ) (ℋ : Set (Set (Fin n)))\n    (κ : ℝ) (hr : 3 ≤ r) (hκ : 0 < κ) (hne : ℋ.Nonempty)\n    (hm : 0 < m) (hroom : ℓ * m ≤ n) (hw : w < 2 ^ ℓ)\n    (hscale : (8 * (r : ℝ)) ^ 2 * (n : ℝ) ≤ (m : ℝ) * κ)\n    (hsys : Set.IsSystem w ℋ)\n    (hcode : ∀ U : Set (Fin n),\n      ({A : Set (Fin n) | A ∈ ℋ ∧ U ⊆ A}.ncard : ℝ) * κ ^ U.ncard ≤\n        (ℋ.ncard : ℝ)) :\n    (r : ℝ) * ((n.choose (ℓ * m) : ℝ) -\n      ({U : Set (Fin n) | U.ncard = ℓ * m ∧ ∃ A ∈ ℋ, A ⊆ U}.ncard : ℝ)) <\n        (n.choose (ℓ * m) : ℝ) := by\n  classical\n  letI := Fintype.ofFinite ℋ\n  let b : Fin (Fintype.card ℋ) ≃ ℋ := (Fintype.equivFin ℋ).symm\n  let f (i : Fin (Fintype.card ℋ)) : Set (Fin n) := (b i).val\n  have hd : Fintype.card ℋ = ℋ.ncard := by\n    rw [← Nat.card_eq_fintype_card, Nat.card_coe_set_eq]\n  have hmass : (0 : ℝ) < (ℋ.ncard : ℝ) := by\n    exact_mod_cast (Set.ncard_pos).mpr hne\n  have henum (U : Set (Fin n)) :\n      {i : Fin (Fintype.card ℋ) | U ⊆ f i}.ncard =\n        {A : Set (Fin n) | A ∈ ℋ ∧ U ⊆ A}.ncard := by\n    apply Set.ncard_congr (fun i _ ↦ f i)\n    · intro i hi\n      exact ⟨(b i).property, hi⟩\n    · intro i j _ _ heq\n      exact b.injective (Subtype.ext heq)\n    · intro A hA\n      obtain ⟨i, hi⟩ := b.surjective ⟨A, hA.1⟩\n      have hfi : f i = A := congrArg Subtype.val hi\n      exact ⟨i, by simpa only [Set.mem_setOf_eq, hfi] using hA.2, hfi⟩\n  have hVcard : (Set.univ : Set (Fin n)).ncard = n := by simp\n  have hgood :\n      {U : Set (Fin n) | U ⊆ Set.univ ∧ U.ncard = ℓ * m ∧\n        ∃ i : Fin (Fintype.card ℋ), f i ⊆ U} =\n      {U : Set (Fin n) | U.ncard = ℓ * m ∧ ∃ A ∈ ℋ, A ⊆ U} := by\n    ext U\n    constructor\n    · rintro ⟨_, hsize, i, hi⟩\n      exact ⟨hsize, f i, (b i).property, hi⟩\n    · rintro ⟨hsize, A, hA, hAU⟩\n      obtain ⟨i, hi⟩ := b.surjective ⟨A, hA⟩\n      have hfi : f i = A := congrArg Subtype.val hi\n      exact ⟨Set.subset_univ U, hsize, i, hfi ▸ hAU⟩\n  have hrR : (3 : ℝ) ≤ r := by exact_mod_cast hr\n  have hhit := labelled_halving_hitting n (Fintype.card ℋ) w ℓ m Set.univ f κ\n    (ℋ.ncard : ℝ) (8 * (r : ℝ)) hκ hmass (by linarith) hm\n    (by simpa only [hVcard] using hroom) hw\n    (by simpa only [hVcard] using hscale)\n    (fun i ↦ ⟨Set.subset_univ _, hsys _ (b i).property⟩)\n    (fun U ↦ by rw [henum U]; exact hcode U)\n  rw [hVcard, hgood, hd] at hhit\n  let E : ℝ := ∑ j ∈ Finset.Icc 1 w, (2 / (8 * (r : ℝ))) ^ j\n  let B : ℝ := (n.choose (ℓ * m) : ℝ)\n  let G : ℝ :=\n    ({U : Set (Fin n) | U.ncard = ℓ * m ∧ ∃ A ∈ ℋ, A ⊆ U}.ncard : ℝ)\n  have hnormalized : (1 - E) * B ≤ G := by\n    apply (mul_le_mul_iff_right₀ hmass).mp\n    change (ℋ.ncard : ℝ) * ((1 - E) * B) ≤ (ℋ.ncard : ℝ) * G\n    change ((ℋ.ncard : ℝ) - (ℋ.ncard : ℝ) * E) * B ≤\n      (ℋ.ncard : ℝ) * G at hhit\n    nlinarith only [hhit]\n  have hB : 0 < B := by\n    change (0 : ℝ) < (n.choose (ℓ * m) : ℝ)\n    exact_mod_cast Nat.choose_pos hroom\n  have hloss : (r : ℝ) * E ≤ 1 / 2 := geometric_spread_loss r w hr\n  have hbad : (r : ℝ) * (B - G) ≤ ((r : ℝ) * E) * B := by\n    have hdiff : B - G ≤ E * B := by nlinarith only [hnormalized]\n    have hmul := mul_le_mul_of_nonneg_left hdiff (by positivity : (0 : ℝ) ≤ r)\n    nlinarith only [hmul]\n  have hbound := mul_le_mul_of_nonneg_right hloss hB.le\n  change (r : ℝ) * (B - G) < B\n  nlinarith only [hbad, hbound, hB]\ntheorem dyadic_spread_matching (r n w ℓ : ℕ) (ℋ : Set (Set (Fin n))) (κ : ℝ)\n    (hr : 3 ≤ r) (hw : 0 < w) (hdyadic : w < 2 ^ ℓ) (hκ : 0 < κ)\n    (hlarge : 260 * (r : ℝ) ^ 3 * (ℓ : ℝ) ≤ κ) (hne : ℋ.Nonempty)\n    (hempty : (∅ : Set (Fin n)) ∉ ℋ) (hsys : Set.IsSystem w ℋ)\n    (hcode : ∀ U : Set (Fin n),\n      ({A : Set (Fin n) | A ∈ ℋ ∧ U ⊆ A}.ncard : ℝ) * κ ^ U.ncard ≤\n        (ℋ.ncard : ℝ)) :\n    ∃ P ⊆ ℋ, P.ncard = r ∧ P.Pairwise Disjoint := by\n  have hℓ : 0 < ℓ := by\n    by_contra hzero\n    have heq : ℓ = 0 := by omega\n    simp only [heq, pow_zero] at hdyadic\n    omega\n  have hκn := spread_parameter_le_ground_size n ℋ κ hκ.le hne hempty hcode\n  obtain ⟨m, hm, hroom, hroom', hscale⟩ :=\n    spread_matching_block_parameters r n ℓ κ hr hℓ hκ hκn hlarge\n  exact matching_of_dense_hitting_sets n r (ℓ * m) ℋ hempty hroom\n    (spread_hitting_density r n w ℓ m ℋ κ hr hκ hne hm hroom' hdyadic hscale hsys hcode)\ntheorem exists_uniform_sunflower_constant :\n    ∃ c : ℝ, 0 < c ∧ ∀ (r : ℕ), 3 ≤ r →\n      ∀ (n : ℕ) (ℱ : Set (Set (Fin n))) (w : ℕ), 2 ≤ w → Set.IsSystem w ℱ →\n        _root_.ImprovedBoundsSunflowerLemma.lowerBound r c w ≤ (ℱ.ncard : ℝ) →\n        ∃ S ⊆ ℱ, Set.IsSunflower r S := by\n  refine ⟨40000, by norm_num, ?_⟩\n  intro r hr n ℱ w hw hsys hsize\n  let ℓ : ℕ := Nat.log 2 w + 1\n  let κ : ℝ := 520 * (r : ℝ) ^ 3 * (ℓ : ℝ)\n  obtain ⟨hκ, hthreshold, hdyadic⟩ := scalar_threshold_comparison r w hr hw\n  change 2 ≤ κ at hκ\n  change κ < 40000 * (r : ℝ) ^ 3 * Real.logb (1.9 : ℝ) (w : ℝ) *\n    Real.logb (1.9 : ℝ) (Real.logb (1.9 : ℝ) (w : ℝ)) at hthreshold\n  change w < 2 ^ ℓ at hdyadic\n  have hκpos : 0 < κ := by linarith\n  have hstrict : κ ^ w < (ℱ.ncard : ℝ) := by\n    apply lt_of_lt_of_le ?_ hsize\n    exact pow_lt_pow_left₀ hthreshold hκpos.le (by omega : w ≠ 0)\n  obtain ⟨T, ℋ, hne, hempty, hsysH, hprop, hcode⟩ :=\n    extract_spread_petals n w ℱ κ hκ hsys hstrict\n  have hscale : 260 * (r : ℝ) ^ 3 * (ℓ : ℝ) ≤ κ / 2 := by\n    dsimp [κ]\n    ring_nf\n    exact le_rfl\n  obtain ⟨P, hPH, hcard, hdis⟩ :=\n    dyadic_spread_matching r n w ℓ ℋ (κ / 2) hr (by omega) hdyadic\n      (div_pos hκpos (by norm_num)) hscale hne hempty hsysH hcode\n  exact sunflower_of_disjoint_petals n r ℱ T P (by omega) hcard hdis\n    (fun A hA ↦ hprop A (hPH hA))\ntheorem chosen_constant_sunflower\n    (r : ℕ) (hr : 3 ≤ r) (X : Type*) [Finite X] (ℱ : Set (Set X)) (w : ℕ)\n    (hw : 2 ≤ w) (hℱ₁ : Set.IsSystem w ℱ)\n    (hℱ₂ : _root_.ImprovedBoundsSunflowerLemma.lowerBound r\n      (Classical.choose Submission.Helpers.exists_uniform_sunflower_constant) w ≤\n        (ℱ.ncard : ℝ)) :\n    ∃ S ⊆ ℱ, Set.IsSunflower r S := by\n  exact transfer_from_numbered_ground_sets\n    (Classical.choose exists_uniform_sunflower_constant)\n    (Classical.choose_spec exists_uniform_sunflower_constant).2\n    r hr X ℱ w hw hℱ₁ hℱ₂\nend Submission.Helpers\n"},{"name":"Submission.lean","path":"submitted/annals_improved_bounds_sunflower_lemma/Submission.lean","sha256":"5452139451a7e52fdc601cc3908dad70bc30ee7980fc686c1adc44cb39679a87","recordSource":true,"declarations":[{"id":"declaration:5452139451a7e52fdc601cc3908dad70bc30ee7980fc686c1adc44cb39679a87:855","name":"Submission.ImprovedBoundsSunflowerLemma.C","kind":"definition","type":"C : ℝ","line":42,"endLine":42,"references":[],"steps":[{"id":"proof-step:5452139451a7e52fdc601cc3908dad70bc30ee7980fc686c1adc44cb39679a87:867","line":42,"endLine":43,"code":" Classical.choose Helpers.exists_uniform_sunflower_constant\n\n"}]},{"id":"declaration:5452139451a7e52fdc601cc3908dad70bc30ee7980fc686c1adc44cb39679a87:1192","name":"Submission.ImprovedBoundsSunflowerLemma.theorem_1_4","kind":"theorem","type":"theorem_1_4 (r : ℕ) (hr : r ≥ 3) (X : Type*) [Finite X] (ℱ : Set (Set X)) (w : ℕ) (hw : w ≥ 2) (hℱ₁ : ℱ.IsSystem w) (hℱ₂ : ℱ.ncard ≥ lowerBound r C w) : ∃ S ⊆ ℱ, S.IsSunflower r","line":52,"endLine":55,"references":["declaration:5452139451a7e52fdc601cc3908dad70bc30ee7980fc686c1adc44cb39679a87:855"],"steps":[{"id":"proof-step:5452139451a7e52fdc601cc3908dad70bc30ee7980fc686c1adc44cb39679a87:1392","line":54,"endLine":56,"code":" by\n  exact Helpers.chosen_constant_sunflower r hr X ℱ w hw hℱ₁ hℱ₂\n\n"}]}],"code":"/-\nCopyright (c) 2026 Justus Springer. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Justus Springer\n-/\n\nimport Mathlib.Analysis.SpecialFunctions.Log.Base\nimport Submission.Helpers\nimport ChallengeDeps\n/-!\n# Main Statement from Improved bounds for the sunflower lemma\n\nWe formalise the statement of the main result from R. Alweiss, S. Lovett, K. Wu, and J. Zhang,\n`Improved bounds for the sunflower lemma`, Annals of Math, 194 (3) 2021.\n-/\n\n\nnamespace Submission\n\nopen _root_.ImprovedBoundsSunflowerLemma\nopen _root_.Set\nset_option autoImplicit false\n\nnamespace Set\n\nvariable {X : Type*}\n\n\n\n\n\nend Set\n\nnamespace ImprovedBoundsSunflowerLemma\n\nopen Real\n\n\n\n/-- The absolute constant `C` in Theorem 1.4. Although not explicitly stated in the paper,\nthe constant `C` doesn't depend on `r`. -/\nnoncomputable def C : ℝ := Classical.choose Helpers.exists_uniform_sunflower_constant\n\n/--\nStatement of Theorem 1.4 (Main theorem, sunflowers):\n\nLet `r ≥ 3`. For some constant `C`, any `w`-set system `F` of size\n`|F| ≥ (C * r ^ 3 * log w * log log w) ^ w` contains an `r`-sunflower.\n\nNote: We require `w ≥ 2`, as the paper assumes `log log w > 0`.\n-/\ntheorem theorem_1_4 (r : ℕ) (hr : r ≥ 3) (X : Type*) [Finite X] (ℱ : Set (Set X)) (w : ℕ)\n      (hw : w ≥ 2) (hℱ₁ : ℱ.IsSystem w) (hℱ₂ : ℱ.ncard ≥ lowerBound r C w) :\n      ∃ S ⊆ ℱ, S.IsSunflower r := by\n  exact Helpers.chosen_constant_sunflower r hr X ℱ w hw hℱ₁ hℱ₂\n\nend ImprovedBoundsSunflowerLemma\n\nend Submission\n"}]}};
